const BUNPO_CATEGORIES=[{"id":"dasar","name":"Dasar kalimat","symbol":"あ","color":"lavender","description":"Sifat, kata kerja, dan keberadaan"},{"id":"partikel","name":"Partikel","symbol":"は","color":"mint","description":"Hubungkan kata dengan tepat"},{"id":"tanya","name":"Bertanya & menunjuk","symbol":"？","color":"peach","description":"Temukan informasi yang kamu cari"},{"id":"rangkaian","name":"Merangkai kalimat","symbol":"つ","color":"blue","description":"Urutan dan keterangan yang menyatu"},{"id":"ungkapan","name":"Keinginan & interaksi","symbol":"話","color":"pink","description":"Meminta, mengajak, memberi, dan bercerita"},{"id":"penghubung","name":"Alasan & penghubung","symbol":"結","color":"lilac","description":"Karena, tetapi, dan kalau begitu"},{"id":"keterangan","name":"Kata keterangan","symbol":"時","color":"peach","description":"Derajat, frekuensi, waktu, dan cara"},{"id":"perubahan","name":"Cara & perubahan","symbol":"変","color":"mint","description":"Menjadi, membuat, dan memilih"},{"id":"waktu","name":"Waktu & tujuan","symbol":"前","color":"blue","description":"Sebelum, sesudah, dan pergi untuk"},{"id":"perbandingan","name":"Perbandingan","symbol":"比","color":"lavender","description":"Lebih, mana yang lebih, dan paling"},{"id":"kemampuan","name":"Kegiatan & kemampuan","symbol":"可","color":"pink","description":"Membendakan kegiatan dan menyatakan bisa"}];
const BUNPO_DATA=[{"id":"i-adjective","category":"dasar","subcategory":"Kata sifat","sourcePages":[2],"title":"Kata sifat-i","kana":"いけいようし","romaji":"i keiyoushi","meaning":"Menyatakan sifat dan mengubah waktunya","explanation":"Kata sifat-i dapat menjadi predikat dengan tambahan です. Untuk negatif dan lampau, ubah akhiran い pada kata sifatnya. Bentuk lampau tidak dibuat dengan menempelkan でした setelah kata sifat-i.","patterns":["Sifat-i + です","Buang い + くないです","Buang い + かったです","Buang い + くなかったです"],"note":"Bentuk negatif sopan lain: ～くありません dan ～くありませんでした. Kata きれい termasuk sifat-na meskipun berakhir dengan bunyi i.","examples":[{"jp":"この本はおもしろいです。","kana":"この ほん は おもしろいです。","meaning":"Buku ini menarik."},{"jp":"昨日は寒くなかったです。","kana":"きのう は さむくなかったです。","meaning":"Kemarin tidak dingin."}],"mistake":{"wrong":"おもしろいでした。","correct":"おもしろかったです。","why":"Lampau sifat-i memakai ～かったです, bukan ～いでした。"},"table":{"headers":["Makna","Bentuk"],"rows":[["Sekarang","おもしろいです"],["Negatif","おもしろくないです"],["Lampau","おもしろかったです"],["Negatif lampau","おもしろくなかったです"]]},"order":1,"level":"N5","enrichment":false,"check":{"prompt":"Bagaimana mengatakan “Kemarin dingin”?","options":["昨日は寒かったです。","昨日は寒いでした。"],"answer":0,"explanation":"Sifat-i berubah menjadi ～かったです untuk lampau."}},{"id":"ii","category":"dasar","subcategory":"Kata sifat","sourcePages":[2],"title":"いい → よい","kana":"いい・よい","romaji":"ii / yoi","meaning":"Perubahan khusus kata “baik”","explanation":"いい dan よい sama-sama berarti baik. Saat いい diubah ke bentuk negatif, lampau, atau penghubung, gunakan dasar よ. Bentuk いい tetap dipakai dalam kalimat positif sekarang.","patterns":["いいです → よくないです","いいです → よかったです","いいです → よくなかったです","いい → よくて"],"note":"かっこいい mengikuti perubahan yang sama: かっこよかったです (dulu/kondisi tadi keren).","examples":[{"jp":"このかばんはいいです。","kana":"この かばん は いいです。","meaning":"Tas ini bagus."},{"jp":"昨日の天気はよかったです。","kana":"きのう の てんき は よかったです。","meaning":"Cuaca kemarin bagus."}],"mistake":{"wrong":"いいかったです。","correct":"よかったです。","why":"Dasar perubahan いい adalah よ, sehingga bentuk lampaunya よかったです。"},"order":2,"level":"N5","enrichment":false},{"id":"na-adjective","category":"dasar","subcategory":"Kata sifat","sourcePages":[3],"title":"Kata sifat-na","kana":"なけいようし","romaji":"na keiyoushi","meaning":"Sifat seperti tenang, indah, dan praktis","explanation":"Sifat-na memakai です saat menjadi predikat. Untuk negatif, gunakan ではありません atau じゃないです. Akhiran な digunakan ketika sifat langsung menerangkan kata benda, bukan sebelum です.","patterns":["Sifat-na + です","Sifat-na + じゃないです","Sifat-na + でした","Sifat-na + じゃなかったです"],"note":"では lebih formal daripada じゃ. きれい (indah/bersih), 静か (tenang), dan 好き (suka) termasuk kelompok ini.","examples":[{"jp":"この部屋はきれいです。","kana":"この へや は きれいです。","meaning":"Kamar ini bersih."},{"jp":"昨日は暇じゃなかったです。","kana":"きのう は ひま じゃ なかったです。","meaning":"Kemarin saya tidak senggang."}],"mistake":{"wrong":"きれいくないです。","correct":"きれいじゃないです。","why":"きれい adalah sifat-na; tidak berubah menjadi ～くない。"},"table":{"headers":["Makna","Bentuk"],"rows":[["Sekarang","きれいです"],["Negatif","きれいではありません"],["Lampau","きれいでした"],["Negatif lampau","きれいじゃなかったです"]]},"order":3,"level":"N5","enrichment":false,"check":{"prompt":"Pilih “Kamar ini tidak bersih”.","options":["この部屋はきれいくないです。","この部屋はきれいじゃないです。"],"answer":1,"explanation":"きれい adalah sifat-na, jadi gunakan じゃないです."}},{"id":"verb-forms","category":"dasar","subcategory":"Kata kerja","sourcePages":[3],"title":"Bentuk sopan & biasa","kana":"ます・ません・ました・ませんでした","romaji":"masu / masen / mashita / masen deshita","meaning":"Mengenali perubahan kata kerja","explanation":"Bentuk ～ます dipakai untuk kalimat sopan. ～ません menyatakan negatif, ～ました lampau, dan ～ませんでした negatif lampau. Bentuk biasa sering muncul sebelum pola lain seperti とき atau saat menerangkan kata benda.","patterns":["～ます → ～ません","～ます → ～ました","～ます → ～ませんでした"],"note":"Bentuk biasa tidak selalu cukup dibuat dengan membuang ます. Kenali kelompok kata kerjanya; する dan 来る memiliki perubahan khusus. ある menjadi ない dalam bentuk biasa negatif.","examples":[{"jp":"今日は勉強します。","kana":"きょう は べんきょうします。","meaning":"Hari ini saya belajar."},{"jp":"昨日は勉強しませんでした。","kana":"きのう は べんきょうしませんでした。","meaning":"Kemarin saya tidak belajar."}],"table":{"headers":["Sopan / biasa","Negatif","Lampau","Negatif lampau"],"rows":[["あります / ある","ありません / ない","ありました / あった","ありませんでした / なかった"],["します / する","しません / しない","しました / した","しませんでした / しなかった"],["来ます / くる","来ません / こない","来ました / きた","来ませんでした / こなかった"]]},"order":4,"level":"N5","enrichment":false},{"id":"noun-modifiers","category":"dasar","subcategory":"Frasa benda","sourcePages":[4],"title":"Sifat + kata benda","kana":"い・な ＋ めいし","romaji":"i / na + meishi","meaning":"Menerangkan benda secara langsung","explanation":"Dalam bahasa Jepang, keterangan diletakkan sebelum benda yang diterangkan. Sifat-i langsung menempel pada kata benda. Sifat-na memerlukan な di antaranya.","patterns":["Sifat-i + kata benda","Sifat-na + な + kata benda"],"note":"Jangan menambahkan の setelah sifat-i. Bandingkan 高い山 (gunung tinggi) dan きれいな海 (laut yang indah).","examples":[{"jp":"高い山が見えます。","kana":"たかい やま が みえます。","meaning":"Terlihat gunung yang tinggi."},{"jp":"静かな部屋で勉強します。","kana":"しずかな へや で べんきょうします。","meaning":"Saya belajar di kamar yang tenang."}],"mistake":{"wrong":"きれい海","correct":"きれいな海","why":"Sifat-na harus dihubungkan dengan な sebelum kata benda."},"order":5,"level":"N5","enrichment":false},{"id":"no-possession","category":"partikel","subcategory":"Penghubung benda","sourcePages":[4],"title":"N の N","kana":"の","romaji":"no","meaning":"Kepemilikan, asal, dan hubungan antarbenda","explanation":"の menghubungkan dua kata benda. Kata benda pertama menerangkan yang kedua: pemilik, asal, jenis, atau waktu yang berkaitan dengan benda tersebut. Artinya disesuaikan dengan konteks.","patterns":["Pemilik + の + benda","Asal / jenis / waktu + の + benda"],"note":"Urutannya berbeda dari bahasa Indonesia: 日本の車 berarti mobil Jepang, sedangkan 私の本 berarti buku saya.","examples":[{"jp":"これは私の本です。","kana":"これ は わたし の ほん です。","meaning":"Ini buku saya."},{"jp":"昨日の新聞を読みます。","kana":"きのう の しんぶん を よみます。","meaning":"Saya membaca koran kemarin."}],"order":6,"level":"N5","enrichment":false},{"id":"no-substitute","category":"partikel","subcategory":"Penghubung benda","sourcePages":[4],"title":"の sebagai pengganti benda","kana":"の","romaji":"no","meaning":"“Yang …” ketika bendanya sudah jelas","explanation":"Kalau benda sudah diketahui dari percakapan, の dapat menggantikannya. Gunakan setelah pemilik atau sifat agar tidak perlu mengulang nama benda.","patterns":["Pemilik + の","Sifat-i + の","Sifat-na + な + の"],"note":"Ini berbeda dari の untuk membendakan kegiatan. Di sini の menggantikan benda yang sudah dipahami bersama.","examples":[{"jp":"このペンは私のです。","kana":"この ペン は わたし の です。","meaning":"Pena ini milik saya."},{"jp":"大きいのをください。","kana":"おおきい の を ください。","meaning":"Tolong beri saya yang besar."}],"order":7,"level":"N5","enrichment":false},{"id":"existence","category":"dasar","subcategory":"Keberadaan","sourcePages":[5],"title":"います・あります","kana":"います・あります","romaji":"imasu / arimasu","meaning":"Ada: makhluk hidup atau benda","explanation":"います digunakan untuk orang dan hewan. あります digunakan untuk benda dan tumbuhan. Dalam konteks tertentu, keberadaan ini juga menyatakan memiliki sesuatu atau mempunyai anggota keluarga.","patterns":["Orang / hewan + が + います","Benda / tumbuhan + が + あります"],"note":"Untuk tumbuhan, gunakan あります pada pola dasar ini. Bentuk negatif sopannya いません dan ありません.","examples":[{"jp":"猫がいます。","kana":"ねこ が います。","meaning":"Ada seekor kucing."},{"jp":"傘があります。","kana":"かさ が あります。","meaning":"Ada payung / saya punya payung."}],"order":8,"level":"N5","enrichment":false},{"id":"existence-place","category":"dasar","subcategory":"Keberadaan","sourcePages":[5],"title":"Tempat に ～がいます／あります","kana":"に ～が います・あります","romaji":"ni ... ga imasu / arimasu","meaning":"Menjelaskan sesuatu berada di mana","explanation":"Sebutkan tempat terlebih dahulu dengan に, lalu benda atau makhluk yang ada dengan が. Untuk menjelaskan letak benda yang sudah menjadi topik, susunannya dapat menjadi A は tempat にあります／います.","patterns":["Tempat + に + benda + が + あります","Tempat + に + orang / hewan + が + います","A + は + tempat + に + あります／います"],"note":"に menandai lokasi keberadaan. Untuk lokasi berlangsungnya kegiatan seperti belajar atau bekerja, biasanya gunakan で.","examples":[{"jp":"机の上に本があります。","kana":"つくえ の うえ に ほん が あります。","meaning":"Ada buku di atas meja."},{"jp":"先生は教室にいます。","kana":"せんせい は きょうしつ に います。","meaning":"Guru berada di kelas."}],"mistake":{"wrong":"教室で先生がいます。","correct":"教室に先生がいます。","why":"Pada pola keberadaan います, lokasi ditandai に。"},"order":9,"level":"N5","enrichment":false,"check":{"prompt":"Isi bagian kosong: 机の上＿＿本があります。","options":["で","に"],"answer":1,"explanation":"Keberadaan あります memakai に untuk lokasinya."}},{"id":"wa","category":"partikel","subcategory":"Topik & subjek","sourcePages":[6],"title":"は","kana":"は","romaji":"wa","meaning":"Menandai topik dan pertentangan","explanation":"は memperkenalkan hal yang sedang dibicarakan: “kalau tentang A, …”. Partikel ini juga dapat menonjolkan perbedaan antara dua hal. Saat menjadi partikel, は dibaca wa.","patterns":["Topik + は + keterangan","A + は …、B + は …"],"note":"は tidak selalu sama dengan subjek. Pada kalimat negatif atau perbandingan, は dapat menekankan apa yang dibedakan.","examples":[{"jp":"私は学生です。","kana":"わたし は がくせい です。","meaning":"Saya pelajar."},{"jp":"肉は食べますが、魚は食べません。","kana":"にく は たべます が、さかな は たべません。","meaning":"Daging saya makan, tetapi ikan tidak."}],"order":10,"level":"N5","enrichment":false},{"id":"wa-ga","category":"partikel","subcategory":"Topik & subjek","sourcePages":[6],"title":"A は B が ～","kana":"は・が","romaji":"wa / ga","meaning":"Mendeskripsikan bagian atau ciri suatu topik","explanation":"A adalah topik besar, sedangkan B adalah bagian atau unsur yang dijelaskan. Pola ini berguna untuk membicarakan tubuh, ciri tempat, kemampuan, atau kesukaan.","patterns":["A + は + B + が + sifat / keterangan"],"note":"兄は背が高いです berarti kakak laki-laki saya bertubuh tinggi. は menandai kakak sebagai topik dan が menandai 背 sebagai hal yang tinggi.","examples":[{"jp":"兄は背が高いです。","kana":"あに は せ が たかいです。","meaning":"Kakak laki-laki saya tinggi."},{"jp":"東京は人が多いです。","kana":"とうきょう は ひと が おおいです。","meaning":"Tokyo memiliki banyak penduduk/orang."}],"order":11,"level":"N5","enrichment":false},{"id":"ga-question","category":"partikel","subcategory":"Topik & subjek","sourcePages":[6],"title":"Kata tanya + が","kana":"が","romaji":"ga","meaning":"Menanyakan dan menunjukkan subjek","explanation":"Saat menanyakan siapa atau yang mana yang melakukan sesuatu, が dipakai setelah kata tanya. Jawabannya juga dapat memakai が untuk menunjukkan subjek yang dimaksud.","patterns":["だれ / どれ + が + keterangan + か","Jawaban + が + keterangan"],"note":"Bandingkan だれが来ますか (siapa yang datang?) dengan 田中さんは来ますか (kalau Tanaka, apakah datang?). Fokus pertanyaannya berbeda.","examples":[{"jp":"誰が来ますか。","kana":"だれ が きます か。","meaning":"Siapa yang akan datang?"},{"jp":"田中さんが来ます。","kana":"たなかさん が きます。","meaning":"Tanaka yang akan datang."}],"order":12,"level":"N5","enrichment":false},{"id":"wo","category":"partikel","subcategory":"Objek & kebersamaan","sourcePages":[7],"title":"を","kana":"を","romaji":"o / wo","meaning":"Objek tindakan dan jalur yang dilalui","explanation":"を paling sering menandai objek langsung tindakan, misalnya membaca buku. Pada kata kerja gerak tertentu, を menandai tempat yang dilalui atau ditinggalkan. Sebagai partikel, を biasanya diucapkan o.","patterns":["Objek + を + kata kerja","Jalur / tempat yang dilalui + を + gerak"],"note":"を bukan penanda tempat untuk semua tindakan. 公園を散歩します menekankan berjalan menyusuri taman; 公園で勉強します menyatakan belajar di taman.","examples":[{"jp":"本を読みます。","kana":"ほん を よみます。","meaning":"Saya membaca buku."},{"jp":"橋を渡ります。","kana":"はし を わたります。","meaning":"Saya menyeberangi jembatan."}],"order":13,"level":"N5","enrichment":false},{"id":"to","category":"partikel","subcategory":"Objek & kebersamaan","sourcePages":[7],"title":"と","kana":"と","romaji":"to","meaning":"“Dan” atau “bersama”","explanation":"と menyambungkan daftar benda yang disebutkan secara lengkap. Sebelum kata kerja, と juga menandai teman atau pihak lain yang terlibat dalam kegiatan.","patterns":["Benda A + と + benda B","Orang + と + kegiatan"],"note":"と untuk daftar benda tidak menggantikan penghubung antara dua kalimat lengkap. Untuk “lalu” atau “dan” antarkalimat, lihat そして／それから.","examples":[{"jp":"パンと卵を買います。","kana":"パン と たまご を かいます。","meaning":"Saya membeli roti dan telur."},{"jp":"友達と買い物をします。","kana":"ともだち と かいもの を します。","meaning":"Saya berbelanja bersama teman."}],"order":14,"level":"N5","enrichment":false},{"id":"ni","category":"partikel","subcategory":"Tempat, waktu & cara","sourcePages":[8],"title":"に","kana":"に","romaji":"ni","meaning":"Lokasi keberadaan, waktu, tujuan, dan penerima","explanation":"に memiliki beberapa fungsi. Gunakan untuk tempat keberadaan, waktu tertentu, tujuan gerak, atau orang yang menjadi sasaran/penerima tindakan. Perhatikan kata kerja setelahnya untuk menentukan maknanya.","patterns":["Waktu tertentu + に","Tujuan + に + 行きます","Orang + に + 会います／聞きます","Kendaraan + に + 乗ります"],"note":"今日・明日・毎日 biasanya tidak memerlukan に sebagai keterangan waktu. Tujuan perjalanan juga dapat memakai へ, yang menekankan arah.","examples":[{"jp":"七時に起きます。","kana":"しちじ に おきます。","meaning":"Saya bangun pukul tujuh."},{"jp":"友達に会います。","kana":"ともだち に あいます。","meaning":"Saya bertemu teman."}],"order":15,"level":"N5","enrichment":false},{"id":"de","category":"partikel","subcategory":"Tempat, waktu & cara","sourcePages":[8],"title":"で","kana":"で","romaji":"de","meaning":"Lokasi kegiatan, alat, dan cakupan","explanation":"で menandai tempat suatu kegiatan berlangsung serta alat atau cara yang dipakai. Dalam konteks lain, で membatasi kelompok pembanding atau menyatakan jumlah yang dihitung bersama.","patterns":["Tempat + で + kegiatan","Alat / kendaraan + で + kegiatan","Jumlah + で + harga"],"note":"Bedakan 図書館で勉強します (belajar di perpustakaan) dan 図書館にいます (berada di perpustakaan).","examples":[{"jp":"図書館で勉強します。","kana":"としょかん で べんきょうします。","meaning":"Saya belajar di perpustakaan."},{"jp":"電車で学校へ行きます。","kana":"でんしゃ で がっこう へ いきます。","meaning":"Saya pergi ke sekolah dengan kereta."}],"mistake":{"wrong":"図書館に勉強します。","correct":"図書館で勉強します。","why":"Lokasi berlangsungnya kegiatan 勉強します ditandai で。"},"order":16,"level":"N5","enrichment":false,"check":{"prompt":"Isi bagian kosong: 図書館＿＿勉強します。","options":["で","に"],"answer":0,"explanation":"で menandai tempat berlangsungnya kegiatan belajar."}},{"id":"mo","category":"partikel","subcategory":"Daftar & pilihan","sourcePages":[9],"title":"も","kana":"も","romaji":"mo","meaning":"Juga; baik A maupun B","explanation":"も menambahkan sesuatu yang sama dengan hal sebelumnya. A も B も menyertakan keduanya; jika predikatnya negatif, artinya menjadi “baik A maupun B tidak …”.","patterns":["A + も + keterangan","A + も + B + も + predikat"],"note":"も dapat menggantikan は・が・を sesuai konteks. Partikel seperti に dan で biasanya tetap ada: にも、でも.","examples":[{"jp":"私も学生です。","kana":"わたし も がくせい です。","meaning":"Saya juga pelajar."},{"jp":"肉も魚も食べません。","kana":"にく も さかな も たべません。","meaning":"Saya tidak makan daging maupun ikan."}],"order":17,"level":"N5","enrichment":false},{"id":"ka-choice","category":"partikel","subcategory":"Daftar & pilihan","sourcePages":[9],"title":"A か B","kana":"か","romaji":"ka","meaning":"Memilih A atau B","explanation":"Di antara dua kata benda, か menyatakan pilihan “atau”. Ini berbeda dari か di akhir kalimat yang membuat pertanyaan. Dalam satu kalimat, kedua fungsi dapat muncul bersamaan.","patterns":["Benda A + か + benda B","Kalimat sopan + か"],"note":"Kalimat tanya sopan umumnya diakhiri か. Jangan menyamakan A か B dengan A と B: yang pertama pilihan, yang kedua daftar.","examples":[{"jp":"コーヒーか紅茶を飲みます。","kana":"コーヒー か こうちゃ を のみます。","meaning":"Saya minum kopi atau teh hitam."},{"jp":"これはあなたの本ですか。","kana":"これ は あなた の ほん です か。","meaning":"Apakah ini bukumu?"}],"order":18,"level":"N5","enrichment":false},{"id":"ya","category":"partikel","subcategory":"Daftar & pilihan","sourcePages":[9],"title":"や ～など","kana":"や・など","romaji":"ya / nado","meaning":"Menyebut beberapa contoh dari sebuah daftar","explanation":"や dipakai untuk menyebut benda sebagai contoh, bukan daftar lengkap. など dapat ditambahkan setelah unsur terakhir untuk menegaskan “dan sebagainya”.","patterns":["A + や + B + など"],"note":"Gunakan と jika daftar hendak disebutkan sebagai satu set lengkap. や memberi kesan masih ada benda lain yang sejenis.","examples":[{"jp":"パンや果物を買います。","kana":"パン や くだもの を かいます。","meaning":"Saya membeli roti, buah, dan lain-lain."},{"jp":"駅の前に銀行や店などがあります。","kana":"えき の まえ に ぎんこう や みせ など が あります。","meaning":"Di depan stasiun ada bank, toko, dan sebagainya."}],"order":19,"level":"N5","enrichment":false},{"id":"kara-made","category":"partikel","subcategory":"Batas & perkiraan","sourcePages":[9],"title":"から・まで","kana":"から・まで","romaji":"kara / made","meaning":"Dari titik awal sampai titik akhir","explanation":"から menunjukkan awal dan まで menunjukkan akhir, baik untuk waktu maupun tempat. Keduanya boleh dipakai bersama atau sendiri jika titik lainnya sudah jelas.","patterns":["Awal + から + akhir + まで","Waktu / tempat + から","Waktu / tempat + まで"],"note":"から di sini berarti “dari”, berbeda dari から setelah kalimat alasan yang berarti “karena”.","examples":[{"jp":"九時から五時まで働きます。","kana":"くじ から ごじ まで はたらきます。","meaning":"Saya bekerja dari pukul sembilan sampai lima."},{"jp":"家から駅まで歩きます。","kana":"いえ から えき まで あるきます。","meaning":"Saya berjalan dari rumah ke stasiun."}],"order":20,"level":"N5","enrichment":false},{"id":"goro","category":"partikel","subcategory":"Batas & perkiraan","sourcePages":[10],"title":"ごろ","kana":"ごろ","romaji":"goro","meaning":"Sekitar suatu titik waktu","explanation":"ごろ dipakai setelah titik waktu untuk menyatakan perkiraan. Bayangkan satu titik di jam atau kalender, bukan panjang durasinya.","patterns":["Titik waktu + ごろ"],"note":"七時ごろ berarti sekitar pukul tujuh. Untuk durasi sekitar satu jam, gunakan 一時間ぐらい.","examples":[{"jp":"七時ごろ電話します。","kana":"しちじ ごろ でんわします。","meaning":"Saya akan menelepon sekitar pukul tujuh."},{"jp":"三月ごろ日本へ行きます。","kana":"さんがつ ごろ にほん へ いきます。","meaning":"Saya pergi ke Jepang sekitar bulan Maret."}],"mistake":{"wrong":"一時間ごろ待ちます。","correct":"一時間ぐらい待ちます。","why":"Durasi 一時間 memakai ぐらい; ごろ dipakai untuk titik waktu."},"order":21,"level":"N5","enrichment":false,"check":{"prompt":"Mana yang berarti “sekitar pukul tujuh”?","options":["七時間ぐらい","七時ごろ"],"answer":1,"explanation":"七時ごろ adalah sekitar pukul tujuh. 七時間ぐらい menyatakan durasi sekitar tujuh jam."}},{"id":"gurai","category":"partikel","subcategory":"Batas & perkiraan","sourcePages":[10],"title":"ぐらい／くらい","kana":"ぐらい・くらい","romaji":"gurai / kurai","meaning":"Sekitar jumlah, harga, atau durasi","explanation":"ぐらい dan くらい menyatakan perkiraan kuantitas, harga, atau lamanya waktu. Keduanya dipakai dengan makna dasar yang sama.","patterns":["Jumlah / durasi + ぐらい／くらい"],"note":"Bedakan 一時間ぐらい (sekitar satu jam) dari 一時ごろ (sekitar pukul satu).","examples":[{"jp":"三十分ぐらいかかります。","kana":"さんじゅっぷん ぐらい かかります。","meaning":"Memerlukan sekitar tiga puluh menit."},{"jp":"千円くらいです。","kana":"せんえん くらい です。","meaning":"Harganya sekitar seribu yen."}],"order":22,"level":"N5","enrichment":false},{"id":"dake","category":"partikel","subcategory":"Batas & perkiraan","sourcePages":[10],"title":"だけ","kana":"だけ","romaji":"dake","meaning":"Hanya; membatasi jumlah atau pilihan","explanation":"だけ membatasi sesuatu pada unsur yang disebutkan. Dalam pola dasar ini, kalimat tetap dapat memakai predikat positif karena makna “hanya” sudah dibawa oleh だけ.","patterns":["Kata benda / jumlah + だけ"],"note":"に dan で dapat dipertahankan sesuai kebutuhan: 日曜日にだけ (hanya pada Minggu). Pelajari konteks sebelum menumpuk partikel.","examples":[{"jp":"休みは日曜日だけです。","kana":"やすみ は にちようび だけ です。","meaning":"Hari libur hanya hari Minggu."},{"jp":"水だけ飲みます。","kana":"みず だけ のみます。","meaning":"Saya hanya minum air."}],"order":23,"level":"N5","enrichment":false},{"id":"combined-wa","category":"partikel","subcategory":"Penekanan","sourcePages":[10],"title":"には・では・へは・までは","kana":"には・では・へは・までは","romaji":"ni wa / de wa / e wa / made wa","meaning":"Menjadikan tempat atau batas sebagai topik","explanation":"は dapat ditambahkan setelah に・で・へ・まで untuk menonjolkan topik atau pertentangan. Partikel awal tetap membawa makna lokasi, alat, arah, atau batasnya.","patterns":["に / で / へ / まで + は"],"note":"では pada materi ini adalah gabungan で＋は, misalnya 電車では. Bentuk yang sama juga muncul pada ungkapan lain; pahami konteksnya.","examples":[{"jp":"この町には図書館がありません。","kana":"この まち には としょかん が ありません。","meaning":"Di kota ini tidak ada perpustakaan."},{"jp":"電車では五時間かかります。","kana":"でんしゃ では ごじかん かかります。","meaning":"Kalau naik kereta, perlu lima jam."}],"order":24,"level":"N5","enrichment":false},{"id":"question-words","category":"tanya","subcategory":"Kata tanya","sourcePages":[11],"title":"だれ・何・どこ・どれ","kana":"だれ・なに・なん・どこ・どれ・どの","romaji":"dare / nani / nan / doko / dore / dono","meaning":"Siapa, apa, di mana, dan yang mana","explanation":"Pilih kata tanya sesuai informasi yang dicari. どれ berdiri sendiri, sedangkan どの harus diikuti kata benda. どなた adalah bentuk lebih sopan dari だれ; どちら dapat menjadi bentuk sopan untuk arah, tempat, atau pilihan.","patterns":["だれの + benda + ですか","どれ + ですか","どの + benda + ですか"],"note":"何 memiliki bacaan なに atau なん bergantung susunannya. Contoh yang umum: 何ですか (なんですか) dan 何を食べますか (なにをたべますか).","examples":[{"jp":"これは誰のペンですか。","kana":"これ は だれ の ペン です か。","meaning":"Pena siapa ini?"},{"jp":"どの本が好きですか。","kana":"どの ほん が すき です か。","meaning":"Buku yang mana yang kamu sukai?"}],"mistake":{"wrong":"どれ本ですか。","correct":"どの本ですか。","why":"Sebelum kata benda 本, gunakan どの; どれ berdiri sendiri."},"table":{"headers":["Kata tanya","Makna"],"rows":[["だれ / どなた","Siapa"],["なに / なん","Apa"],["どこ / どちら","Di mana / arah mana"],["どれ","Yang mana (berdiri sendiri)"],["どの + benda","Benda yang mana"]]},"order":25,"level":"N5","enrichment":false,"check":{"prompt":"Pilih susunan “buku yang mana?”.","options":["どれ本","どの本"],"answer":1,"explanation":"どの harus diikuti benda; どれ berdiri sendiri."}},{"id":"how-questions","category":"tanya","subcategory":"Kata tanya","sourcePages":[11,12],"title":"どうやって・どんな・いくつ","kana":"どうやって・どんな・いくつ","romaji":"dou yatte / donna / ikutsu","meaning":"Cara, jenis, dan jumlah","explanation":"どうやって menanyakan cara melakukan sesuatu. どんな diikuti kata benda untuk menanyakan jenis atau sifatnya. いくつ menanyakan jumlah; juga bisa dipakai untuk menanyakan usia.","patterns":["どうやって + kegiatan + か","どんな + benda + が好きですか","Benda + を + いくつ + kata kerja + か"],"note":"Untuk menanyakan harga gunakan いくら. Untuk panjang waktu atau tingkat, gunakan どのくらい.","examples":[{"jp":"どうやって学校へ行きますか。","kana":"どうやって がっこう へ いきます か。","meaning":"Bagaimana caramu pergi ke sekolah?"},{"jp":"りんごをいくつ買いましたか。","kana":"りんご を いくつ かいました か。","meaning":"Berapa buah apel yang kamu beli?"}],"table":{"headers":["Kata tanya","Makna"],"rows":[["どんな + benda","Yang seperti apa"],["いつ","Kapan"],["どうして / なぜ","Mengapa"],["いくら","Berapa harga"],["どのくらい","Berapa lama / seberapa"],["どちら / どっち","Yang mana (dua pilihan)"]]},"order":26,"level":"N5","enrichment":false},{"id":"kochira","category":"tanya","subcategory":"Penunjuk sopan","sourcePages":[12],"title":"こちら・そちら","kana":"こちら・そちら","romaji":"kochira / sochira","meaning":"Menunjuk dan memperkenalkan secara sopan","explanation":"こちら dan そちら dapat menunjuk arah atau pihak secara sopan. Dalam perkenalan, こちらは～さんです dipakai untuk memperkenalkan orang yang ada di sisi pembicara.","patterns":["こちら + は + orang + です","そちら + は + orang / tempat + ですか"],"note":"Saat menyebut keluarga sendiri kepada orang luar, gunakan 母・父. Untuk keluarga orang lain, gunakan お母さん・お父さん. Ini penyesuaian kesopanan, bukan larangan mutlak memakai 私の母.","examples":[{"jp":"こちらは田中さんです。","kana":"こちら は たなかさん です。","meaning":"Ini Tanaka."},{"jp":"こちらは私の母です。","kana":"こちら は わたし の はは です。","meaning":"Ini ibu saya."}],"order":27,"level":"N5","enrichment":false},{"id":"question-ka","category":"tanya","subcategory":"Tak tentu & cakupan","sourcePages":[13],"title":"Kata tanya + か","kana":"なにか・だれか・どこか・いつか","romaji":"nanika / dareka / dokoka / itsuka","meaning":"Sesuatu, seseorang, suatu tempat, suatu hari","explanation":"Tambahkan か setelah kata tanya untuk menyebut hal yang belum ditentukan. なにか bukan pertanyaan “apa”, melainkan “sesuatu”.","patterns":["なにか + kata kerja","だれか + いますか","どこか + へ／に + 行きます","いつか + kalimat"],"note":"Dalam なにか食べます, を sering tidak disebutkan. Untuk tempat tujuan, へ／に dapat dipakai sesuai konteks.","examples":[{"jp":"何か食べましょう。","kana":"なにか たべましょう。","meaning":"Ayo makan sesuatu."},{"jp":"教室に誰かいますか。","kana":"きょうしつ に だれか います か。","meaning":"Apakah ada seseorang di kelas?"}],"order":28,"level":"N5","enrichment":false},{"id":"question-mo-negative","category":"tanya","subcategory":"Tak tentu & cakupan","sourcePages":[13],"title":"Kata tanya + も + negatif","kana":"だれも・なにも・どこにも","romaji":"daremo / nanimo / doko ni mo","meaning":"Tidak siapa-siapa, tidak apa-apa, tidak ke mana-mana","explanation":"Gabungan kata tanya dengan も dan predikat negatif meniadakan seluruh kemungkinan. Pastikan bagian akhir kalimat memang negatif.","patterns":["だれも + いません","なにも + kata kerja negatif","どこにも／どこへも + 行きません"],"note":"Untuk tujuan tempat, partikel に atau へ dapat dipertahankan sebelum も. だれも di sini berarti “tidak seorang pun” karena diikuti negatif.","examples":[{"jp":"教室に誰もいません。","kana":"きょうしつ に だれも いません。","meaning":"Tidak ada siapa-siapa di kelas."},{"jp":"今朝は何も食べませんでした。","kana":"けさ は なにも たべませんでした。","meaning":"Pagi ini saya tidak makan apa pun."}],"mistake":{"wrong":"何も食べます。","correct":"何も食べません。","why":"Untuk makna “tidak makan apa pun”, predikatnya harus negatif."},"order":29,"level":"N5","enrichment":false,"check":{"prompt":"Pilih “Tidak ada siapa-siapa”.","options":["誰もいません。","誰もいます。"],"answer":0,"explanation":"だれも＋negatif menyatakan tidak ada seorang pun."}},{"id":"question-demo","category":"tanya","subcategory":"Tak tentu & cakupan","sourcePages":[14],"title":"Kata tanya + でも","kana":"なんでも・だれでも・いつでも・どこでも","romaji":"nandemo / daredemo / itsudemo / dokodemo","meaning":"Apa pun, siapa pun, kapan pun, di mana pun","explanation":"でも setelah kata tanya membuka pilihan tanpa membatasi satu unsur tertentu. どれでも berarti yang mana pun; いつでも berarti kapan saja.","patterns":["Kata tanya + でも + predikat"],"note":"でも di sini adalah bagian dari ungkapan seperti なんでも. Bedakan dari でも yang mengawali kalimat dengan arti “tetapi”.","examples":[{"jp":"何でも食べます。","kana":"なんでも たべます。","meaning":"Saya makan apa saja."},{"jp":"いつでも来てください。","kana":"いつでも きて ください。","meaning":"Silakan datang kapan saja."}],"order":30,"level":"N5","enrichment":false},{"id":"dou-desuka","category":"tanya","subcategory":"Pendapat & tindakan","sourcePages":[14],"title":"どうですか・いかがですか","kana":"どうですか・いかがですか","romaji":"dou desu ka / ikaga desu ka","meaning":"Menanyakan kesan atau menawarkan sesuatu","explanation":"どうですか menanyakan pendapat atau keadaan. Pola ini juga dapat menawarkan makanan atau minuman. いかがですか memiliki makna serupa dengan tingkat kesopanan lebih tinggi.","patterns":["Topik + は + どうですか／いかがですか","Lampau: どうでしたか／いかがでしたか"],"note":"どうでしたか menanyakan kesan tentang pengalaman yang sudah terjadi. Untuk menanyakan keputusan tindakan, gunakan どうしますか.","examples":[{"jp":"新しい学校はどうですか。","kana":"あたらしい がっこう は どう です か。","meaning":"Bagaimana sekolah barumu?"},{"jp":"お茶はいかがですか。","kana":"おちゃ は いかが です か。","meaning":"Bagaimana kalau minum teh?"}],"order":31,"level":"N5","enrichment":false},{"id":"dou-shimasuka","category":"tanya","subcategory":"Pendapat & tindakan","sourcePages":[22],"title":"どうしますか","kana":"どうしますか","romaji":"dou shimasu ka","meaning":"Akan melakukan apa atau memilih tindakan apa","explanation":"どうしますか menanyakan tindakan atau keputusan yang akan diambil. Bentuk どうしましたか dapat menanyakan apa yang dilakukan sebelumnya; dalam situasi tertentu juga menanyakan ada masalah apa.","patterns":["Topik + は + どうしますか","Lampau: どうしましたか"],"note":"Bedakan 旅行はどうでしたか (bagaimana kesan perjalanannya?) dan 旅行はどうしますか (bagaimana keputusan tentang perjalanan itu?).","examples":[{"jp":"この本はどうしますか。","kana":"この ほん は どうします か。","meaning":"Buku ini akan kamu apakan?"},{"jp":"今日はどうしますか。","kana":"きょう は どうします か。","meaning":"Hari ini kita akan melakukan apa?"}],"order":32,"level":"N5","enrichment":false},{"id":"connect-adjectives","category":"rangkaian","subcategory":"Sifat & benda","sourcePages":[15],"title":"～くて・～で","kana":"くて・で","romaji":"kute / de","meaning":"Menghubungkan sifat atau identitas","explanation":"Untuk menyambungkan sifat-i, buang い lalu tambahkan くて. Sifat-na dan kata benda memakai で. Bagian terakhir kalimat menentukan waktu dan tingkat kesopanan keseluruhan.","patterns":["Sifat-i tanpa い + くて","Sifat-na / kata benda + で"],"note":"いい berubah menjadi よくて. Untuk menerangkan benda setelah beberapa sifat, akhiri sifat terakhir dengan bentuk yang cocok sebelum benda.","examples":[{"jp":"この部屋は広くて明るいです。","kana":"この へや は ひろくて あかるいです。","meaning":"Kamar ini luas dan terang."},{"jp":"姉は親切で元気です。","kana":"あね は しんせつ で げんき です。","meaning":"Kakak perempuan saya baik hati dan bersemangat."}],"mistake":{"wrong":"広いくて明るいです。","correct":"広くて明るいです。","why":"Buang い sebelum menambahkan くて。"},"order":33,"level":"N5","enrichment":false},{"id":"negative-connect","category":"rangkaian","subcategory":"Sifat & benda","sourcePages":[15],"title":"～くなくて・～じゃなくて","kana":"くなくて・じゃなくて","romaji":"kunakute / ja nakute","meaning":"Menyambungkan bentuk negatif","explanation":"Sifat-i negatif dapat disambungkan dengan ～くなくて. Kata benda dan sifat-na memakai ～じゃなくて atau ～ではなくて. Pola ini juga bisa mengoreksi informasi: “bukan A, melainkan B”.","patterns":["Sifat-i tanpa い + くなくて","Kata benda / sifat-na + じゃなくて"],"note":"Jangan menyamakan bentuk ini dengan ～ないでください yang menyatakan permintaan agar tidak melakukan tindakan.","examples":[{"jp":"先生じゃなくて、学生です。","kana":"せんせい じゃ なくて、がくせい です。","meaning":"Bukan guru, melainkan pelajar."},{"jp":"この料理は辛くなくて、おいしいです。","kana":"この りょうり は からくなくて、おいしいです。","meaning":"Masakan ini tidak pedas dan enak."}],"order":34,"level":"N5","enrichment":false},{"id":"te-sequence","category":"rangkaian","subcategory":"Urutan kegiatan","sourcePages":[16],"title":"Vて、Vます","kana":"て・で","romaji":"te / de","meaning":"Melakukan beberapa tindakan berurutan","explanation":"Bentuk て menghubungkan kegiatan dalam satu rangkaian. Kata kerja terakhir menentukan waktu kalimat. Gunakan bentuk て yang sesuai kelompok kata kerjanya.","patterns":["Vて + Vて + kata kerja akhir"],"note":"Contoh perubahan: 食べる→食べて、飲む→飲んで、行く→行って、する→して、来る→来て. Akhiran て juga dapat membawa hubungan lain sesuai konteks.","examples":[{"jp":"朝起きて、顔を洗います。","kana":"あさ おきて、かお を あらいます。","meaning":"Pagi hari saya bangun lalu mencuci muka."},{"jp":"本を読んで、寝ました。","kana":"ほん を よんで、ねました。","meaning":"Saya membaca buku lalu tidur."}],"table":{"headers":["Akhiran kamus","Bentuk て"],"rows":[["う・つ・る (gol. I)","って"],["む・ぶ・ぬ","んで"],["く / ぐ","いて / いで"],["す","して"],["る (gol. II)","Buang る + て"],["する / 来る","して / 来て (きて)"],["行く (khusus)","行って"]]},"order":35,"level":"N5","enrichment":false},{"id":"te-kara","category":"rangkaian","subcategory":"Urutan kegiatan","sourcePages":[16],"title":"Vてから","kana":"てから","romaji":"te kara","meaning":"Setelah selesai A, baru B","explanation":"てから menegaskan bahwa kegiatan pertama diselesaikan sebelum kegiatan berikutnya. Cocok untuk menjelaskan urutan yang penting.","patterns":["Vて + から + kegiatan berikutnya"],"note":"から di sini mengikuti bentuk て dan berarti “setelah”. Ini berbeda dari から setelah alasan yang berarti “karena”.","examples":[{"jp":"手を洗ってから、ご飯を食べます。","kana":"て を あらって から、ごはん を たべます。","meaning":"Setelah mencuci tangan, saya makan."},{"jp":"宿題をしてから、遊びます。","kana":"しゅくだい を して から、あそびます。","meaning":"Setelah mengerjakan PR, saya bermain."}],"order":36,"level":"N5","enrichment":false},{"id":"sorekara-soshite","category":"rangkaian","subcategory":"Penghubung kalimat","sourcePages":[16],"title":"それから・そして","kana":"それから・そして","romaji":"sorekara / soshite","meaning":"Lalu; dan juga","explanation":"それから sering memperkenalkan kegiatan berikutnya dalam urutan waktu. そして menambahkan informasi atau melanjutkan rangkaian cerita. Keduanya menghubungkan kalimat yang sudah dapat berdiri sendiri.","patterns":["Kalimat A。それから、kalimat B。","Kalimat A。そして、kalimat B。"],"note":"Untuk daftar kata benda gunakan と atau や. Jangan memakai と begitu saja di antara dua kalimat sopan.","examples":[{"jp":"六時に起きました。それから、散歩しました。","kana":"ろくじ に おきました。それから、さんぽしました。","meaning":"Saya bangun pukul enam. Setelah itu saya berjalan-jalan."},{"jp":"兄は親切です。そして、料理も上手です。","kana":"あに は しんせつ です。そして、りょうり も じょうず です。","meaning":"Kakak saya baik hati. Ia juga pandai memasak."}],"order":37,"level":"N5","enrichment":false},{"id":"relative-clause","category":"rangkaian","subcategory":"Anak kalimat","sourcePages":[21,22],"title":"Keterangan sebelum kata benda","kana":"ふつうけい ＋ めいし","romaji":"futsuukei + meishi","meaning":"Buku yang dipinjam; orang yang berambut panjang","explanation":"Letakkan keterangan tepat sebelum benda yang diterangkan. Kata kerja di dalam keterangan memakai bentuk biasa. Kata sifat mengikuti aturan sifat-i atau sifat-na seperti frasa benda biasa.","patterns":["Kata kerja bentuk biasa + benda","Subjek + が + keterangan + benda","Sifat-na + な + benda"],"note":"図書館で借りた本 berarti buku yang dipinjam di perpustakaan. が dapat berganti の dalam sebagian anak kalimat, tetapi gunakan が dahulu agar pola mudah dikenali.","examples":[{"jp":"昨日買った本を読みます。","kana":"きのう かった ほん を よみます。","meaning":"Saya membaca buku yang dibeli kemarin."},{"jp":"父が働いている会社は東京にあります。","kana":"ちち が はたらいている かいしゃ は とうきょう に あります。","meaning":"Perusahaan tempat ayah bekerja berada di Tokyo."}],"mistake":{"wrong":"昨日買いました本","correct":"昨日買った本","why":"Keterangan sebelum benda memakai bentuk biasa 買った, bukan bentuk sopan 買いました。"},"order":38,"level":"N5","enrichment":false},{"id":"hoshii","category":"ungkapan","subcategory":"Keinginan","sourcePages":[17],"title":"N がほしいです","kana":"が ほしいです","romaji":"ga hoshii desu","meaning":"Ingin memiliki sesuatu","explanation":"Gunakan ほしい untuk menyatakan keinginan memiliki benda. Benda yang diinginkan ditandai が. Perubahannya mengikuti sifat-i: ほしくない、ほしかった、ほしくなかった.","patterns":["Benda + が + ほしいです"],"note":"Untuk keinginan melakukan kegiatan, gunakan kata kerja ～たい. Pola langsung ini terutama dipakai untuk keinginan diri sendiri atau menanyakan keinginan lawan bicara.","examples":[{"jp":"新しいかばんがほしいです。","kana":"あたらしい かばん が ほしいです。","meaning":"Saya ingin tas baru."},{"jp":"今は車がほしくないです。","kana":"いま は くるま が ほしくないです。","meaning":"Sekarang saya tidak ingin mobil."}],"order":39,"level":"N5","enrichment":false},{"id":"tai","category":"ungkapan","subcategory":"Keinginan","sourcePages":[17],"title":"Vたいです","kana":"たいです","romaji":"tai desu","meaning":"Ingin melakukan sesuatu","explanation":"Buang ます dari kata kerja bentuk sopan, lalu tambahkan たいです. Bentuk ini menyatakan keinginan melakukan kegiatan. Perubahan negatif dan lampaunya mengikuti sifat-i.","patterns":["Vます tanpa ます + たいです","～たくないです / ～たかったです"],"note":"食べます→食べたいです. Objek kegiatan bisa memakai を atau が dalam pola keinginan tertentu. Bedakan 買いたい (ingin membeli) dan ほしい (ingin memiliki).","examples":[{"jp":"日本へ行きたいです。","kana":"にほん へ いきたいです。","meaning":"Saya ingin pergi ke Jepang."},{"jp":"今日は肉を食べたくないです。","kana":"きょう は にく を たべたくないです。","meaning":"Hari ini saya tidak ingin makan daging."}],"mistake":{"wrong":"日本へ行くたいです。","correct":"日本へ行きたいです。","why":"たい menempel pada bentuk sebelum ます: 行きます→行きたい。"},"order":40,"level":"N5","enrichment":false,"check":{"prompt":"Ubah 行きます menjadi “ingin pergi”.","options":["行くたいです。","行きたいです。"],"answer":1,"explanation":"Buang ます dari 行きます, lalu tambahkan たいです."}},{"id":"te-imasu","category":"ungkapan","subcategory":"Kegiatan & keadaan","sourcePages":[18],"title":"Vています","kana":"ています","romaji":"te imasu","meaning":"Sedang berlangsung atau keadaan yang bertahan","explanation":"ている／ています dapat menyatakan tindakan yang sedang berlangsung. Dengan kata kerja tertentu, pola ini menyatakan keadaan hasil yang masih berlangsung, seperti sudah menikah, tinggal, mengenal, atau memiliki.","patterns":["Vて + います","Negatif: Vて + いません"],"note":"結婚しています berarti sudah menikah, bukan selalu sedang menjalani upacara. 知っています berarti tahu/kenal; negatif yang umum adalah 知りません.","examples":[{"jp":"今、妹はピアノを弾いています。","kana":"いま、いもうと は ピアノ を ひいています。","meaning":"Sekarang adik perempuan saya sedang bermain piano."},{"jp":"東京に住んでいます。","kana":"とうきょう に すんでいます。","meaning":"Saya tinggal di Tokyo."}],"order":41,"level":"N5","enrichment":false},{"id":"te-kudasai","category":"ungkapan","subcategory":"Permintaan","sourcePages":[18],"title":"Vてください","kana":"て ください","romaji":"te kudasai","meaning":"Tolong atau silakan melakukan","explanation":"Tambahkan ください setelah bentuk て untuk meminta seseorang melakukan tindakan. Nada dan situasi menentukan apakah terjemahannya lebih cocok “tolong” atau “silakan”.","patterns":["Vて + ください"],"note":"Pola ini merupakan permintaan langsung. Dalam situasi yang memerlukan kesopanan lebih tinggi, ada ungkapan lain; untuk tahap dasar, perhatikan intonasi dan lawan bicara.","examples":[{"jp":"名前を書いてください。","kana":"なまえ を かいて ください。","meaning":"Tolong tulis nama Anda."},{"jp":"ここで待ってください。","kana":"ここ で まって ください。","meaning":"Silakan tunggu di sini."}],"mistake":{"wrong":"名前を書くください。","correct":"名前を書いてください。","why":"ください dalam pola permintaan ini mengikuti bentuk て, bukan bentuk kamus."},"order":42,"level":"N5","enrichment":false},{"id":"naide-kudasai","category":"ungkapan","subcategory":"Permintaan","sourcePages":[18],"title":"Vないでください","kana":"ないで ください","romaji":"naide kudasai","meaning":"Tolong jangan melakukan","explanation":"Buat bentuk negatif biasa ～ない, lalu tambahkan でください. Gunakan saat meminta orang tidak melakukan suatu tindakan.","patterns":["Vない + でください"],"note":"書く→書かないでください、買う→買わないでください、する→しないでください、来る→来ないでください (こないでください).","examples":[{"jp":"ここで写真を撮らないでください。","kana":"ここ で しゃしん を とらないで ください。","meaning":"Tolong jangan mengambil foto di sini."},{"jp":"ペンで書かないでください。","kana":"ペン で かかないで ください。","meaning":"Tolong jangan menulis dengan pena."}],"mistake":{"wrong":"写真を撮りませんでください。","correct":"写真を撮らないでください。","why":"Gunakan bentuk biasa negatif 撮らない sebelum でください。"},"order":43,"level":"N5","enrichment":false},{"id":"ne-yo","category":"ungkapan","subcategory":"Percakapan","sourcePages":[18],"title":"～ね・～よ","kana":"ね・よ","romaji":"ne / yo","meaning":"Mencari persetujuan atau memberi informasi","explanation":"ね mengajak lawan bicara berbagi perasaan atau mengonfirmasi sesuatu. よ menyampaikan informasi yang dianggap perlu diketahui lawan bicara. Keduanya diletakkan di akhir kalimat.","patterns":["Kalimat + ね","Kalimat + よ"],"note":"Pemakaian よ berlebihan dapat terdengar menekan. Pilih sesuai hubungan dan situasi, bukan sekadar mengganti tanda titik.","examples":[{"jp":"今日は暑いですね。","kana":"きょう は あついです ね。","meaning":"Hari ini panas, ya."},{"jp":"雨が降っていますよ。","kana":"あめ が ふっています よ。","meaning":"Sedang hujan, lho."}],"order":44,"level":"N5","enrichment":false},{"id":"morau","category":"ungkapan","subcategory":"Memberi & menerima","sourcePages":[19],"title":"～に／から もらいます","kana":"に・から もらいます","romaji":"ni / kara moraimasu","meaning":"Menerima dari seseorang","explanation":"もらいます memandang perpindahan benda dari sisi penerima. Penerima menjadi topik/subjek, benda memakai を, dan pemberi memakai に atau から.","patterns":["Penerima + は + pemberi + に／から + benda + を + もらいます"],"note":"に dan から dapat dipakai untuk pemberi yang berupa orang. Saat menyebut lembaga sebagai sumber, から biasanya lebih sesuai.","examples":[{"jp":"母にかばんをもらいました。","kana":"はは に かばん を もらいました。","meaning":"Saya menerima tas dari ibu."},{"jp":"父から時計をもらいました。","kana":"ちち から とけい を もらいました。","meaning":"Saya menerima jam dari ayah."}],"order":45,"level":"N5","enrichment":false,"check":{"prompt":"私が母に本をもらいました。 Siapa penerima buku?","options":["Saya","Ibu"],"answer":0,"explanation":"もらいます memakai sudut pandang penerima, yaitu 私."}},{"id":"kureru","category":"ungkapan","subcategory":"Memberi & menerima","sourcePages":[19],"title":"～が くれます","kana":"くれます","romaji":"kuremasu","meaning":"Orang lain memberi kepada saya atau pihak saya","explanation":"くれます dipakai ketika orang lain memberi sesuatu kepada pembicara atau orang yang dipandang dekat dengan pembicara. Pemberi memakai が／は, sedangkan penerima dapat dihilangkan jika sudah jelas.","patterns":["Pemberi + が + 私に + benda + を + くれます"],"note":"Bedakan 友達にあげます (saya memberi kepada teman) dan 友達がくれます (teman memberi kepada saya). Sudut pandangnya berubah.","examples":[{"jp":"友達が本をくれました。","kana":"ともだち が ほん を くれました。","meaning":"Teman memberi saya buku."},{"jp":"先生が写真をくれました。","kana":"せんせい が しゃしん を くれました。","meaning":"Guru memberi saya foto."}],"order":46,"level":"N5","enrichment":false,"check":{"prompt":"友達が本をくれました。 Apa maksudnya?","options":["Saya memberi buku kepada teman.","Teman memberi buku kepada saya."],"answer":1,"explanation":"くれます menunjukkan pemberian menuju pembicara atau pihak pembicara."}},{"id":"ageru","category":"ungkapan","subcategory":"Memberi & menerima","sourcePages":[19],"title":"～に あげます","kana":"あげます","romaji":"agemasu","meaning":"Memberikan sesuatu kepada orang lain","explanation":"あげます memandang pemberian dari sisi pemberi. Pemberi adalah topik/subjek, penerima ditandai に, dan benda yang diberikan ditandai を.","patterns":["Pemberi + は + penerima + に + benda + を + あげます"],"note":"Pola ini juga dapat menceritakan pemberian antara orang lain. Untuk pemberian kepada pembicara, くれます biasanya menjadi pilihan yang sesuai.","examples":[{"jp":"友達にチョコレートをあげます。","kana":"ともだち に チョコレート を あげます。","meaning":"Saya memberi cokelat kepada teman."},{"jp":"母の誕生日に花をあげました。","kana":"はは の たんじょうび に はな を あげました。","meaning":"Saya memberikan bunga pada ulang tahun ibu."}],"order":47,"level":"N5","enrichment":false},{"id":"mashou","category":"ungkapan","subcategory":"Ajakan & tawaran","sourcePages":[20],"title":"Vましょう","kana":"ましょう","romaji":"mashou","meaning":"Ayo melakukan bersama","explanation":"ましょう mengajak melakukan suatu kegiatan bersama atau menyatakan usulan tindakan. Ganti ます dengan ましょう.","patterns":["Vます tanpa ます + ましょう"],"note":"Ajakan ini cukup langsung. ～ませんか lebih memberi ruang bagi lawan bicara untuk menerima atau menolak.","examples":[{"jp":"一緒に勉強しましょう。","kana":"いっしょに べんきょうしましょう。","meaning":"Ayo belajar bersama."},{"jp":"近いですから、歩きましょう。","kana":"ちかいです から、あるきましょう。","meaning":"Karena dekat, ayo berjalan kaki."}],"order":48,"level":"N5","enrichment":false},{"id":"mashouka","category":"ungkapan","subcategory":"Ajakan & tawaran","sourcePages":[20],"title":"Vましょうか","kana":"ましょうか","romaji":"mashou ka","meaning":"Mau saya bantu? Bagaimana kalau kita …?","explanation":"ましょうか dapat menawarkan tindakan yang akan dilakukan pembicara atau mengusulkan tindakan bersama. Maknanya ditentukan oleh konteks dan siapa yang akan melakukan kegiatan.","patterns":["Vます tanpa ます + ましょうか"],"note":"Ini bukan pola utama untuk menanyakan kemampuan “bisa atau tidak”. 手伝いましょうか berarti “mau saya bantu?”, bukan “apakah kamu bisa membantu?”.","examples":[{"jp":"荷物を持ちましょうか。","kana":"にもつ を もちましょう か。","meaning":"Mau saya bawakan barangnya?"},{"jp":"一緒に行きましょうか。","kana":"いっしょに いきましょう か。","meaning":"Bagaimana kalau kita pergi bersama?"}],"order":49,"level":"N5","enrichment":false,"check":{"prompt":"荷物を持ちましょうか paling sesuai berarti …","options":["Mau saya bawakan barangnya?","Apakah kamu bisa membawa barang?"],"answer":0,"explanation":"ましょうか di sini menawarkan bantuan dari pembicara."}},{"id":"masenka","category":"ungkapan","subcategory":"Ajakan & tawaran","sourcePages":[20],"title":"Vませんか","kana":"ませんか","romaji":"masen ka","meaning":"Mengajak dengan lebih halus","explanation":"Walaupun memakai bentuk negatif, ～ませんか sering berfungsi sebagai ajakan: “maukah …?” atau “bagaimana kalau …?”. Lawan bicara diberi kesempatan memilih.","patterns":["Vます tanpa ます + ませんか"],"note":"Jawaban menerima yang umum adalah いいですね。～ましょう. Jangan menerjemahkannya secara kaku sebagai pertanyaan negatif dalam semua konteks.","examples":[{"jp":"一緒に昼ご飯を食べませんか。","kana":"いっしょに ひるごはん を たべません か。","meaning":"Maukah makan siang bersama?"},{"jp":"日曜日に映画を見ませんか。","kana":"にちようび に えいが を みません か。","meaning":"Bagaimana kalau menonton film hari Minggu?"}],"order":50,"level":"N5","enrichment":false},{"id":"kara-reason","category":"penghubung","subcategory":"Alasan","sourcePages":[23],"title":"～から・～からです","kana":"から・からです","romaji":"kara / kara desu","meaning":"Karena; menyampaikan alasan","explanation":"Letakkan alasan sebelum から, kemudian hasil atau keputusan sesudahnya. Untuk menjawab pertanyaan mengapa, alasan dapat ditutup dengan からです.","patterns":["Alasan + から + hasil","Sifat-na / benda + だから + hasil","Alasan + からです"],"note":"Bentuk sopan seperti ～ですから dan ～ますから juga dapat dipakai. だから setelah kata benda berbeda dari だから di awal kalimat baru.","examples":[{"jp":"暑いから、窓を開けます。","kana":"あつい から、まど を あけます。","meaning":"Karena panas, saya membuka jendela."},{"jp":"今日は休みですから、家にいます。","kana":"きょう は やすみ です から、いえ に います。","meaning":"Karena hari ini libur, saya berada di rumah."}],"order":51,"level":"N5","enrichment":false},{"id":"dakara","category":"penghubung","subcategory":"Alasan","sourcePages":[23],"title":"だから","kana":"だから","romaji":"dakara","meaning":"Oleh karena itu; jadi","explanation":"だから mengawali kalimat kesimpulan atau akibat dari kalimat sebelumnya. Jelaskan alasannya dahulu, lalu sampaikan keputusan atau hasilnya.","patterns":["Kalimat alasan。だから、hasil。"],"note":"Sebagai penghubung antarkalimat, だから tidak ditempelkan pada sifat-i. Gunakan 暑いから dalam satu kalimat, bukan 暑いだから.","examples":[{"jp":"明日はテストです。だから、勉強します。","kana":"あした は テスト です。だから、べんきょうします。","meaning":"Besok ada ujian. Karena itu, saya belajar."},{"jp":"今日は雨です。だから、家にいます。","kana":"きょう は あめ です。だから、いえ に います。","meaning":"Hari ini hujan. Jadi, saya berada di rumah."}],"mistake":{"wrong":"暑いだから、水を飲みます。","correct":"暑いから、水を飲みます。","why":"Setelah sifat-i, langsung gunakan から. だ dipakai setelah benda atau sifat-na dalam bentuk biasa."},"order":52,"level":"N5","enrichment":false},{"id":"demo-shikashi","category":"penghubung","subcategory":"Pertentangan","sourcePages":[23],"title":"でも・しかし・けれども","kana":"でも・しかし・けれども","romaji":"demo / shikashi / keredomo","meaning":"Tetapi, pada awal kalimat berikutnya","explanation":"Kata penghubung ini memperkenalkan informasi yang berlawanan atau berbeda dari kalimat sebelumnya. でも umum dalam percakapan, sedangkan しかし sering dipakai dalam tulisan atau situasi lebih formal.","patterns":["Kalimat A。でも、kalimat B。","Kalimat A。しかし、kalimat B。"],"note":"けれども juga dapat berfungsi sebagai penghubung. Bentuk pendek けど sering muncul dalam percakapan; pelajari sambungannya pada materi ～けど／～が.","examples":[{"jp":"日本語は難しいです。でも、おもしろいです。","kana":"にほんご は むずかしいです。でも、おもしろいです。","meaning":"Bahasa Jepang sulit. Tetapi menarik."},{"jp":"旅行に行きたいです。しかし、時間がありません。","kana":"りょこう に いきたいです。しかし、じかん が ありません。","meaning":"Saya ingin bepergian. Namun, tidak punya waktu."}],"order":53,"level":"N5","enrichment":false},{"id":"kedo-ga","category":"penghubung","subcategory":"Pertentangan","sourcePages":[24],"title":"～けど・～けれど・～が","kana":"けど・けれど・が","romaji":"kedo / keredo / ga","meaning":"Menyambungkan dua hal yang bertentangan","explanation":"けど／けれど menghubungkan dua bagian kalimat dengan arti “tetapi”. Setelah kata benda atau sifat-na bentuk biasa, gunakan だ sebelum けど. が dapat disambungkan setelah bentuk sopan ～です／～ます.","patterns":["Bentuk biasa + けど／けれど","Benda / sifat-na + だけど","Bentuk sopan + が"],"note":"が pada pola ini adalah penghubung kalimat, berbeda dari が penanda subjek. Pola ini juga dapat menjadi pembuka halus sebelum permintaan.","examples":[{"jp":"日本語は難しいですが、おもしろいです。","kana":"にほんご は むずかしいです が、おもしろいです。","meaning":"Bahasa Jepang sulit, tetapi menarik."},{"jp":"今日は暇だけど、明日は忙しいです。","kana":"きょう は ひま だけど、あした は いそがしいです。","meaning":"Hari ini senggang, tetapi besok sibuk."}],"mistake":{"wrong":"今日は暇けど、明日は忙しいです。","correct":"今日は暇だけど、明日は忙しいです。","why":"暇 adalah sifat-na; bentuk biasa sebelum けど memerlukan だ。"},"order":54,"level":"N5","enrichment":false},{"id":"soredewa","category":"penghubung","subcategory":"Peralihan","sourcePages":[24],"title":"それでは・では・じゃ","kana":"それでは・では・それじゃ・じゃ","romaji":"soredewa / dewa / soreja / ja","meaning":"Kalau begitu; beralih ke langkah berikutnya","explanation":"Gunakan untuk merespons keadaan yang baru diketahui atau menutup satu bagian pembicaraan. それでは／では terasa lebih sopan, sedangkan それじゃ／じゃ umum dalam percakapan santai.","patterns":["それでは／では + kalimat","じゃ + usulan / salam penutup"],"note":"では di sini adalah ungkapan peralihan. Jangan selalu menafsirkannya sebagai gabungan partikel tempat で＋は.","examples":[{"jp":"では、また来週。","kana":"では、また らいしゅう。","meaning":"Kalau begitu, sampai minggu depan."},{"jp":"じゃ、タクシーで行きましょう。","kana":"じゃ、タクシー で いきましょう。","meaning":"Kalau begitu, ayo naik taksi."}],"order":55,"level":"N5","enrichment":false},{"id":"degree","category":"keterangan","subcategory":"Derajat","sourcePages":[25],"title":"とても・たいへん・すごく・本当に","kana":"とても・たいへん・すごく・ほんとうに","romaji":"totemo / taihen / sugoku / hontou ni","meaning":"Sangat; benar-benar","explanation":"Kata-kata ini memperkuat sifat atau penilaian. とても dan たいへん dapat berarti sangat. すごく sering dipakai dalam percakapan, sedangkan 本当に menekankan “benar-benar”.","patterns":["とても／たいへん／すごく + sifat","本当に + penilaian"],"note":"たいへん sebelum sifat dapat berarti “sangat”; たいへんです sendiri biasanya berarti sulit, berat, atau merepotkan.","examples":[{"jp":"この料理はとてもおいしいです。","kana":"この りょうり は とても おいしいです。","meaning":"Masakan ini sangat enak."},{"jp":"本当にきれいですね。","kana":"ほんとうに きれい です ね。","meaning":"Benar-benar indah, ya."}],"order":56,"level":"N5","enrichment":false},{"id":"taihen","category":"keterangan","subcategory":"Derajat","sourcePages":[25],"title":"～は大変です","kana":"たいへんです","romaji":"taihen desu","meaning":"Sulit, berat, atau merepotkan","explanation":"大変です dapat menilai sesuatu sebagai pekerjaan berat, keadaan sulit, atau kerepotan. Gunakan は untuk menunjukkan hal yang sedang dinilai.","patterns":["Topik + は + 大変です"],"note":"Jangan menyamakan 大変です (berat/sulit) dengan 大変おいしいです (sangat enak). Posisi dan susunannya mengubah fungsi.","examples":[{"jp":"日本語の勉強は大変です。","kana":"にほんご の べんきょう は たいへん です。","meaning":"Belajar bahasa Jepang itu berat."},{"jp":"毎日の仕事は大変です。","kana":"まいにち の しごと は たいへん です。","meaning":"Pekerjaan setiap hari itu berat."}],"order":57,"level":"N5","enrichment":false},{"id":"amari","category":"keterangan","subcategory":"Derajat","sourcePages":[25],"title":"あまり ～ない","kana":"あまり・あんまり","romaji":"amari / anmari","meaning":"Tidak begitu; tidak terlalu","explanation":"あまり biasanya diikuti predikat negatif dalam pola dasar ini. Kalimat menyatakan derajat atau frekuensi yang rendah, bukan penolakan sepenuhnya.","patterns":["あまり + sifat / kata kerja negatif"],"note":"あんまり adalah bentuk percakapan. Bedakan dari ぜんぜん～ない yang menyatakan “sama sekali tidak”.","examples":[{"jp":"この肉はあまりおいしくないです。","kana":"この にく は あまり おいしくないです。","meaning":"Daging ini tidak begitu enak."},{"jp":"テレビはあまり見ません。","kana":"テレビ は あまり みません。","meaning":"Saya tidak terlalu sering menonton televisi."}],"order":58,"level":"N5","enrichment":false},{"id":"zenzen","category":"keterangan","subcategory":"Derajat","sourcePages":[25],"title":"ぜんぜん ～ない","kana":"ぜんぜん","romaji":"zenzen","meaning":"Sama sekali tidak","explanation":"Pada pola dasar, ぜんぜん memperkuat predikat negatif. Gunakan untuk menyatakan bahwa kemampuan, pemahaman, atau keadaan tertentu sama sekali tidak ada.","patterns":["ぜんぜん + predikat negatif"],"note":"Dalam percakapan modern ada pemakaian positif tertentu, tetapi untuk materi dasar ini fokuskan pada pasangan negatif agar maknanya jelas.","examples":[{"jp":"この漢字は全然わかりません。","kana":"この かんじ は ぜんぜん わかりません。","meaning":"Saya sama sekali tidak memahami kanji ini."},{"jp":"今日は全然寒くないです。","kana":"きょう は ぜんぜん さむくないです。","meaning":"Hari ini sama sekali tidak dingin."}],"order":59,"level":"N5","enrichment":false},{"id":"frequency","category":"keterangan","subcategory":"Frekuensi","sourcePages":[26],"title":"いつも・たいてい・よく・ときどき","kana":"いつも・たいてい・よく・ときどき","romaji":"itsumo / taitei / yoku / tokidoki","meaning":"Selalu, biasanya, sering, dan kadang-kadang","explanation":"Pilih keterangan frekuensi untuk menjelaskan seberapa sering kegiatan terjadi. Kata-kata ini umumnya berada sebelum kegiatan yang diterangkan dan tidak memerlukan partikel に.","patterns":["Topik + keterangan frekuensi + kegiatan"],"note":"よく dalam materi ini berarti sering. Pada きのうはよく寝ました, よく lebih cocok diartikan “dengan nyenyak/baik”.","examples":[{"jp":"朝はいつもパンを食べます。","kana":"あさ は いつも パン を たべます。","meaning":"Pagi hari saya selalu makan roti."},{"jp":"時々、駅で先生に会います。","kana":"ときどき、えき で せんせい に あいます。","meaning":"Kadang-kadang saya bertemu guru di stasiun."}],"table":{"headers":["Kata","Makna"],"rows":[["いつも","Selalu"],["たいてい","Biasanya"],["よく","Sering"],["ときどき","Kadang-kadang"]]},"order":60,"level":"N5","enrichment":false},{"id":"extent","category":"keterangan","subcategory":"Derajat","sourcePages":[26],"title":"まあまあ・ほとんど・だいたい","kana":"まあまあ・ほとんど・だいたい","romaji":"maamaa / hotondo / daitai","meaning":"Lumayan, hampir semua, dan secara umum","explanation":"まあまあ menyatakan tingkat yang sedang atau lumayan. ほとんど berarti hampir seluruhnya dan dapat berubah menjadi “hampir tidak” jika diikuti negatif. だいたい menyatakan gambaran umum atau perkiraan.","patterns":["まあまあ + です","ほとんど + positif / negatif","だいたい + keterangan"],"note":"ほとんどわかります berarti hampir semuanya paham, sedangkan ほとんどわかりません berarti hampir tidak paham. Perhatikan akhir kalimat.","examples":[{"jp":"今日のテストはまあまあでした。","kana":"きょう の テスト は まあまあ でした。","meaning":"Ujian hari ini lumayan."},{"jp":"この本はほとんど読みました。","kana":"この ほん は ほとんど よみました。","meaning":"Saya sudah membaca hampir seluruh buku ini."}],"order":61,"level":"N5","enrichment":false},{"id":"yoku","category":"keterangan","subcategory":"Cara","sourcePages":[26],"title":"よく","kana":"よく","romaji":"yoku","meaning":"Dengan baik, saksama, atau nyenyak","explanation":"Selain “sering”, よく dapat menilai bagaimana kegiatan dilakukan. Maknanya menyesuaikan kata kerja: よく聞く bisa berarti mendengarkan baik-baik dan よく寝る bisa berarti tidur nyenyak.","patterns":["よく + kegiatan"],"note":"Gunakan konteks untuk membedakan frekuensi dan kualitas tindakan. Jangan memaksakan terjemahan “sering” pada setiap よく.","examples":[{"jp":"昨日はよく寝ました。","kana":"きのう は よく ねました。","meaning":"Kemarin saya tidur nyenyak."},{"jp":"先生の話をよく聞いてください。","kana":"せんせい の はなし を よく きいて ください。","meaning":"Tolong dengarkan penjelasan guru baik-baik."}],"order":62,"level":"N5","enrichment":false},{"id":"sakki-sugu","category":"keterangan","subcategory":"Waktu","sourcePages":[27],"title":"さっき・すぐ・もうすぐ","kana":"さっき・すぐ・もうすぐ","romaji":"sakki / sugu / mou sugu","meaning":"Tadi, segera, dan sebentar lagi","explanation":"さっき menunjuk waktu yang baru saja lewat. すぐ menyatakan tindakan dilakukan segera atau tanpa jeda panjang. もうすぐ menunjukkan sesuatu akan terjadi dalam waktu dekat.","patterns":["さっき + kegiatan lampau","すぐ／すぐに + tindakan","もうすぐ + kejadian"],"note":"さっき biasanya dipakai untuk kejadian dekat dalam percakapan, bukan untuk masa lampau yang sangat jauh.","examples":[{"jp":"田中さんはさっき帰りました。","kana":"たなかさん は さっき かえりました。","meaning":"Tanaka pulang tadi."},{"jp":"もうすぐ十二時です。","kana":"もうすぐ じゅうにじ です。","meaning":"Sebentar lagi pukul dua belas."}],"order":63,"level":"N5","enrichment":false},{"id":"motto","category":"keterangan","subcategory":"Derajat","sourcePages":[27],"title":"もっと","kana":"もっと","romaji":"motto","meaning":"Lebih banyak atau lebih lagi","explanation":"もっと meminta atau menyatakan penambahan tingkat, jumlah, maupun intensitas dibanding keadaan sekarang. Tidak selalu perlu menyebutkan pembanding secara langsung.","patterns":["もっと + sifat / kegiatan"],"note":"もう少し berarti “sedikit lagi”; もっと dapat menghendaki penambahan lebih luas. Pilih sesuai maksud.","examples":[{"jp":"もっと食べてください。","kana":"もっと たべて ください。","meaning":"Silakan makan lebih banyak."},{"jp":"もっと日本語を勉強したいです。","kana":"もっと にほんご を べんきょうしたいです。","meaning":"Saya ingin belajar bahasa Jepang lebih banyak lagi."}],"order":64,"level":"N5","enrichment":false},{"id":"mou-mada","category":"keterangan","subcategory":"Waktu","sourcePages":[27],"title":"もう・まだ ～ていません","kana":"もう・まだ","romaji":"mou / mada","meaning":"Sudah atau belum","explanation":"もう dengan kegiatan lampau menyatakan sudah selesai. Untuk “belum melakukan”, pola yang umum adalah まだ～ていません. まだ juga dapat berarti masih saat diikuti keadaan yang berlanjut.","patterns":["もう + Vました","まだ + Vていません","まだ + keadaan yang berlanjut"],"note":"Saat menjawab もう食べましたか, jawaban lengkap yang mudah dipahami adalah はい、もう食べました atau いいえ、まだ食べていません.","examples":[{"jp":"もう昼ご飯を食べました。","kana":"もう ひるごはん を たべました。","meaning":"Saya sudah makan siang."},{"jp":"まだ宿題をしていません。","kana":"まだ しゅくだい を していません。","meaning":"Saya belum mengerjakan PR."}],"mistake":{"wrong":"まだ食べました。","correct":"まだ食べていません。","why":"Untuk menyatakan “belum makan”, gunakan まだ dengan bentuk negatif yang tepat."},"order":65,"level":"N5","enrichment":false},{"id":"adjective-adverb","category":"perubahan","subcategory":"Cara melakukan","sourcePages":[28],"title":"Sifat-i ～く・sifat-na ～に","kana":"く・に","romaji":"ku / ni","meaning":"Melakukan sesuatu dengan cara tertentu","explanation":"Kata sifat dapat menerangkan cara melakukan tindakan. Buang い pada sifat-i lalu tambahkan く. Untuk sifat-na, gunakan に sebelum kata kerja.","patterns":["Sifat-i tanpa い + く + kata kerja","Sifat-na + に + kata kerja"],"note":"いい berubah menjadi よく. 大きく書く berarti menulis dengan ukuran besar, sedangkan 大きい字 berarti huruf yang besar.","examples":[{"jp":"もう少し大きく書いてください。","kana":"もう すこし おおきく かいて ください。","meaning":"Tolong tulis sedikit lebih besar."},{"jp":"静かに話してください。","kana":"しずかに はなして ください。","meaning":"Tolong berbicaralah dengan tenang/pelan."}],"mistake":{"wrong":"静かく話します。","correct":"静かに話します。","why":"静か adalah sifat-na, sehingga memakai に untuk menerangkan cara tindakan."},"order":66,"level":"N5","enrichment":false},{"id":"naru","category":"perubahan","subcategory":"Perubahan keadaan","sourcePages":[28],"title":"～くなります・～になります","kana":"く なります・に なります","romaji":"ku narimasu / ni narimasu","meaning":"Menjadi; mengalami perubahan","explanation":"なります menyatakan perubahan keadaan atau identitas. Sifat-i berubah menjadi ～く, sedangkan sifat-na dan kata benda diikuti に.","patterns":["Sifat-i tanpa い + くなります","Sifat-na / benda + になります"],"note":"いい→よくなります. なります menekankan hasil perubahan, sedangkan ～く／にします menekankan tindakan membuat perubahan.","examples":[{"jp":"寒くなりました。","kana":"さむく なりました。","meaning":"Cuacanya menjadi dingin."},{"jp":"兄は医者になりました。","kana":"あに は いしゃ に なりました。","meaning":"Kakak laki-laki saya menjadi dokter."}],"mistake":{"wrong":"寒いになりました。","correct":"寒くなりました。","why":"Sifat-i memakai ～くなります, bukan ～いになります。"},"order":67,"level":"N5","enrichment":false,"check":{"prompt":"Pilih “Menjadi dingin”.","options":["寒いになります。","寒くなります。"],"answer":1,"explanation":"Sifat-i berubah menjadi ～く sebelum なります."}},{"id":"suru-change","category":"perubahan","subcategory":"Perubahan keadaan","sourcePages":[29],"title":"～くします・～にします","kana":"く します・に します","romaji":"ku shimasu / ni shimasu","meaning":"Membuat sesuatu menjadi …","explanation":"Pola ini menyatakan tindakan yang sengaja mengubah keadaan. Sifat-i memakai ～くします dan sifat-na memakai ～にします.","patterns":["Sifat-i tanpa い + くします","Sifat-na + にします"],"note":"部屋をきれいにします berarti membuat kamar bersih. Bedakan dengan 部屋がきれいになります yang menyatakan kamar menjadi bersih.","examples":[{"jp":"部屋をきれいにします。","kana":"へや を きれいに します。","meaning":"Saya membersihkan kamar."},{"jp":"音を小さくしてください。","kana":"おと を ちいさく して ください。","meaning":"Tolong kecilkan suaranya."}],"order":68,"level":"N5","enrichment":false},{"id":"ni-shimasu","category":"perubahan","subcategory":"Pilihan","sourcePages":[29],"title":"N にします","kana":"に します","romaji":"ni shimasu","meaning":"Memutuskan atau memilih sesuatu","explanation":"Setelah menimbang pilihan, N にします menyatakan keputusan “saya pilih N”. Pola ini sering dipakai saat memesan makanan atau menentukan pilihan.","patterns":["Pilihan + に + します"],"note":"ラーメンにします berarti memilih ramen. Ini berbeda dari ラーメンを作ります yang berarti membuat ramen.","examples":[{"jp":"私はラーメンにします。","kana":"わたし は ラーメン に します。","meaning":"Saya pilih ramen."},{"jp":"飲み物はお茶にします。","kana":"のみもの は おちゃ に します。","meaning":"Untuk minuman, saya pilih teh."}],"order":69,"level":"N5","enrichment":false},{"id":"to-iimasu","category":"ungkapan","subcategory":"Percakapan","sourcePages":[29],"title":"～と言います","kana":"と いいます","romaji":"to iimasu","meaning":"Mengutip ucapan; menyebut sesuatu","explanation":"と menandai isi ucapan sebelum 言います. Untuk menanyakan padanan dalam bahasa Jepang, gunakan 日本語でどう言いますか. 何と言いますか dapat menanyakan sebutan atau ungkapan yang diucapkan.","patterns":["「Ucapan」+ と + 言います","これは日本語でどう言いますか"],"note":"と di sini adalah penanda kutipan. Tanda 「 」 membantu pembaca melihat bagian yang diucapkan.","examples":[{"jp":"「いただきます」と言います。","kana":"「いただきます」 と いいます。","meaning":"Kita mengucapkan “itadakimasu”."},{"jp":"これは日本語でどう言いますか。","kana":"これ は にほんご で どう いいます か。","meaning":"Ini disebut apa dalam bahasa Jepang?"}],"order":70,"level":"N5","enrichment":false},{"id":"toki","category":"waktu","subcategory":"Saat & urutan","sourcePages":[30],"title":"～とき","kana":"とき","romaji":"toki","meaning":"Ketika; pada saat","explanation":"とき menghubungkan keadaan atau kegiatan dengan waktu terjadinya hal lain. Bentuk sebelum とき mengikuti jenis katanya. Pada kata kerja, bentuk kamus dan lampau dapat mengubah hubungan waktunya.","patterns":["Kata kerja bentuk biasa + とき","Sifat-i + とき","Sifat-na + なとき","Kata benda + のとき"],"note":"ひまなとき memerlukan な; 学生のとき memerlukan の. Pelajari perbedaan 行くとき (saat akan/pergi) dan 行ったとき (saat sudah/pernah pergi) melalui konteks.","examples":[{"jp":"本を読むとき、眼鏡をかけます。","kana":"ほん を よむ とき、めがね を かけます。","meaning":"Ketika membaca buku, saya memakai kacamata."},{"jp":"暇なとき、音楽を聞きます。","kana":"ひまな とき、おんがく を ききます。","meaning":"Saat senggang, saya mendengarkan musik."}],"mistake":{"wrong":"暇のとき","correct":"暇なとき","why":"暇 adalah sifat-na, sehingga memakai な sebelum とき。"},"order":71,"level":"N5","enrichment":false},{"id":"mae-ni","category":"waktu","subcategory":"Saat & urutan","sourcePages":[31],"title":"～前に","kana":"まえに","romaji":"mae ni","meaning":"Sebelum; … yang lalu","explanation":"Untuk “sebelum melakukan”, letakkan kata kerja bentuk kamus sebelum 前に. Kata benda memakai の前に. Jika didahului durasi, 前に dapat berarti “… yang lalu”.","patterns":["V kamus + 前に","Kata benda + の前に","Durasi + 前に"],"note":"Walaupun kalimat utamanya lampau, kata kerja sebelum 前に tetap bentuk kamus: 日本へ来る前に勉強しました.","examples":[{"jp":"寝る前に、本を読みます。","kana":"ねる まえに、ほん を よみます。","meaning":"Sebelum tidur, saya membaca buku."},{"jp":"二年前に日本へ来ました。","kana":"にねん まえに にほん へ きました。","meaning":"Saya datang ke Jepang dua tahun yang lalu."}],"mistake":{"wrong":"寝た前に、本を読みます。","correct":"寝る前に、本を読みます。","why":"“Sebelum tidur” memakai bentuk kamus 寝る sebelum 前に。"},"order":72,"level":"N5","enrichment":false,"check":{"prompt":"Isi bagian kosong: ＿＿前に、本を読みます。","options":["寝る","寝た"],"answer":0,"explanation":"Pola “sebelum melakukan” memakai bentuk kamus sebelum 前に."}},{"id":"ato-de","category":"waktu","subcategory":"Saat & urutan","sourcePages":[31],"title":"～た後で・～の後で","kana":"た あとで・の あとで","romaji":"ta ato de / no ato de","meaning":"Setelah kegiatan atau peristiwa","explanation":"Untuk menyatakan setelah melakukan sesuatu, gunakan kata kerja bentuk た sebelum 後で. Kalau yang disebut berupa kata benda, hubungkan dengan の.","patterns":["Vた + 後で","Kata benda + の後で"],"note":"Bentuk た menandai bahwa kegiatan pertama sudah selesai sebelum kegiatan berikutnya, meskipun kegiatan berikutnya masih akan dilakukan.","examples":[{"jp":"ご飯を食べた後で、勉強します。","kana":"ごはん を たべた あとで、べんきょうします。","meaning":"Setelah makan, saya belajar."},{"jp":"授業の後で、買い物をします。","kana":"じゅぎょう の あとで、かいもの を します。","meaning":"Setelah pelajaran, saya berbelanja."}],"mistake":{"wrong":"食べる後で","correct":"食べた後で","why":"Sebelum 後で, gunakan bentuk た untuk kegiatan yang selesai lebih dahulu."},"order":73,"level":"N5","enrichment":false,"check":{"prompt":"Isi bagian kosong: ご飯を＿＿後で、勉強します。","options":["食べる","食べた"],"answer":1,"explanation":"Pola “setelah melakukan” memakai bentuk た sebelum 後で."}},{"id":"purpose-ni","category":"waktu","subcategory":"Tujuan perjalanan","sourcePages":[32],"title":"～に行きます／来ます／帰ります","kana":"に いきます・きます・かえります","romaji":"ni ikimasu / kimasu / kaerimasu","meaning":"Pergi, datang, atau pulang untuk melakukan","explanation":"Sebutkan tujuan kegiatan dengan に sebelum kata kerja perjalanan. Untuk kata kerja, buang ます dahulu. Kata benda kegiatan seperti 買い物 juga dapat langsung diikuti に.","patterns":["Vます tanpa ます + に + 行きます／来ます／帰ります","Kata benda kegiatan + に + 行きます"],"note":"Tempat tujuan dapat disebutkan terpisah dengan へ／に: 図書館へ本を借りに行きます. に setelah 借り menyatakan tujuan kegiatan.","examples":[{"jp":"友達に会いに行きます。","kana":"ともだち に あい に いきます。","meaning":"Saya pergi untuk bertemu teman."},{"jp":"また遊びに来てください。","kana":"また あそび に きて ください。","meaning":"Silakan datang lagi untuk bermain/berkunjung."}],"mistake":{"wrong":"本を借りますに行きます。","correct":"本を借りに行きます。","why":"Buang ます sebelum に pada pola tujuan: 借ります→借りに。"},"order":74,"level":"N5","enrichment":false},{"id":"yori","category":"perbandingan","subcategory":"Dua pilihan","sourcePages":[32],"title":"A は B より ～","kana":"より","romaji":"yori","meaning":"A lebih … daripada B","explanation":"A adalah hal yang dijelaskan, sedangkan B menjadi patokan perbandingan. Sifat di akhir menerangkan kelebihan A dibanding B.","patterns":["A + は + B + より + sifat + です"],"note":"より berarti “daripada”. Perhatikan urutan A dan B agar terjemahan tidak terbalik. Contoh lampau memakai sifat lampau jika membicarakan keadaan kemarin.","examples":[{"jp":"電車はバスより速いです。","kana":"でんしゃ は バス より はやいです。","meaning":"Kereta lebih cepat daripada bus."},{"jp":"昨日は今日より寒かったです。","kana":"きのう は きょう より さむかったです。","meaning":"Kemarin lebih dingin daripada hari ini."}],"order":75,"level":"N5","enrichment":false,"check":{"prompt":"AはBより高いです。 Mana yang lebih mahal?","options":["A","B"],"answer":0,"explanation":"A yang dijelaskan lebih mahal; B adalah patokan setelah より."}},{"id":"houga","category":"perbandingan","subcategory":"Dua pilihan","sourcePages":[33],"title":"A より B のほうが ～","kana":"より・のほうが","romaji":"yori / no hou ga","meaning":"Dibanding A, B lebih …","explanation":"B のほうが menonjolkan sisi B yang lebih memiliki sifat tertentu. A より dapat ditambahkan sebagai pembanding atau dihilangkan jika sudah diketahui.","patterns":["A + より + B + のほうが + sifat","B + のほうが + sifat"],"note":"A は B より高い dan B より A のほうが高い menyampaikan perbandingan yang sama. Yang penting adalah unsur setelah のほうが.","examples":[{"jp":"バスより電車のほうが速いです。","kana":"バス より でんしゃ の ほう が はやいです。","meaning":"Dibanding bus, kereta lebih cepat."},{"jp":"この本のほうがおもしろいです。","kana":"この ほん の ほう が おもしろいです。","meaning":"Buku ini lebih menarik."}],"order":76,"level":"N5","enrichment":false},{"id":"dochira","category":"perbandingan","subcategory":"Dua pilihan","sourcePages":[33],"title":"A と B とどちらが ～","kana":"どちら・どっち","romaji":"dochira / docchi","meaning":"Di antara dua pilihan, mana yang lebih …?","explanation":"どちら membandingkan dua pilihan. Sebutkan A dan B dengan と, lalu tanyakan sifat atau kesukaan yang ingin dibandingkan. どっち adalah bentuk percakapan yang lebih santai.","patterns":["A + と + B + と + どちらが + sifat + ですか"],"note":"Jawaban dapat memakai ～のほうが. Untuk tiga pilihan atau lebih, kata tanya seperti どれ／何 bersama 一番 lebih sesuai.","examples":[{"jp":"犬と猫とどちらが好きですか。","kana":"いぬ と ねこ と どちら が すき です か。","meaning":"Kamu lebih suka anjing atau kucing?"},{"jp":"猫のほうが好きです。","kana":"ねこ の ほう が すき です。","meaning":"Saya lebih suka kucing."}],"order":77,"level":"N5","enrichment":false},{"id":"ichiban","category":"perbandingan","subcategory":"Paling","sourcePages":[34],"title":"～が一番 ～","kana":"いちばん","romaji":"ichiban","meaning":"Yang paling … dalam sebuah kelompok","explanation":"一番 menandai tingkat tertinggi dalam suatu cakupan. Sebutkan cakupannya dengan で, kemudian hal yang paling memiliki sifat itu dengan が.","patterns":["Cakupan + で + A + が + 一番 + sifat","Cakupan + で + 何／どれ／だれ + が + 一番 + sifat + ですか"],"note":"Cakupan penting agar maksud “paling” jelas. Untuk membandingkan dua hal saja, pola どちら／のほうが biasanya lebih sederhana.","examples":[{"jp":"日本では富士山が一番高い山です。","kana":"にほん では ふじさん が いちばん たかい やま です。","meaning":"Di Jepang, Gunung Fuji adalah gunung tertinggi."},{"jp":"日本料理で何が一番好きですか。","kana":"にほんりょうり で なに が いちばん すき です か。","meaning":"Di antara masakan Jepang, apa yang paling kamu sukai?"}],"order":78,"level":"N5","enrichment":false},{"id":"tari","category":"rangkaian","subcategory":"Contoh kegiatan","sourcePages":[34],"title":"～たり ～たりします","kana":"たり・たり します","romaji":"tari / tari shimasu","meaning":"Melakukan kegiatan seperti A dan B","explanation":"～たり menyebut beberapa kegiatan sebagai contoh. Tidak harus mencakup semua kegiatan dan tidak menetapkan urutan waktunya. Tambahkan り setelah bentuk た masing-masing kata kerja, lalu tutup dengan します.","patterns":["Vた + り + Vた + り + します"],"note":"Waktu ditentukan oleh します／しました. Untuk urutan tegas, gunakan Vてから atau rangkaian Vて.","examples":[{"jp":"休みの日は本を読んだり、映画を見たりします。","kana":"やすみ の ひ は ほん を よんだり、えいが を みたり します。","meaning":"Pada hari libur saya melakukan kegiatan seperti membaca buku dan menonton film."},{"jp":"昨日は掃除したり、洗濯したりしました。","kana":"きのう は そうじしたり、せんたくしたり しました。","meaning":"Kemarin saya melakukan kegiatan seperti bersih-bersih dan mencuci pakaian."}],"mistake":{"wrong":"本を読んだり、映画を見たりです。","correct":"本を読んだり、映画を見たりします。","why":"Rangkaian contoh kegiatan ini ditutup dengan します (atau perubahannya)."},"order":79,"level":"N5","enrichment":false},{"id":"koto","category":"kemampuan","subcategory":"Membendakan kegiatan","sourcePages":[35],"title":"Vこと","kana":"こと","romaji":"koto","meaning":"Mengubah kegiatan menjadi hal yang dibicarakan","explanation":"Kata kerja bentuk kamus ditambah こと dapat diperlakukan seperti kata benda. Pola ini dipakai untuk membicarakan hobi atau kegiatan yang disukai.","patterns":["V kamus + こと","趣味は + V kamus + ことです"],"note":"Pada pola definisi hobi 趣味は～ことです, gunakan こと. Menggantinya begitu saja dengan のです dapat menghasilkan fungsi penjelasan yang berbeda.","examples":[{"jp":"私の趣味は映画を見ることです。","kana":"わたし の しゅみ は えいが を みる こと です。","meaning":"Hobi saya menonton film."},{"jp":"走ることが好きです。","kana":"はしる こと が すき です。","meaning":"Saya suka berlari."}],"order":80,"level":"N5","enrichment":false},{"id":"nominal-no","category":"kemampuan","subcategory":"Membendakan kegiatan","sourcePages":[35],"title":"Vの＋は／が／を","kana":"のは","romaji":"no wa","meaning":"Menjadikan kegiatan sebagai topik, subjek, atau objek","explanation":"の setelah kata kerja bentuk biasa membendakan kegiatan. は menjadikannya topik, が dapat menandai hal yang disukai atau ditangkap indra, dan を menandai objek seperti kegiatan yang dilupakan. Partikel dipilih sesuai kata kerja atau penilaian sesudahnya.","patterns":["V bentuk biasa + のは + penilaian","V bentuk biasa + のが + 好きです／見えます","V bentuk biasa + のを + 忘れました"],"note":"Contoh: 泳ぐのが好きです berarti suka berenang; 電話するのを忘れました berarti lupa menelepon. の dan こと tidak selalu dapat saling menggantikan. Penjelasan keluarga pola ini tetap di N5 agar tidak menjadi kartu ganda di N4.","examples":[{"jp":"漢字を覚えるのは大変です。","kana":"かんじ を おぼえる の は たいへん です。","meaning":"Menghafal kanji itu berat."},{"jp":"この機械を使うのは簡単です。","kana":"この きかい を つかう の は かんたん です。","meaning":"Menggunakan mesin ini mudah."}],"order":81,"level":"N5","enrichment":false},{"id":"koto-dekiru","category":"kemampuan","subcategory":"Bisa melakukan","sourcePages":[36],"title":"N ができます・Vことができます","kana":"が できます・ことが できます","romaji":"ga dekimasu / koto ga dekimasu","meaning":"Dapat atau mampu melakukan","explanation":"できます dapat menyatakan kemampuan atau kemungkinan melakukan kegiatan. Kata benda kegiatan dapat langsung diikuti ができます. Kata kerja memakai bentuk kamus＋ことができます.","patterns":["Kata benda kegiatan + が + できます","V kamus + ことが + できます"],"note":"は dapat menggantikan が untuk menonjolkan pertentangan: 話すことはできますが、書くことはできません. Itu bukan berarti は selalu dapat diterjemahkan “kalau”.","examples":[{"jp":"私は料理ができます。","kana":"わたし は りょうり が できます。","meaning":"Saya bisa memasak."},{"jp":"日本語を読むことができます。","kana":"にほんご を よむ こと が できます。","meaning":"Saya bisa membaca bahasa Jepang."}],"mistake":{"wrong":"日本語を読みますことができます。","correct":"日本語を読むことができます。","why":"Sebelum ことができます, gunakan bentuk kamus 読む, bukan 読みます。"},"order":82,"level":"N5","enrichment":false,"check":{"prompt":"Pilih “Bisa membaca bahasa Jepang”.","options":["日本語を読みますことができます。","日本語を読むことができます。"],"answer":1,"explanation":"Sebelum ことができます, gunakan kata kerja bentuk kamus."}},{"id":"potential-verbs","category":"kemampuan","subcategory":"Pengayaan","sourcePages":[37],"title":"Kata kerja potensial","kana":"かのうけい","romaji":"kanoukei","meaning":"Bentuk kata kerja yang berarti “bisa”","explanation":"Bentuk potensial mengungkapkan kemampuan secara langsung. Golongan I mengubah bunyi akhir u menjadi e lalu menambah る. Golongan II membuang る lalu menambah られる. する dan 来る berubah secara khusus.","patterns":["Gol. I: bunyi u → e + る","Gol. II: buang る + られる","する → できる","来る → 来られる (こられる)"],"note":"Pola ini termasuk materi pengayaan. Bentuk standar untuk 見る adalah 見られる. Objek pada kalimat potensial sering memakai が; は dapat menekankan pertentangan.","examples":[{"jp":"私は漢字が少し読めます。","kana":"わたし は かんじ が すこし よめます。","meaning":"Saya bisa membaca sedikit kanji."},{"jp":"明日は何時に来られますか。","kana":"あした は なんじ に こられます か。","meaning":"Besok bisa datang pukul berapa?"}],"table":{"headers":["Kamus","Potensial","Potensial sopan"],"rows":[["読む","読める","読めます"],["見る","見られる","見られます"],["する","できる","できます"],["来る (くる)","来られる (こられる)","来られます (こられます)"]]},"order":83,"level":"N5","enrichment":true}];
const BUNPO_N4_CATEGORIES=[{"id":"forms","name":"Bentuk kata kerja","symbol":"変","color":"mint","description":"Pasif, kausatif, dan bentuk perintah"},{"id":"state","name":"Keadaan & pengamatan","symbol":"見","color":"blue","description":"Kejadian, hasil tindakan, dan indra"},{"id":"condition","name":"Syarat & pengandaian","symbol":"ば","color":"lavender","description":"Kalau, apabila, dan hasil yang mengikuti"},{"id":"rules","name":"Izin & kewajiban","symbol":"可","color":"peach","description":"Boleh, harus, dan tidak perlu"},{"id":"plans","name":"Niat, rencana & tujuan","symbol":"予","color":"pink","description":"Keputusan, usaha, dan tujuan kegiatan"},{"id":"time","name":"Waktu & tahap tindakan","symbol":"時","color":"blue","description":"Rentang, tenggat, dan saat berlangsung"},{"id":"actions","name":"Cara & proses kegiatan","symbol":"行","color":"mint","description":"Pengalaman, persiapan, dan tindakan"},{"id":"giving","name":"Bantuan, saran & perasaan","symbol":"助","color":"lilac","description":"Memberi bantuan dan menyampaikan harapan"},{"id":"particles","name":"Partikel & pembatasan","symbol":"も","color":"peach","description":"Jumlah, batas, bahan, dan contoh"},{"id":"connectors","name":"Alasan & penyusun kalimat","symbol":"結","color":"blue","description":"Hubungan sebab, isi pikiran, dan pertanyaan"},{"id":"inference","name":"Dugaan & kesan","symbol":"想","color":"lavender","description":"Kabar, perkiraan, dan hal yang tampak"},{"id":"morphology","name":"Perubahan & gabungan kata","symbol":"方","color":"mint","description":"Mudah, sulit, cara, dan kadar sifat"},{"id":"polite","name":"Bahasa hormat","symbol":"礼","color":"pink","description":"Menghormati pihak lain dan berbicara resmi"},{"id":"expressions","name":"Ungkapan percakapan","symbol":"話","color":"lilac","description":"Pertanyaan akrab, penekanan, dan nuansa"}];
const BUNPO_N4_DATA=[{"id":"n4-passive","concept":"passive","category":"forms","subcategory":"Bentuk pasif","title":"Bentuk pasif ～れる／～られる","kana":"うけみ","romaji":"ukemi","meaning":"Subjek dikenai suatu tindakan","explanation":"Kalimat pasif memusatkan perhatian pada pihak yang menerima tindakan. Untuk golongan I, ubah bunyi akhir u menjadi a lalu tambah れる; kata berakhiran う menjadi われる. Golongan II membuang る lalu menambah られる. する→される dan 来る→来られる（こられる）.","patterns":["Gol. I: u → a + れる（う → われる）","Gol. II: buang る + られる","Penerima は + pelaku に + V pasif"],"note":"Pasif tidak selalu berarti terganggu. Ada juga pasif netral seperti buku diterbitkan. Bentuk ～られる dapat sama dengan potensial; tentukan fungsi lewat konteks.","examples":[{"jp":"私は先生にほめられました。","kana":"わたし は せんせい に ほめられました。","meaning":"Saya dipuji oleh guru."},{"jp":"この本は多くの国で読まれています。","kana":"この ほん は おおく の くに で よまれて います。","meaning":"Buku ini dibaca di banyak negara."}],"level":"N4","enrichment":false,"order":1,"sources":[{"id":"master","page":263},{"id":"master","page":264},{"id":"master","page":265},{"id":"all","page":69},{"id":"verb","page":43},{"id":"verb","page":44},{"id":"verb","page":45},{"id":"verb","page":46},{"id":"rangkuman","page":15},{"id":"rangkuman","page":43}],"table":{"headers":["Kamus","Pasif"],"rows":[["買う","買われる"],["読む","読まれる"],["食べる","食べられる"],["する","される"],["来る（くる）","来られる（こられる）"]]},"check":{"prompt":"私は先生にほめられました。Siapa yang memuji?","options":["Saya.","Guru."],"answer":1,"explanation":"先生に menandai pelaku; 私 adalah orang yang dipuji."},"searchTerms":[]},{"id":"n4-causative","concept":"causative","category":"forms","subcategory":"Bentuk kausatif","title":"Bentuk kausatif ～せる／～させる","kana":"しえき","romaji":"shieki","meaning":"Menyuruh atau membiarkan seseorang melakukan","explanation":"Kausatif menunjukkan seseorang membuat, menyuruh, atau mengizinkan orang lain melakukan tindakan. Golongan I mengubah u menjadi a lalu menambah せる; う menjadi わせる. Golongan II membuang る lalu menambah させる. する→させる dan 来る→来させる（こさせる）.","patterns":["Gol. I: u → a + せる（う → わせる）","Gol. II: buang る + させる","Penyuruh は + pelaku に + objek を + V kausatif","Penyuruh は + pelaku を + V gerak/intransitif kausatif"],"note":"Pemilihan に／を bergantung kata kerja dan susunan kalimat. Jangan gunakan を dua kali untuk pelaku dan objek. 食べる→食べさせる, bukan たさせる.","examples":[{"jp":"母は子どもに野菜を食べさせました。","kana":"はは は こども に やさい を たべさせました。","meaning":"Ibu menyuruh anak makan sayur."},{"jp":"部長は社員を大阪へ行かせました。","kana":"ぶちょう は しゃいん を おおさか へ いかせました。","meaning":"Kepala bagian menyuruh pegawai pergi ke Osaka."}],"level":"N4","enrichment":false,"order":2,"sources":[{"id":"master","page":167},{"id":"master","page":168},{"id":"master","page":169},{"id":"all","page":70},{"id":"verb","page":47},{"id":"verb","page":48},{"id":"verb","page":49},{"id":"verb","page":50},{"id":"rangkuman","page":15}],"table":{"headers":["Kamus","Kausatif"],"rows":[["買う","買わせる"],["読む","読ませる"],["食べる","食べさせる"],["する","させる"],["来る（くる）","来させる（こさせる）"]]},"check":{"prompt":"Bentuk kausatif 食べる yang benar …","options":["食べさせる","たさせる"],"answer":0,"explanation":"Golongan II membuang る lalu menambah させる."},"mistake":{"wrong":"子どもに野菜をたさせます。","correct":"子どもに野菜を食べさせます。","why":"食べる adalah golongan II: 食べ + させる."},"searchTerms":[]},{"id":"n4-causative-passive","concept":"causative-passive","category":"forms","subcategory":"Kausatif pasif","title":"～させられる","kana":"させられる","romaji":"saserareru","meaning":"Disuruh atau dipaksa melakukan","explanation":"Gabungan kausatif dan pasif menempatkan orang yang harus melakukan tindakan sebagai subjek. Biasanya menunjukkan bahwa tindakan itu terjadi karena kemauan orang lain, sering dengan rasa terpaksa.","patterns":["Bentuk kausatif: buang る + られる","Pelaku は + penyuruh に + V kausatif pasif"],"note":"読む→読ませる→読ませられる. Ada bentuk singkat 読まされる pada banyak kata kerja golongan I, tetapi tidak diterapkan begitu saja pada semuanya. Bentuk lengkap lebih aman dipelajari dulu.","examples":[{"jp":"私は先生に作文を書かせられました。","kana":"わたし は せんせい に さくぶん を かかせられました。","meaning":"Saya disuruh guru menulis karangan."},{"jp":"子どものころ、毎日野菜を食べさせられました。","kana":"こども の ころ、まいにち やさい を たべさせられました。","meaning":"Ketika kecil, saya disuruh makan sayur setiap hari."}],"level":"N4","enrichment":false,"order":3,"sources":[{"id":"master","page":165},{"id":"master","page":166},{"id":"all","page":71}],"table":{"headers":["Kamus","Kausatif pasif"],"rows":[["読む","読ませられる／読まされる"],["話す","話させられる"],["食べる","食べさせられる"],["する","させられる"],["来る（くる）","来させられる（こさせられる）"]]},"searchTerms":[]},{"id":"n4-sasete-kudasai","concept":"sasete-kudasai","category":"forms","subcategory":"Meminta izin bertindak","title":"～させてください","kana":"させてください","romaji":"sasetekudasai","meaning":"Izinkan saya; biarkan saya melakukan","explanation":"Bentuk kausatif diubah ke bentuk て lalu diikuti ください untuk meminta izin melakukan suatu tindakan. Pembicara adalah orang yang ingin bertindak; lawan bicara diminta memberikan izin.","patterns":["V kausatif bentuk て + ください","V kausatif bentuk て + いただけませんか"],"note":"話させてください berarti izinkan saya berbicara, bukan tolong suruh orang lain berbicara. Bentuk ～させていただけませんか lebih sopan.","examples":[{"jp":"少し考えさせてください。","kana":"すこし かんがえさせて ください。","meaning":"Izinkan saya memikirkannya sebentar."},{"jp":"今日は早く帰らせていただけませんか。","kana":"きょう は はやく かえらせて いただけません か。","meaning":"Bolehkah saya pulang lebih awal hari ini?"}],"level":"N4","enrichment":false,"order":4,"sources":[{"id":"master","page":170},{"id":"master","page":171},{"id":"all","page":72}],"check":{"prompt":"考えさせてください berarti …","options":["Tolong pikirkan untuk saya.","Izinkan saya memikirkannya."],"answer":1,"explanation":"Pembicara meminta izin menjadi pelaku tindakan."},"searchTerms":[]},{"id":"n4-imperative","concept":"imperative","category":"forms","subcategory":"Perintah langsung","title":"Bentuk perintah","kana":"めいれいけい","romaji":"meireikei","meaning":"Perintah tegas atau seruan singkat","explanation":"Bentuk perintah dibuat dengan mengubah bunyi akhir u menjadi e untuk golongan I. Golongan II membuang る lalu menambah ろ. Bentuk khusus: する→しろ dan 来る→来い（こい）. Bentuk ini muncul pada instruksi darurat, olahraga, atau situasi sangat langsung.","patterns":["Gol. I: u → e","Gol. II: buang る + ろ","する → しろ","来る → 来い"],"note":"Terdengar keras jika dipakai dalam percakapan biasa. Untuk meminta bantuan sehari-hari, gunakan ～てください atau bentuk yang lebih sopan.","examples":[{"jp":"危ない！止まれ！","kana":"あぶない！とまれ！","meaning":"Bahaya! Berhenti!"},{"jp":"最後まで走れ！","kana":"さいご まで はしれ！","meaning":"Lari sampai akhir!"}],"level":"N4","enrichment":false,"order":5,"sources":[{"id":"all","page":36},{"id":"verb","page":25},{"id":"verb","page":26},{"id":"verb","page":27},{"id":"verb","page":28},{"id":"rangkuman","page":14}],"table":{"headers":["Kamus","Perintah"],"rows":[["買う","買え"],["読む","読め"],["食べる","食べろ"],["する","しろ"],["来る（くる）","来い（こい）"]]},"searchTerms":[]},{"id":"n4-nasai","concept":"nasai","category":"forms","subcategory":"Perintah yang diarahkan","title":"～なさい","kana":"なさい","romaji":"nasai","meaning":"Lakukanlah; perintah dari pihak yang mengarahkan","explanation":"なさい ditambahkan pada pangkal bentuk ます. Sering dipakai orang tua kepada anak, guru kepada murid, atau dalam petunjuk soal. Lebih terarah daripada bentuk perintah kasar, tetapi tetap merupakan perintah.","patterns":["Vます: buang ます + なさい"],"note":"Bukan permintaan sopan untuk atasan. 食べなさい berarti makanlah, bukan larangan; larangan kata kerja dibuat dengan bentuk kamus＋な.","examples":[{"jp":"問題をよく読みなさい。","kana":"もんだい を よく よみなさい。","meaning":"Bacalah soal dengan teliti."},{"jp":"野菜も食べなさい。","kana":"やさい も たべなさい。","meaning":"Makanlah sayurnya juga."}],"level":"N4","enrichment":false,"order":6,"sources":[{"id":"master","page":127},{"id":"master","page":128},{"id":"all","page":37},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-prohibitive-na","concept":"prohibitive-na","category":"forms","subcategory":"Larangan langsung","title":"Vな","kana":"な","romaji":"na","meaning":"Jangan! sebagai larangan tegas","explanation":"Kata kerja bentuk kamus ditambah な menyatakan larangan langsung. Dipakai dalam tanda peringatan, ucapan keras, atau situasi mendesak. Ini berbeda dari sifat-na dan akhiran perintah なさい.","patterns":["V kamus + な"],"note":"Gunakan ～ないでください untuk permintaan sehari-hari yang lebih halus. Perhatikan perbedaannya: 食べなさい berarti makanlah; 食べるな berarti jangan makan.","examples":[{"jp":"ここに入るな。","kana":"ここ に はいる な。","meaning":"Jangan masuk ke sini."},{"jp":"動くな！","kana":"うごく な！","meaning":"Jangan bergerak!"}],"level":"N4","enrichment":false,"order":7,"sources":[{"id":"master","page":113},{"id":"master","page":114},{"id":"all","page":36},{"id":"verb","page":29},{"id":"verb","page":30},{"id":"verb","page":31},{"id":"verb","page":32},{"id":"rangkuman","page":14},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-transitivity","concept":"transitivity","category":"state","subcategory":"Pelaku dan kejadian","title":"自動詞・他動詞","kana":"じどうし・たどうし","romaji":"jidoushi / tadoushi","meaning":"Membedakan benda yang berubah dan tindakan pada benda","explanation":"Kata kerja intransitif menjelaskan apa yang terjadi pada subjek, umumnya dengan が. Kata kerja transitif menjelaskan tindakan pelaku terhadap objek, umumnya dengan を. Pasangan bentuk harus dipelajari sebagai kosakata; tidak semua kata kerja mempunyai pasangan.","patterns":["Benda が + kata kerja intransitif","Pelaku は + benda を + kata kerja transitif"],"note":"Contoh pasangan benar: 開く（あく）↔開ける（あける）, 割れる（われる）↔割る（わる）. 割れる dan 開ける bukan pasangan. Ketiadaan pelaku dalam kalimat tidak selalu berarti kejadian berlangsung tanpa sebab manusia.","examples":[{"jp":"窓が開きました。","kana":"まど が あきました。","meaning":"Jendelanya terbuka."},{"jp":"私が窓を開けました。","kana":"わたし が まど を あけました。","meaning":"Saya membuka jendela itu."}],"level":"N4","enrichment":false,"order":8,"sources":[{"id":"master","page":191},{"id":"master","page":192},{"id":"master","page":193},{"id":"all","page":73},{"id":"all","page":74},{"id":"rangkuman","page":16},{"id":"rangkuman","page":17},{"id":"rangkuman","page":18}],"table":{"headers":["Intransitif（が）","Transitif（を）"],"rows":[["開く（あく）","開ける（あける）"],["閉まる（しまる）","閉める（しめる）"],["割れる（われる）","割る（わる）"],["消える（きえる）","消す（けす）"]]},"searchTerms":[]},{"id":"n4-te-aru","concept":"te-aru","category":"state","subcategory":"Hasil yang disengaja","title":"～てある","kana":"てある","romaji":"tearu","meaning":"Keadaan hasil tindakan yang sengaja dilakukan","explanation":"てある menyatakan suatu keadaan hasil tindakan yang dilakukan dengan maksud tertentu, sering sebagai persiapan. Biasanya memakai kata kerja transitif. Fokus dapat berada pada benda yang sudah disiapkan.","patterns":["Benda が + V transitif bentuk て + あります","（persiapan）benda を + Vてあります"],"note":"窓が開いています hanya menyatakan keadaan jendela terbuka. 窓が開けてあります menyoroti bahwa seseorang sengaja membukanya. Penjelasan keadaan ～ている sendiri tetap di N5.","examples":[{"jp":"机の上に資料が置いてあります。","kana":"つくえ の うえ に しりょう が おいて あります。","meaning":"Dokumen sudah diletakkan di atas meja."},{"jp":"暑いので、窓が開けてあります。","kana":"あつい ので、まど が あけて あります。","meaning":"Karena panas, jendela sengaja dibiarkan terbuka."}],"level":"N4","enrichment":false,"order":9,"sources":[{"id":"all","page":75}],"searchTerms":[]},{"id":"n4-mieru-kikoeru","concept":"mieru-kikoeru","category":"state","subcategory":"Penglihatan dan pendengaran","title":"見える・聞こえる","kana":"みえる・きこえる","romaji":"mieru / kikoeru","meaning":"Terlihat; terdengar tanpa menyoroti usaha","explanation":"見える dan 聞こえる menyatakan sesuatu dapat tertangkap mata atau telinga karena kondisi saat itu. Hal yang terlihat atau terdengar biasanya memakai が. Bedakan dari bentuk potensial yang menyoroti kemampuan atau kesempatan melakukan.","patterns":["Hal が + 見えます","Bunyi が + 聞こえます"],"note":"見られる dan 聞ける adalah bentuk potensial yang sudah diperkenalkan di N5. 見える tidak sama dengan 見られる, dan 聞こえる tidak sama dengan 聞ける.","examples":[{"jp":"ここから海が見えます。","kana":"ここ から うみ が みえます。","meaning":"Dari sini laut terlihat."},{"jp":"隣の部屋から音楽が聞こえます。","kana":"となり の へや から おんがく が きこえます。","meaning":"Terdengar musik dari kamar sebelah."}],"level":"N4","enrichment":false,"order":10,"sources":[{"id":"all","page":43}],"searchTerms":[]},{"id":"n4-ga-suru","concept":"ga-suru","category":"state","subcategory":"Kesan indra","title":"～がする","kana":"がする","romaji":"gasuru","meaning":"Terasa; tercium; terdengar suatu kesan","explanation":"Nがする menyatakan indra menangkap bunyi, bau, atau rasa. Kata benda seperti 音, 声, におい, dan 味 menjadi hal yang dirasakan.","patterns":["音 / 声 / におい / 味 + がします"],"note":"する di sini bukan melakukan benda itu. 音がする berarti ada bunyi yang terdengar, bukan membuat suara dengan sengaja.","examples":[{"jp":"台所からいいにおいがします。","kana":"だいどころ から いい におい が します。","meaning":"Tercium aroma harum dari dapur."},{"jp":"このスープは変な味がします。","kana":"この スープ は へんな あじ が します。","meaning":"Sup ini terasa aneh."}],"level":"N4","enrichment":false,"order":11,"sources":[{"id":"master","page":39},{"id":"master","page":40}],"searchTerms":[]},{"id":"n4-ni-ki-ga-tsuku","concept":"ni-ki-ga-tsuku","category":"state","subcategory":"Menyadari","title":"～に気がつく","kana":"にきがつく","romaji":"nikigatsuku","meaning":"Menyadari; baru memperhatikan adanya hal","explanation":"気がつく menyatakan bahwa perhatian seseorang menangkap suatu hal yang sebelumnya tidak disadari. Hal yang disadari ditandai に; untuk kegiatan atau keadaan, gunakan のに.","patterns":["N + に気がつきます","V bentuk biasa + のに気がつきます"],"note":"Bentuk 気をつける berarti berhati-hati, bukan menyadari. Perhatikan perbedaan partikel dan kata kerjanya.","examples":[{"jp":"間違いに気がつきました。","kana":"まちがい に き が つきました。","meaning":"Saya menyadari kesalahannya."},{"jp":"財布がないのに気がつきました。","kana":"さいふ が ない の に き が つきました。","meaning":"Saya baru menyadari bahwa dompet saya tidak ada."}],"level":"N4","enrichment":false,"order":12,"sources":[{"id":"master","page":131},{"id":"master","page":132}],"searchTerms":[]},{"id":"n4-ba","concept":"ba","category":"condition","subcategory":"Syarat umum","title":"～ば","kana":"ば","romaji":"ba","meaning":"Jika syarat A terpenuhi, B terjadi","explanation":"Gunakan ～ば untuk menyebut syarat yang memungkinkan hasil berikutnya. Untuk kata kerja golongan I, ubah bunyi akhir u menjadi e lalu tambah ば. Golongan II membuang る lalu menambah れば. Bentuk khusus: する→すれば dan 来る→来れば（くれば）.","patterns":["V gol. I: u → e + ば","V gol. II: buang る + れば","Sifat-i: buang い + ければ","Bentuk negatif: ない → なければ"],"note":"いい menjadi よければ. Untuk meminta orang melakukan sesuatu setelah suatu tindakan selesai, ～たら sering lebih mudah digunakan. Sifat-na dan kata benda dapat memakai ～なら.","examples":[{"jp":"安ければ、このかばんを買います。","kana":"やすければ、この かばん を かいます。","meaning":"Jika murah, saya akan membeli tas ini."},{"jp":"時間があれば、手伝えます。","kana":"じかん が あれば、てつだえます。","meaning":"Kalau ada waktu, saya bisa membantu."}],"level":"N4","enrichment":false,"order":13,"sources":[{"id":"master","page":18},{"id":"master","page":19},{"id":"master","page":20},{"id":"master","page":21},{"id":"master","page":22},{"id":"all","page":57},{"id":"all","page":58},{"id":"verb","page":37},{"id":"verb","page":38},{"id":"verb","page":39},{"id":"verb","page":40},{"id":"verb","page":41},{"id":"verb","page":42},{"id":"rangkuman","page":15},{"id":"rangkuman","page":44}],"table":{"headers":["Dasar","Syarat"],"rows":[["買う","買えば"],["読む","読めば"],["食べる","食べれば"],["する","すれば"],["来る（くる）","来れば（くれば）"],["高い","高ければ"],["いい","よければ"],["ない","なければ"]]},"searchTerms":[]},{"id":"n4-tara","concept":"tara","category":"condition","subcategory":"Setelah syarat terpenuhi","title":"～たら","kana":"たら","romaji":"tara","meaning":"Kalau; setelah sesuatu terjadi","explanation":"Bentuk ～たら dibuat dengan menambahkan ら pada bentuk lampau biasa. Pola ini dipakai untuk syarat yang dibayangkan maupun langkah yang dilakukan setelah A selesai. Bagian B dapat berupa ajakan, permintaan, atau niat.","patterns":["Vた + ら","Sifat-i: ～かったら","Sifat-na / N: ～だったら","Negatif: ～なかったら"],"note":"Bentuk た di sini tidak selalu berarti masa lalu. ご飯を食べたら出かけます berarti akan pergi setelah makan, bukan sudah makan.","examples":[{"jp":"仕事が終わったら、電話してください。","kana":"しごと が おわったら、でんわ して ください。","meaning":"Setelah pekerjaan selesai, tolong telepon saya."},{"jp":"雨だったら、家にいます。","kana":"あめ だったら、いえ に います。","meaning":"Kalau hujan, saya akan berada di rumah."}],"level":"N4","enrichment":false,"order":14,"sources":[{"id":"master","page":197},{"id":"master","page":198},{"id":"all","page":57},{"id":"rangkuman","page":42},{"id":"rangkuman","page":46}],"searchTerms":[]},{"id":"n4-conditional-to","concept":"conditional-to","category":"condition","subcategory":"Hasil yang tetap","title":"～と（条件）","kana":"と","romaji":"to","meaning":"Kalau A terjadi, biasanya B mengikuti","explanation":"Gunakan と untuk hubungan yang tetap atau berulang: cara kerja alat, gejala alam, kebiasaan, atau petunjuk jalan. Bagian sebelum と memakai bentuk biasa bukan lampau. Hasilnya dipandang mengikuti syarat secara alami.","patterns":["V kamus / Vない + と","Sifat-i + と","Sifat-na / N + だと"],"note":"Untuk ajakan atau permintaan sebagai akibat langsung, gunakan ～たら, bukan pola otomatis と. Ini berbeda dari partikel と yang berarti bersama atau dan.","examples":[{"jp":"このボタンを押すと、電気がつきます。","kana":"この ボタン を おす と、でんき が つきます。","meaning":"Kalau tombol ini ditekan, lampunya menyala."},{"jp":"春になると、暖かくなります。","kana":"はる に なる と、あたたかく なります。","meaning":"Saat musim semi tiba, cuaca menjadi hangat."}],"level":"N4","enrichment":false,"order":15,"sources":[{"id":"master","page":239},{"id":"master","page":240},{"id":"all","page":59},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-nara","concept":"nara","category":"condition","subcategory":"Menanggapi informasi","title":"～なら","kana":"なら","romaji":"nara","meaning":"Kalau memang; kalau yang dimaksud …","explanation":"なら mengambil informasi atau rencana yang sedang dibicarakan sebagai syarat. Pembicara lalu memberi saran atau tanggapan yang sesuai. Saran itu dapat dilakukan sebelum kegiatan yang disebutkan.","patterns":["V / sifat-i bentuk biasa + なら","Sifat-na / N + なら"],"note":"日本へ行くなら bermakna kalau kamu akan pergi ke Jepang. Berbeda dari 行ったら yang dapat berarti setelah tiba di Jepang.","examples":[{"jp":"日本へ行くなら、この本を読んでください。","kana":"にほん へ いく なら、この ほん を よんで ください。","meaning":"Kalau akan pergi ke Jepang, bacalah buku ini."},{"jp":"静かな部屋なら、ここがいいです。","kana":"しずかな へや なら、ここ が いい です。","meaning":"Kalau mencari kamar yang tenang, yang ini cocok."}],"level":"N4","enrichment":false,"order":16,"sources":[{"id":"master","page":125},{"id":"master","page":126},{"id":"all","page":57},{"id":"all","page":58},{"id":"verb","page":37},{"id":"verb","page":38},{"id":"verb","page":39},{"id":"verb","page":40},{"id":"verb","page":41},{"id":"verb","page":42},{"id":"rangkuman","page":44}],"searchTerms":[]},{"id":"n4-baai","concept":"baai","category":"condition","subcategory":"Keadaan tertentu","title":"～場合は","kana":"ばあいは","romaji":"baaiha","meaning":"Apabila terjadi keadaan tertentu","explanation":"場合は memperkenalkan keadaan yang menjadi dasar petunjuk atau tindakan. Pola ini sering muncul dalam aturan, pengumuman, dan penjelasan tentang cara menangani masalah.","patterns":["V bentuk biasa + 場合は","Sifat-i + 場合は","Sifat-na + な場合は","N + の場合は"],"note":"Bukan sekadar ketika di masa lalu. Pola ini menyoroti suatu kasus atau situasi yang perlu ditangani.","examples":[{"jp":"遅れる場合は、連絡してください。","kana":"おくれる ばあい は、れんらく して ください。","meaning":"Jika akan terlambat, tolong hubungi kami."},{"jp":"地震の場合は、エレベーターを使わないでください。","kana":"じしん の ばあい は、エレベーター を つかわないで ください。","meaning":"Jika terjadi gempa, jangan gunakan lift."}],"level":"N4","enrichment":false,"order":17,"sources":[{"id":"master","page":23},{"id":"master","page":24},{"id":"rangkuman","page":50}],"searchTerms":[]},{"id":"n4-obligation","concept":"obligation","category":"rules","subcategory":"Kewajiban","title":"～なければならない","kana":"なければならない・なくてはいけない","romaji":"nakerebanaranai / nakutehaikenai","meaning":"Harus melakukan sesuatu","explanation":"Pola negatif bersyarat diikuti ならない atau いけない menyatakan kewajiban: sesuatu tidak boleh dibiarkan tidak dilakukan. Mulailah dari bentuk ない, lalu ubah sesuai rumus.","patterns":["Vない: buang ない + なければならない","Vない: buang ない + なくてはいけない","Vない + といけない"],"note":"Bentuk sopannya なければなりません／なくてはいけません. Dalam percakapan ada なきゃ／なくちゃ. Tulis 行かなければ, bukan 行かないければ.","examples":[{"jp":"明日までに、この書類を出さなければなりません。","kana":"あした まで に、この しょるい を ださなければ なりません。","meaning":"Saya harus menyerahkan dokumen ini paling lambat besok."},{"jp":"薬を飲まないといけません。","kana":"くすり を のまない と いけません。","meaning":"Saya harus minum obat."}],"level":"N4","enrichment":false,"order":18,"sources":[{"id":"master","page":121},{"id":"master","page":122},{"id":"master","page":123},{"id":"master","page":124},{"id":"all","page":21},{"id":"rangkuman","page":42}],"check":{"prompt":"Pilih bentuk yang benar untuk “harus pergi”.","options":["行かないければなりません。","行かなければなりません。"],"answer":1,"explanation":"Mulai dari 行かない; ない diubah menjadi なければ."},"mistake":{"wrong":"行かないければなりません。","correct":"行かなければなりません。","why":"ない diubah menjadi なければ. Tidak mempertahankan い sebelum ければ."},"searchTerms":["nakereba ikenai","nakutewa ikenai","naito ikenai","なければいけない","なくてはいけない","ないといけない"]},{"id":"n4-temo-ii","concept":"temo-ii","category":"rules","subcategory":"Izin","title":"～てもいい","kana":"てもいい","romaji":"temoii","meaning":"Boleh melakukan; meminta izin","explanation":"Bentuk て ditambah もいい menyatakan bahwa suatu tindakan diizinkan. Tambahkan ですか untuk meminta izin. Bentuk ～てもいいでしょうか terasa lebih hati-hati ketika meminta izin kepada atasan atau orang yang belum akrab.","patterns":["Vて + もいいです","Vて + もいいですか","Vて + もいいでしょうか"],"note":"Untuk menjawab izin dari orang yang lebih tinggi kedudukannya, jawaban seperti はい、どうぞ sering lebih luwes daripada terdengar sedang memberi penilaian kepada orang itu.","examples":[{"jp":"ここで写真を撮ってもいいですか。","kana":"ここ で しゃしん を とって も いい です か。","meaning":"Bolehkah saya mengambil foto di sini?"},{"jp":"この辞書を使ってもいいです。","kana":"この じしょ を つかって も いい です。","meaning":"Kamus ini boleh dipakai."}],"level":"N4","enrichment":false,"order":19,"sources":[{"id":"all","page":22},{"id":"rangkuman","page":41}],"searchTerms":[]},{"id":"n4-tewa-ikenai","concept":"tewa-ikenai","category":"rules","subcategory":"Larangan","title":"～てはいけない","kana":"てはいけない","romaji":"tehaikenai","meaning":"Tidak boleh melakukan sesuatu","explanation":"Gunakan ～てはいけない untuk menyatakan larangan atau aturan. Bentuk てはだめです memiliki maksud serupa. Ini lebih tegas daripada permintaan halus ～ないでください yang sudah dipelajari di N5.","patterns":["Vて + はいけません","Vて + はだめです"],"note":"Dalam percakapan, ては dapat menjadi ちゃ dan では menjadi じゃ: 入っちゃだめ. Larangan ini berbeda dari ～なくてもいい yang justru berarti tidak wajib.","examples":[{"jp":"ここに車を止めてはいけません。","kana":"ここ に くるま を とめて は いけません。","meaning":"Tidak boleh memarkir mobil di sini."},{"jp":"この水を飲んではいけません。","kana":"この みず を のんで は いけません。","meaning":"Air ini tidak boleh diminum."}],"level":"N4","enrichment":false,"order":20,"sources":[{"id":"all","page":22},{"id":"rangkuman","page":41}],"searchTerms":[]},{"id":"n4-nakutemo-ii","concept":"nakutemo-ii","category":"rules","subcategory":"Tidak wajib","title":"～なくてもいい","kana":"なくてもいい","romaji":"nakutemoii","meaning":"Tidak perlu; boleh tidak melakukan","explanation":"Pola ini membebaskan seseorang dari kewajiban. Ubah ない menjadi なくて, lalu tambah もいい. Tindakannya boleh dilakukan, tetapi tidak harus.","patterns":["Vない: buang ない + なくてもいいです"],"note":"来なくてもいい berarti tidak perlu datang, bukan dilarang datang. Untuk larangan gunakan 来てはいけません.","examples":[{"jp":"明日は早く来なくてもいいです。","kana":"あした は はやく こなくて も いい です。","meaning":"Besok tidak perlu datang lebih awal."},{"jp":"名前を書かなくてもいいですか。","kana":"なまえ を かかなくて も いい です か。","meaning":"Bolehkah saya tidak menulis nama?"}],"level":"N4","enrichment":false,"order":21,"sources":[{"id":"all","page":22},{"id":"rangkuman","page":42}],"check":{"prompt":"来なくてもいいです berarti …","options":["Tidak perlu datang.","Tidak boleh datang."],"answer":0,"explanation":"なくてもいい membebaskan kewajiban; bukan larangan."},"mistake":{"wrong":"来ないくてもいいです。","correct":"来なくてもいいです。","why":"ない diubah menjadi なくて sebelum もいい."},"searchTerms":[]},{"id":"n4-naide","concept":"naide","category":"rules","subcategory":"Tanpa melakukan","title":"～ないで","kana":"ないで","romaji":"naide","meaning":"Melakukan B tanpa melakukan A","explanation":"Bentuk ない ditambah で menghubungkan tindakan yang tidak dilakukan dengan tindakan berikutnya. Kedua tindakan biasanya mempunyai pelaku yang sama. Pola ini menjelaskan cara atau keadaan saat melakukan B.","patterns":["Vない + で + B"],"note":"Jangan samakan dengan ～なくて yang dapat menjelaskan sebab atau menghubungkan keadaan. ～ないでください sebagai permintaan larangan sudah ada di N5.","examples":[{"jp":"朝ご飯を食べないで、学校へ行きました。","kana":"あさごはん を たべないで、がっこう へ いきました。","meaning":"Saya berangkat ke sekolah tanpa sarapan."},{"jp":"辞書を見ないで、答えてください。","kana":"じしょ を みないで、こたえて ください。","meaning":"Jawablah tanpa melihat kamus."}],"level":"N4","enrichment":false,"order":22,"sources":[{"id":"rangkuman","page":42}],"check":{"prompt":"辞書を見ないで答えてください berarti …","options":["Jawab tanpa melihat kamus.","Lihat kamus sebelum menjawab."],"answer":0,"explanation":"ないで menunjukkan tindakan yang tidak dilakukan saat melakukan hal berikutnya."},"searchTerms":[]},{"id":"n4-necessary","concept":"necessary","category":"rules","subcategory":"Kebutuhan","title":"Nが必要・V必要がある","kana":"ひつよう","romaji":"hitsuyou","meaning":"Perlu; ada kebutuhan melakukan","explanation":"Nが必要 menyatakan benda atau hal yang diperlukan. V必要がある menyatakan perlunya suatu tindakan. Bentuk negatifnya berarti tindakan tidak perlu dilakukan.","patterns":["N + が必要です","V kamus + 必要があります","V kamus + 必要はありません"],"note":"必要 menjelaskan kebutuhan. ～なければならない lebih langsung menyatakan kewajiban. Kata benda dapat menerangkan benda lain sebagai 必要なN.","examples":[{"jp":"申込みには写真が必要です。","kana":"もうしこみ に は しゃしん が ひつよう です。","meaning":"Foto diperlukan untuk pendaftaran."},{"jp":"もう一度確認する必要があります。","kana":"もう いちど かくにん する ひつよう が あります。","meaning":"Perlu memeriksanya sekali lagi."}],"level":"N4","enrichment":false,"order":23,"sources":[{"id":"master","page":37},{"id":"master","page":38},{"id":"master","page":55},{"id":"master","page":56},{"id":"master","page":57}],"searchTerms":["ga hitsuyou","hitsuyou ga aru","がひつよう","ひつようがある"]},{"id":"n4-volitional","concept":"volitional","category":"plans","subcategory":"Bentuk ajakan biasa","title":"Bentuk kehendak ～よう／～おう","kana":"いこうけい","romaji":"ikoukei","meaning":"Ayo; menyatakan kehendak","explanation":"Bentuk kehendak dipakai untuk mengajak secara akrab atau menyatakan kemauan sendiri. Golongan I mengubah bunyi akhir u menjadi o lalu menambah う. Golongan II membuang る lalu menambah よう. Bentuk khusus: する→しよう dan 来る→来よう（こよう）.","patterns":["Gol. I: u → o + う","Gol. II: buang る + よう","する → しよう","来る → 来よう"],"note":"Ajakan sopan ～ましょう sudah ada di N5. Di sini yang dipelajari adalah bentuk biasa dan pembentukannya, misalnya 行く→行こう dan 食べる→食べよう.","examples":[{"jp":"一緒に帰ろう。","kana":"いっしょ に かえろう。","meaning":"Ayo pulang bersama."},{"jp":"少し休もう。","kana":"すこし やすもう。","meaning":"Ayo istirahat sebentar."}],"level":"N4","enrichment":false,"order":24,"sources":[{"id":"master","page":58},{"id":"master","page":59},{"id":"master","page":60},{"id":"all","page":55},{"id":"verb","page":33},{"id":"verb","page":34},{"id":"verb","page":35},{"id":"verb","page":36},{"id":"rangkuman","page":14}],"table":{"headers":["Kamus","Kehendak","Golongan"],"rows":[["買う","買おう","I"],["待つ","待とう","I"],["読む","読もう","I"],["食べる","食べよう","II"],["する","しよう","III"],["来る（くる）","来よう（こよう）","III"]]},"searchTerms":[]},{"id":"n4-volitional-plan","concept":"volitional-plan","category":"plans","subcategory":"Niat yang dipikirkan","title":"～ようと思う","kana":"ようとおもう","romaji":"youtoomou","meaning":"Berniat; sedang berencana untuk","explanation":"Bentuk kehendak ditambah と思う menyatakan niat pembicara. ～と思っています menunjukkan bahwa niat itu sudah dipikirkan dan masih dimiliki. Bentuk ini juga dapat melaporkan niat orang lain jika diketahui.","patterns":["V bentuk kehendak + と思います","V bentuk kehendak + と思っています"],"note":"Tidak ada angka persentase pasti untuk kekuatan niat. Bedakan dari V kamus＋と思う yang dapat sekadar berarti mengira suatu tindakan akan terjadi.","examples":[{"jp":"来年、日本へ行こうと思っています。","kana":"らいねん、にほん へ いこう と おもって います。","meaning":"Saya berencana pergi ke Jepang tahun depan."},{"jp":"今日は早く寝ようと思います。","kana":"きょう は はやく ねよう と おもいます。","meaning":"Hari ini saya berniat tidur lebih awal."}],"level":"N4","enrichment":false,"order":25,"sources":[{"id":"master","page":285},{"id":"master","page":286},{"id":"master","page":287},{"id":"all","page":55},{"id":"rangkuman","page":43}],"searchTerms":[]},{"id":"n4-tsumori","concept":"tsumori","category":"plans","subcategory":"Niat pribadi","title":"～つもりだ","kana":"つもりだ","romaji":"tsumorida","meaning":"Bermaksud; berniat melakukan","explanation":"つもり menyatakan niat yang sudah ada pada diri seseorang. Kata kerja bentuk kamus dipakai untuk niat melakukan, sedangkan bentuk ない untuk niat tidak melakukan.","patterns":["V kamus + つもりです","Vない + つもりです"],"note":"行かないつもり berarti berniat tidak pergi. 行くつもりはありません berarti tidak mempunyai niat pergi. Jangan memberi persentase kepastian yang kaku.","examples":[{"jp":"週末は家で勉強するつもりです。","kana":"しゅうまつ は いえ で べんきょう する つもり です。","meaning":"Akhir pekan ini saya berniat belajar di rumah."},{"jp":"今年は車を買わないつもりです。","kana":"ことし は くるま を かわない つもり です。","meaning":"Tahun ini saya berniat tidak membeli mobil."}],"level":"N4","enrichment":false,"order":26,"sources":[{"id":"all","page":56},{"id":"rangkuman","page":46}],"searchTerms":[]},{"id":"n4-yotei","concept":"yotei","category":"plans","subcategory":"Rencana terjadwal","title":"～予定だ","kana":"よていだ","romaji":"yoteida","meaning":"Dijadwalkan; direncanakan","explanation":"予定 menjelaskan rencana atau jadwal yang sudah disusun. Dibanding つもり yang berpusat pada niat pribadi, 予定 lebih menyoroti susunan kegiatan atau agenda.","patterns":["V kamus + 予定です","N + の予定です"],"note":"Rencana masih dapat berubah. Penggunaan 予定 tidak berarti hasilnya dijamin terjadi.","examples":[{"jp":"会議は三時に始まる予定です。","kana":"かいぎ は さんじ に はじまる よてい です。","meaning":"Rapat dijadwalkan mulai pukul tiga."},{"jp":"明日は休みの予定です。","kana":"あした は やすみ の よてい です。","meaning":"Besok dijadwalkan libur."}],"level":"N4","enrichment":false,"order":27,"sources":[{"id":"master","page":275},{"id":"master","page":276},{"id":"all","page":56},{"id":"rangkuman","page":40},{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-koto-ni-suru","concept":"koto-ni-suru","category":"plans","subcategory":"Keputusan sendiri","title":"～ことにする","kana":"ことにする","romaji":"kotonisuru","meaning":"Memutuskan untuk melakukan atau tidak melakukan","explanation":"Gunakan ことにする ketika pembicara mengambil keputusan tentang suatu tindakan. Bentuk ～ことにしています menyatakan keputusan yang dijalankan sebagai kebiasaan atau aturan pribadi.","patterns":["V kamus / Vない + ことにします","V kamus / Vない + ことにしています"],"note":"Ini berbeda dari Nにします pada N5 yang memilih benda atau pilihan, misalnya コーヒーにします.","examples":[{"jp":"毎朝、歩くことにしました。","kana":"まいあさ、あるく こと に しました。","meaning":"Saya memutuskan untuk berjalan kaki setiap pagi."},{"jp":"夜はお菓子を食べないことにしています。","kana":"よる は おかし を たべない こと に して います。","meaning":"Saya membiasakan diri tidak makan camilan pada malam hari."}],"level":"N4","enrichment":false,"order":28,"sources":[{"id":"master","page":92},{"id":"master","page":93},{"id":"all","page":18}],"searchTerms":[]},{"id":"n4-koto-ni-naru","concept":"koto-ni-naru","category":"plans","subcategory":"Keputusan atau ketetapan","title":"～ことになる","kana":"ことになる","romaji":"kotoninaru","meaning":"Diputuskan; ditetapkan bahwa","explanation":"ことになる menyampaikan keputusan, jadwal, atau hasil keadaan tanpa menonjolkan siapa yang memutuskannya. Sering dipakai untuk keputusan organisasi atau perubahan yang memengaruhi pembicara.","patterns":["V kamus / Vない + ことになります","V kamus / Vない + ことになっています"],"note":"～ことになっています juga dapat menyatakan aturan yang berlaku. Jangan menganggap pembicara pasti sama sekali tidak terlibat dalam keputusan itu.","examples":[{"jp":"来月、大阪へ転勤することになりました。","kana":"らいげつ、おおさか へ てんきん する こと に なりました。","meaning":"Sudah diputuskan bahwa saya akan pindah tugas ke Osaka bulan depan."},{"jp":"ここでは靴を脱ぐことになっています。","kana":"ここ では くつ を ぬぐ こと に なって います。","meaning":"Aturan di sini mengharuskan melepas sepatu."}],"level":"N4","enrichment":false,"order":29,"sources":[{"id":"master","page":90},{"id":"master","page":91},{"id":"all","page":19}],"searchTerms":[]},{"id":"n4-tameni","concept":"tameni","category":"plans","subcategory":"Tujuan yang disengaja","title":"～ために","kana":"ために","romaji":"tameni","meaning":"Untuk; demi mencapai tujuan","explanation":"ために menyebut tujuan yang ingin dicapai melalui tindakan yang disengaja. Untuk kata kerja, gunakan bentuk kamus. Untuk orang, benda, atau kepentingan tertentu, gunakan Nのために.","patterns":["V kamus + ために、tindakan","N + のために、tindakan"],"note":"Untuk tujuan berupa keadaan yang tidak mudah dikendalikan atau bentuk potensial, ～ように biasanya lebih cocok: 聞こえるように. Materi ini berfokus pada tujuan, bukan ために sebagai sebab formal.","examples":[{"jp":"留学するために、お金を貯めています。","kana":"りゅうがく する ため に、おかね を ためて います。","meaning":"Saya menabung untuk belajar di luar negeri."},{"jp":"家族のために、働いています。","kana":"かぞく の ため に、はたらいて います。","meaning":"Saya bekerja demi keluarga."}],"level":"N4","enrichment":false,"order":30,"sources":[{"id":"all","page":29},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-youni-purpose","concept":"youni-purpose","category":"plans","subcategory":"Tujuan berupa keadaan","title":"～ように（目的）","kana":"ように","romaji":"youni","meaning":"Agar; supaya suatu keadaan tercapai","explanation":"Gunakan ように untuk keadaan yang diharapkan terjadi, seperti bisa mendengar, tidak lupa, atau tidak terlambat. Bagian tujuan sering berupa kata kerja potensial atau bentuk ない.","patterns":["V kamus / V potensial / Vない + ように、tindakan"],"note":"Di sini, ように berarti agar, bukan sepertinya. Subjek pada tujuan dan tindakan dapat berbeda, misalnya anak bisa membaca karena orang tua mengajarinya.","examples":[{"jp":"忘れないように、メモします。","kana":"わすれない よう に、メモ します。","meaning":"Saya mencatat supaya tidak lupa."},{"jp":"後ろの人にも聞こえるように、大きな声で話します。","kana":"うしろ の ひと に も きこえる よう に、おおきな こえ で はなします。","meaning":"Saya berbicara keras agar orang di belakang juga dapat mendengar."}],"level":"N4","enrichment":false,"order":31,"sources":[{"id":"all","page":30},{"id":"rangkuman","page":40},{"id":"rangkuman","page":46}],"searchTerms":[]},{"id":"n4-youni-suru","concept":"youni-suru","category":"plans","subcategory":"Usaha dan kebiasaan","title":"～ようにする","kana":"ようにする","romaji":"younisuru","meaning":"Berusaha; mengusahakan kebiasaan","explanation":"ようにする menyatakan usaha sadar agar suatu tindakan dilakukan atau dihindari. ～ようにしています menekankan usaha yang dipelihara sebagai kebiasaan. ～ようにしてください meminta orang mengusahakan hal itu.","patterns":["V kamus / Vない + ようにします","V kamus / Vない + ようにしています"],"note":"Berbeda dari ことにする yang menyoroti keputusan, ようにする menyoroti upaya menjalankannya.","examples":[{"jp":"毎日、日本語で話すようにしています。","kana":"まいにち、にほんご で はなす よう に して います。","meaning":"Saya berusaha berbicara bahasa Jepang setiap hari."},{"jp":"遅れないようにしてください。","kana":"おくれない よう に して ください。","meaning":"Usahakan jangan terlambat."}],"level":"N4","enrichment":false,"order":32,"sources":[{"id":"master","page":283},{"id":"master","page":284},{"id":"all","page":31},{"id":"rangkuman","page":40},{"id":"rangkuman","page":47}],"searchTerms":[]},{"id":"n4-youni-naru","concept":"youni-naru","category":"plans","subcategory":"Perubahan kebiasaan atau kemampuan","title":"～ようになる","kana":"ようになる","romaji":"youninaru","meaning":"Menjadi bisa; mulai terbiasa","explanation":"ようになる menyoroti perubahan: sekarang suatu tindakan dapat dilakukan atau menjadi kebiasaan. Dengan bentuk potensial, artinya menjadi bisa. Untuk berhenti melakukan, gunakan ～なくなる.","patterns":["V kamus / V potensial + ようになります","Vない: ない → なくなります"],"note":"Perubahan sifat seperti 高くなる sudah ada di N5. Di sini yang berubah adalah kemampuan atau kebiasaan tindakan.","examples":[{"jp":"日本語の新聞が読めるようになりました。","kana":"にほんご の しんぶん が よめる よう に なりました。","meaning":"Saya sekarang sudah bisa membaca koran bahasa Jepang."},{"jp":"最近、夜は出かけなくなりました。","kana":"さいきん、よる は でかけなく なりました。","meaning":"Akhir-akhir ini saya tidak lagi keluar pada malam hari."}],"level":"N4","enrichment":false,"order":33,"sources":[{"id":"master","page":281},{"id":"master","page":282},{"id":"rangkuman","page":40},{"id":"rangkuman","page":42},{"id":"rangkuman","page":47}],"searchTerms":[]},{"id":"n4-aida","concept":"aida","category":"time","subcategory":"Rentang waktu","title":"～間・～間に","kana":"あいだ・あいだに","romaji":"aida / aidani","meaning":"Selama; pada suatu waktu di dalam rentang itu","explanation":"間 menekankan kegiatan atau keadaan yang berlangsung sepanjang suatu rentang. 間に menempatkan suatu kejadian di dalam rentang tersebut. Penanda に penting ketika yang dibicarakan adalah kesempatan melakukan atau terjadinya sesuatu.","patterns":["Vている / V kamus + 間（に）","Sifat-i + 間（に）","Sifat-na + な間（に）","N + の間（に）"],"note":"Bandingkan: 子どもが寝ている間、勉強した berarti belajar selama anak tidur. 寝ている間に、買い物した berarti berbelanja dalam kesempatan saat anak tidur.","examples":[{"jp":"夏休みの間、毎日泳ぎました。","kana":"なつやすみ の あいだ、まいにち およぎました。","meaning":"Selama liburan musim panas, saya berenang setiap hari."},{"jp":"子どもが寝ている間に、料理を作りました。","kana":"こども が ねて いる あいだ に、りょうり を つくりました。","meaning":"Saya memasak selagi anak sedang tidur."}],"level":"N4","enrichment":false,"order":34,"sources":[{"id":"master","page":8},{"id":"master","page":9},{"id":"master","page":10},{"id":"master","page":11},{"id":"master","page":12},{"id":"master","page":13},{"id":"all","page":13}],"searchTerms":["aida ni","あいだに"]},{"id":"n4-made-ni","concept":"made-ni","category":"time","subcategory":"Batas penyelesaian","title":"～までに","kana":"までに","romaji":"madeni","meaning":"Paling lambat; sebelum batas waktu","explanation":"までに menetapkan tenggat: tindakan harus selesai pada atau sebelum waktu yang disebutkan. Ini berbeda dari まで pada N5 yang menekankan berlangsung terus sampai suatu batas.","patterns":["Waktu + までに + tindakan selesai","V kamus + までに + tindakan"],"note":"五時まで働く berarti bekerja sampai pukul lima. 五時までに出す berarti menyerahkan paling lambat pukul lima.","examples":[{"jp":"金曜日までに、宿題を出してください。","kana":"きんようび まで に、しゅくだい を だして ください。","meaning":"Kumpulkan tugas paling lambat hari Jumat."},{"jp":"先生が来るまでに、準備します。","kana":"せんせい が くる まで に、じゅんび します。","meaning":"Saya akan menyiapkannya sebelum guru datang."}],"level":"N4","enrichment":false,"order":35,"sources":[{"id":"master","page":98},{"id":"master","page":99},{"id":"all","page":8},{"id":"rangkuman","page":11}],"check":{"prompt":"五時までに出してください berarti …","options":["Serahkan paling lambat pukul lima.","Terus menyerahkan sampai pukul lima."],"answer":0,"explanation":"までに menetapkan tenggat penyelesaian."},"searchTerms":[]},{"id":"n4-tokoro","concept":"tokoro","category":"time","subcategory":"Tahap suatu tindakan","title":"～ところだ","kana":"ところだ","romaji":"tokoroda","meaning":"Baru akan; sedang; baru saja selesai","explanation":"ところ menunjukkan tahap tindakan dilihat dari saat yang sedang dibicarakan. Bentuk kamus berarti tepat sebelum mulai, ている berarti sedang dilakukan, dan た berarti tepat setelah selesai.","patterns":["V kamus + ところです","Vている + ところです","Vた + ところです"],"note":"Tokoro di sini bukan tempat secara fisik. ～たばかり lebih menekankan bahwa kejadian terasa masih baru bagi pembicara; tidak harus baru beberapa detik.","examples":[{"jp":"今から昼ご飯を食べるところです。","kana":"いま から ひるごはん を たべる ところ です。","meaning":"Saya baru akan makan siang sekarang."},{"jp":"今、宿題をしているところです。","kana":"いま、しゅくだい を して いる ところ です。","meaning":"Saya sedang mengerjakan tugas sekarang."},{"jp":"たった今、駅に着いたところです。","kana":"たった いま、えき に ついた ところ です。","meaning":"Saya baru saja tiba di stasiun."}],"level":"N4","enrichment":false,"order":36,"sources":[{"id":"master","page":189},{"id":"master","page":190},{"id":"master","page":234},{"id":"master","page":235},{"id":"master","page":256},{"id":"master","page":257},{"id":"all","page":11},{"id":"rangkuman","page":47}],"table":{"headers":["Tahap","Pola","Arti"],"rows":[["Sebelum","食べるところ","Baru akan makan"],["Berlangsung","食べているところ","Sedang makan"],["Sesudah","食べたところ","Baru saja selesai makan"]]},"searchTerms":[]},{"id":"n4-ta-bakari","concept":"ta-bakari","category":"time","subcategory":"Kejadian yang terasa baru","title":"～たばかり","kana":"たばかり","romaji":"tabakari","meaning":"Baru saja melakukan menurut perasaan pembicara","explanation":"たばかり menempatkan kejadian lampau sebagai sesuatu yang masih terasa baru. Jarak waktunya bergantung pada konteks: bisa beberapa menit atau bahkan beberapa bulan untuk pengalaman besar.","patterns":["Vた + ばかりです","Vた + ばかりの + N"],"note":"Jangan menetapkan batas menit tertentu. ～たところ menyatakan tepat sesudah selesai, sedangkan ～たばかり memberi penilaian bahwa waktunya belum lama.","examples":[{"jp":"先月、この会社に入ったばかりです。","kana":"せんげつ、この かいしゃ に はいった ばかり です。","meaning":"Saya baru masuk perusahaan ini bulan lalu."},{"jp":"買ったばかりの靴が汚れました。","kana":"かった ばかり の くつ が よごれました。","meaning":"Sepatu yang baru saya beli sudah kotor."}],"level":"N4","enrichment":false,"order":37,"sources":[{"id":"master","page":187},{"id":"master","page":188},{"id":"rangkuman","page":42}],"searchTerms":[]},{"id":"n4-mama","concept":"mama","category":"time","subcategory":"Keadaan tetap","title":"～まま","kana":"まま","romaji":"mama","meaning":"Tetap dalam keadaan; tanpa mengubah keadaan","explanation":"まま menunjukkan keadaan yang dipertahankan atau dibiarkan saat tindakan berikutnya berlangsung. Vた menyatakan keadaan hasil tindakan, sedangkan Vない menunjukkan tindakan yang belum atau tidak dilakukan.","patterns":["Vた / Vない + まま","N + のまま","Sifat-i + まま","Sifat-na + なまま"],"note":"Bukan sekadar urutan dua kegiatan. 電気をつけたまま寝る berarti lampu tetap menyala ketika tidur.","examples":[{"jp":"電気をつけたまま、寝てしまいました。","kana":"でんき を つけた まま、ねて しまいました。","meaning":"Saya tertidur dengan lampu masih menyala."},{"jp":"靴を履いたまま、入らないでください。","kana":"くつ を はいた まま、はいらないで ください。","meaning":"Jangan masuk sambil tetap memakai sepatu."}],"level":"N4","enrichment":false,"order":38,"sources":[{"id":"master","page":100},{"id":"master","page":101},{"id":"master","page":102},{"id":"all","page":16}],"searchTerms":[]},{"id":"n4-ta-koto-aru","concept":"ta-koto-aru","category":"actions","subcategory":"Pengalaman","title":"～たことがある","kana":"たことがある","romaji":"takotogaaru","meaning":"Pernah mengalami atau melakukan","explanation":"Bentuk た ditambah ことがある menyatakan pengalaman sampai saat ini. Fokusnya pada pernah atau tidak pernah, bukan menceritakan satu kejadian pada waktu yang pasti.","patterns":["Vた + ことがあります","Vた + ことがありません","一度も + Vた + ことがありません"],"note":"Untuk kejadian pasti seperti kemarin pergi ke bank, cukup gunakan bentuk lampau biasa. 一度も bersama bentuk negatif berarti belum pernah sekalipun.","examples":[{"jp":"日本で働いたことがあります。","kana":"にほん で はたらいた こと が あります。","meaning":"Saya pernah bekerja di Jepang."},{"jp":"一度も飛行機に乗ったことがありません。","kana":"いちど も ひこうき に のった こと が ありません。","meaning":"Saya belum pernah naik pesawat sekalipun."}],"level":"N4","enrichment":false,"order":39,"sources":[{"id":"all","page":17},{"id":"rangkuman","page":42}],"searchTerms":[]},{"id":"n4-koto-ga-aru","concept":"koto-ga-aru","category":"actions","subcategory":"Kejadian sesekali","title":"～ことがある","kana":"ことがある","romaji":"kotogaaru","meaning":"Ada kalanya; kadang terjadi","explanation":"Kata kerja bentuk kamus atau ない ditambah ことがある menyatakan kejadian yang kadang berlangsung. Ini berbeda dari Vたことがある yang menyatakan pengalaman lampau.","patterns":["V kamus / Vない + ことがあります"],"note":"Bentuk sebelum こと membedakan fungsi. 遅れることがある berarti kadang terlambat; 遅れたことがある berarti pernah terlambat.","examples":[{"jp":"忙しくて、昼ご飯を食べないことがあります。","kana":"いそがしくて、ひるごはん を たべない こと が あります。","meaning":"Kadang saya tidak makan siang karena sibuk."},{"jp":"この電車は遅れることがあります。","kana":"この でんしゃ は おくれる こと が あります。","meaning":"Kereta ini kadang terlambat."}],"level":"N4","enrichment":false,"order":40,"sources":[{"id":"master","page":85},{"id":"master","page":86}],"searchTerms":[]},{"id":"n4-te-oku","concept":"te-oku","category":"actions","subcategory":"Persiapan","title":"～ておく","kana":"ておく","romaji":"teoku","meaning":"Melakukan terlebih dahulu; membiarkan tetap begitu","explanation":"ておく dipakai untuk menyiapkan sesuatu bagi keperluan nanti. Pola ini juga dapat meminta agar keadaan dibiarkan untuk sementara karena masih dibutuhkan.","patterns":["Vて + おきます","Vて + おいてください"],"note":"Dalam percakapan ておく dapat menjadi とく, misalnya 書いとく. Permintaan そのままにしておいてください berarti biarkan tetap seperti itu.","examples":[{"jp":"旅行の前に、ホテルを予約しておきます。","kana":"りょこう の まえ に、ホテル を よやく して おきます。","meaning":"Saya akan memesan hotel terlebih dahulu sebelum bepergian."},{"jp":"まだ使うので、机の上に置いておいてください。","kana":"まだ つかう ので、つくえ の うえ に おいて おいて ください。","meaning":"Karena masih akan dipakai, biarkan di atas meja dulu."}],"level":"N4","enrichment":false,"order":41,"sources":[{"id":"master","page":224},{"id":"master","page":225},{"id":"all","page":23},{"id":"rangkuman","page":42}],"searchTerms":[]},{"id":"n4-te-shimau","concept":"te-shimau","category":"actions","subcategory":"Penyelesaian dan penyesalan","title":"～てしまう・～ちゃう","kana":"てしまう・ちゃう","romaji":"teshimau / chau","meaning":"Menyelesaikan; terlanjur atau tidak sengaja","explanation":"てしまう dapat menunjukkan tindakan selesai seluruhnya. Dalam konteks lain, pola ini menunjukkan penyesalan, kejadian yang tidak diinginkan, atau sesuatu yang terlanjur terjadi. Maknanya ditentukan konteks, bukan hanya bentuk lampau.","patterns":["Vて + しまいます","Vて + しまいました","～てしまう → ～ちゃう","～でしまう → ～じゃう"],"note":"読み終えてしまった tidak harus berarti tidak sengaja membaca. Sebaliknya 忘れてしまった lazim menyiratkan penyesalan.","examples":[{"jp":"宿題は全部やってしまいました。","kana":"しゅくだい は ぜんぶ やって しまいました。","meaning":"Saya sudah menyelesaikan semua tugas."},{"jp":"財布を忘れてしまいました。","kana":"さいふ を わすれて しまいました。","meaning":"Saya terlanjur lupa membawa dompet."}],"level":"N4","enrichment":false,"order":42,"sources":[{"id":"master","page":226},{"id":"master","page":227},{"id":"all","page":24},{"id":"rangkuman","page":41}],"searchTerms":[]},{"id":"n4-te-miru","concept":"te-miru","category":"actions","subcategory":"Mencoba","title":"～てみる","kana":"てみる","romaji":"temiru","meaning":"Mencoba melakukan untuk mengetahui hasilnya","explanation":"てみる berarti melakukan suatu tindakan sebagai percobaan, lalu melihat hasil atau merasakan pengalamannya. Kata kerja みる dalam pola ini biasanya ditulis dengan hiragana.","patterns":["Vて + みます","Vて + みたいです","Vて + みてください"],"note":"Bedakan dari 見る yang benar-benar berarti melihat. 食べてみる berarti mencoba mencicipi, bukan makan lalu melihat sesuatu.","examples":[{"jp":"この靴を履いてみてもいいですか。","kana":"この くつ を はいて みて も いい です か。","meaning":"Bolehkah saya mencoba memakai sepatu ini?"},{"jp":"自分で作ってみました。","kana":"じぶん で つくって みました。","meaning":"Saya sudah mencoba membuatnya sendiri."}],"level":"N4","enrichment":false,"order":43,"sources":[{"id":"master","page":220},{"id":"master","page":221},{"id":"all","page":25},{"id":"rangkuman","page":42}],"searchTerms":[]},{"id":"n4-te-iku-kuru","concept":"te-iku-kuru","category":"actions","subcategory":"Arah dan perubahan","title":"～ていく・～てくる","kana":"ていく・てくる","romaji":"teiku / tekuru","meaning":"Melakukan lalu pergi atau kembali; perubahan mendekat atau berlanjut","explanation":"てくる dapat menunjukkan pergi melakukan sesuatu lalu kembali ke titik pembicaraan. ていく menunjukkan tindakan disertai gerak menjauh. Dalam perubahan waktu, てくる menyoroti perubahan sampai sekarang, sedangkan ていく menyoroti kelanjutan mulai sekarang.","patterns":["Vて + きます","Vて + いきます"],"note":"Sesuaikan makna dengan konteks. 寒くなってきた berarti mulai terasa dingin sampai sekarang; 寒くなっていく berarti ke depan akan makin dingin.","examples":[{"jp":"ちょっと飲み物を買ってきます。","kana":"ちょっと のみもの を かって きます。","meaning":"Saya pergi membeli minuman sebentar, lalu kembali."},{"jp":"これからも日本語を勉強していきます。","kana":"これから も にほんご を べんきょう して いきます。","meaning":"Mulai sekarang pun saya akan terus belajar bahasa Jepang."}],"level":"N4","enrichment":false,"order":44,"sources":[{"id":"master","page":209},{"id":"master","page":210},{"id":"master","page":218},{"id":"master","page":219},{"id":"all","page":76},{"id":"rangkuman","page":42}],"searchTerms":["te iku","te kuru"]},{"id":"n4-toori","concept":"toori","category":"actions","subcategory":"Mengikuti acuan","title":"～とおりに","kana":"とおりに","romaji":"toorini","meaning":"Sesuai; persis seperti acuan","explanation":"とおりに menyatakan bahwa tindakan dilakukan mengikuti petunjuk, contoh, atau kejadian yang dijadikan acuan. Bentuk yang dipakai bergantung pada apakah acuannya kata benda atau kata kerja.","patterns":["V kamus / Vた + とおりに","N + のとおりに"],"note":"先生が言ったとおりに berarti mengikuti apa yang sudah guru katakan. Jangan otomatis menambahkan の setelah kata kerja.","examples":[{"jp":"説明書のとおりに、組み立ててください。","kana":"せつめいしょ の とおり に、くみたてて ください。","meaning":"Rakitlah sesuai buku petunjuk."},{"jp":"私が書いたとおりに、書いてください。","kana":"わたし が かいた とおり に、かいて ください。","meaning":"Tulislah persis seperti yang saya tulis."}],"level":"N4","enrichment":false,"order":45,"sources":[{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-nagara","concept":"nagara","category":"actions","subcategory":"Dua tindakan bersamaan","title":"～ながら","kana":"ながら","romaji":"nagara","meaning":"Sambil melakukan tindakan lain","explanation":"ながら menghubungkan dua tindakan yang dilakukan bersamaan oleh pelaku yang sama. Tindakan utama berada di akhir kalimat. Tindakan sebelum ながら menjadi kegiatan pendamping.","patterns":["Vます: buang ます + ながら、tindakan utama"],"note":"Berbeda dari ～たり yang menyebut contoh kegiatan dan bentuk て yang dapat menunjukkan urutan. Jangan memakai ながら untuk dua pelaku yang berbeda.","examples":[{"jp":"音楽を聞きながら、料理を作ります。","kana":"おんがく を ききながら、りょうり を つくります。","meaning":"Saya memasak sambil mendengarkan musik."},{"jp":"歩きながら、電話をしないでください。","kana":"あるきながら、でんわ を しないで ください。","meaning":"Jangan menelepon sambil berjalan."}],"level":"N4","enrichment":false,"order":46,"sources":[{"id":"master","page":117},{"id":"master","page":118},{"id":"rangkuman","page":40}],"check":{"prompt":"Dalam 音楽を聞きながら料理を作ります, tindakan utama adalah …","options":["Mendengarkan musik.","Memasak."],"answer":1,"explanation":"Tindakan utama ditempatkan setelah bagian ながら."},"searchTerms":[]},{"id":"n4-te-ageru","concept":"te-ageru","category":"giving","subcategory":"Melakukan bantuan","title":"～てあげる","kana":"てあげる","romaji":"teageru","meaning":"Melakukan sesuatu untuk orang lain","explanation":"てあげる memandang tindakan sebagai bantuan yang diberikan kepada orang lain. Pelaku melakukan V, lalu orang yang menerima manfaat dapat ditandai に.","patterns":["Pelaku は + penerima に + Vてあげます"],"note":"Tidak sama dengan memberikan benda memakai あげる pada N5. Kepada atasan, mengatakan ～てあげます secara langsung dapat terdengar menggurui. ～てやる lebih kasar dan terbatas konteks, misalnya terhadap hewan atau tanaman.","examples":[{"jp":"弟に漢字を教えてあげました。","kana":"おとうと に かんじ を おしえて あげました。","meaning":"Saya membantu adik dengan mengajarinya kanji."},{"jp":"友達の荷物を持ってあげました。","kana":"ともだち の にもつ を もって あげました。","meaning":"Saya membantu membawakan barang teman."}],"level":"N4","enrichment":false,"order":47,"sources":[{"id":"master","page":205},{"id":"master","page":206},{"id":"master","page":230},{"id":"master","page":231},{"id":"all","page":27},{"id":"rangkuman","page":41}],"searchTerms":["te yaru","てやる"]},{"id":"n4-te-kureru","concept":"te-kureru","category":"giving","subcategory":"Menerima bantuan","title":"～てくれる","kana":"てくれる","romaji":"tekureru","meaning":"Seseorang melakukan sesuatu untuk saya atau pihak saya","explanation":"てくれる menempatkan orang lain sebagai pelaku bantuan. Pembicara memandang manfaatnya datang kepada diri sendiri atau orang yang dianggap bagian dari pihaknya.","patterns":["Pelaku が / は + （penerima に） + Vてくれます"],"note":"Pelaku tetap orang yang melakukan bantuan. Ini pola tindakan, berbeda dari くれる untuk memberikan benda pada N5.","examples":[{"jp":"友達が駅まで迎えに来てくれました。","kana":"ともだち が えき まで むかえ に きて くれました。","meaning":"Teman datang menjemput saya ke stasiun."},{"jp":"先生が作文を直してくれました。","kana":"せんせい が さくぶん を なおして くれました。","meaning":"Guru membantu memperbaiki karangan saya."}],"level":"N4","enrichment":false,"order":48,"sources":[{"id":"master","page":215},{"id":"master","page":216},{"id":"master","page":217},{"id":"all","page":27},{"id":"rangkuman","page":41}],"searchTerms":[]},{"id":"n4-te-morau","concept":"te-morau","category":"giving","subcategory":"Memperoleh bantuan","title":"～てもらう","kana":"てもらう","romaji":"temorau","meaning":"Mendapat bantuan seseorang melakukan sesuatu","explanation":"てもらう menjadikan penerima bantuan sebagai topik atau subjek. Orang yang melakukan tindakan ditandai に. Pembicara menyoroti bantuan yang diperoleh, sering disertai rasa terbantu.","patterns":["Penerima は + pelaku に + Vてもらいます"],"note":"私は先生に教えてもらった: guru yang mengajar, saya penerimanya. Hindari menghafal hanya sebagai awalan di- karena susunan pelakunya harus tetap dipahami.","examples":[{"jp":"先生に発音を教えてもらいました。","kana":"せんせい に はつおん を おしえて もらいました。","meaning":"Saya mendapat bantuan guru untuk belajar pelafalan."},{"jp":"友達に写真を撮ってもらいました。","kana":"ともだち に しゃしん を とって もらいました。","meaning":"Saya meminta bantuan teman untuk memotret saya."}],"level":"N4","enrichment":false,"order":49,"sources":[{"id":"master","page":222},{"id":"master","page":223},{"id":"all","page":28},{"id":"rangkuman","page":41}],"searchTerms":[]},{"id":"n4-te-hoshii","concept":"te-hoshii","category":"giving","subcategory":"Harapan kepada orang lain","title":"～てほしい","kana":"てほしい","romaji":"tehoshii","meaning":"Ingin orang lain melakukan sesuatu","explanation":"てほしい menyatakan tindakan yang diharapkan dari orang lain. Orang yang diharapkan bertindak ditandai に. Bentuk ないでほしい menyatakan harapan agar tindakan tidak dilakukan.","patterns":["Pelaku yang diharapkan に + Vてほしい","Pelaku yang diharapkan に + Vないでほしい"],"note":"Bedakan Nがほしい pada N5 untuk benda. Ini dapat terdengar langsung; untuk permintaan sopan gunakan ～ていただけませんか.","examples":[{"jp":"もう一度説明してほしいです。","kana":"もう いちど せつめい して ほしい です。","meaning":"Saya ingin kamu menjelaskannya sekali lagi."},{"jp":"ここでは大きな声で話さないでほしいです。","kana":"ここ では おおきな こえ で はなさないで ほしい です。","meaning":"Saya ingin kamu tidak berbicara keras di sini."}],"level":"N4","enrichment":false,"order":50,"sources":[{"id":"master","page":207},{"id":"master","page":208},{"id":"all","page":52}],"searchTerms":[]},{"id":"n4-houga-ii","concept":"houga-ii","category":"giving","subcategory":"Saran langsung","title":"～たほうがいい・～ないほうがいい","kana":"たほうがいい・ないほうがいい","romaji":"tahougaii / naihougaii","meaning":"Sebaiknya melakukan; sebaiknya tidak","explanation":"Vたほうがいい memberi saran untuk melakukan sesuatu. Vないほうがいい menyarankan agar tidak melakukannya. Pola ini menilai pilihan yang lebih baik dalam situasi tertentu.","patterns":["Vた + ほうがいいです","Vない + ほうがいいです"],"note":"Bentuk た pada saran ini bukan berarti tindakannya sudah terjadi. Berbeda dari Nのほうが untuk perbandingan benda pada N5. Kepada atasan, saran ini dapat terasa terlalu langsung.","examples":[{"jp":"今日は早く寝たほうがいいです。","kana":"きょう は はやく ねた ほう が いい です。","meaning":"Hari ini sebaiknya tidur lebih awal."},{"jp":"夜はコーヒーを飲まないほうがいいです。","kana":"よる は コーヒー を のまない ほう が いい です。","meaning":"Malam hari sebaiknya tidak minum kopi."}],"level":"N4","enrichment":false,"order":51,"sources":[{"id":"all","page":35},{"id":"rangkuman","page":47}],"searchTerms":[]},{"id":"n4-tara-dou","concept":"tara-dou","category":"giving","subcategory":"Saran sebagai pilihan","title":"～たらどうですか","kana":"たらどうですか","romaji":"taradoudesuka","meaning":"Bagaimana kalau mencoba …?","explanation":"たらどうですか mengajukan tindakan sebagai pilihan yang dapat dicoba lawan bicara. Bentuk ～たらいかがですか lebih sopan. Gunakan setelah memahami masalah atau kebutuhan lawan bicara.","patterns":["Vた + らどうですか","Vた + らいかがですか"],"note":"Bukan pertanyaan tentang cara melakukan. Jika intonasinya mendesak, bentuk singkat ～たら？ dapat terdengar seperti kritik.","examples":[{"jp":"先生に聞いてみたらどうですか。","kana":"せんせい に きいて みたら どう です か。","meaning":"Bagaimana kalau mencoba bertanya kepada guru?"},{"jp":"少し休んだらいかがですか。","kana":"すこし やすんだら いかが です か。","meaning":"Bagaimana kalau beristirahat sebentar?"}],"level":"N4","enrichment":false,"order":52,"sources":[{"id":"master","page":199},{"id":"master","page":200},{"id":"all","page":53}],"searchTerms":[]},{"id":"n4-tara-ii-question","concept":"tara-ii-question","category":"giving","subcategory":"Meminta petunjuk","title":"～たらいいですか","kana":"たらいいですか","romaji":"taraiidesuka","meaning":"Sebaiknya melakukan apa; harus bagaimana?","explanation":"Pola ini meminta saran tentang tindakan, waktu, tempat, atau cara yang tepat. Gabungkan kata tanya dengan Vたらいいですか.","patterns":["Kata tanya + Vた + らいいですか"],"note":"どうしたらいいですか menanyakan apa yang sebaiknya dilakukan. Ini bukan menyatakan kewajiban pasti, melainkan meminta arahan.","examples":[{"jp":"どこで切符を買ったらいいですか。","kana":"どこ で きっぷ を かったら いい です か。","meaning":"Sebaiknya saya membeli tiket di mana?"},{"jp":"何時に来たらいいですか。","kana":"なんじ に きたら いい です か。","meaning":"Sebaiknya saya datang pukul berapa?"}],"level":"N4","enrichment":false,"order":53,"sources":[{"id":"master","page":201},{"id":"master","page":202}],"searchTerms":[]},{"id":"n4-te-sumimasen","concept":"te-sumimasen","category":"giving","subcategory":"Meminta maaf atas keadaan","title":"～てすみません","kana":"てすみません","romaji":"tesumimasen","meaning":"Maaf karena melakukan atau tidak melakukan","explanation":"Bentuk て menghubungkan tindakan atau keadaan yang menjadi alasan permintaan maaf dengan すみません. Untuk hal yang tidak dilakukan, gunakan ～なくてすみません. Dapat dipakai untuk keadaan saat ini atau permintaan maaf atas hal yang sudah terjadi.","patterns":["Vて + すみません","Vない: ない → なくてすみません","Vて + すみませんでした"],"note":"Bukan meminta orang melakukan sesuatu. 遅れてすみません berarti maaf terlambat; 遅れないでください berarti tolong jangan terlambat.","examples":[{"jp":"遅れてすみません。","kana":"おくれて すみません。","meaning":"Maaf saya terlambat."},{"jp":"手伝えなくてすみませんでした。","kana":"てつだえなくて すみません でした。","meaning":"Maaf saya tidak bisa membantu."}],"level":"N4","enrichment":false,"order":54,"sources":[{"id":"master","page":228},{"id":"master","page":229}],"searchTerms":[]},{"id":"n4-te-yokatta","concept":"te-yokatta","category":"giving","subcategory":"Rasa lega","title":"～てよかった","kana":"てよかった","romaji":"teyokatta","meaning":"Syukurlah; senang karena sesuatu terjadi","explanation":"てよかった menyampaikan rasa lega atau penilaian positif terhadap kejadian. Untuk tindakan yang tidak dilakukan, gunakan ～なくてよかった. Pembicara melihat hasilnya sebagai sesuatu yang baik.","patterns":["Vて + よかったです","Vない: ない → なくてよかったです"],"note":"Bedakan dari ～たほうがいい yang menyarankan tindakan. ～てよかった menilai hasil atau keadaan yang sudah diketahui.","examples":[{"jp":"試験に合格できてよかったです。","kana":"しけん に ごうかく できて よかった です。","meaning":"Syukurlah saya bisa lulus ujian."},{"jp":"大きなけがをしなくてよかったです。","kana":"おおきな けが を しなくて よかった です。","meaning":"Syukurlah tidak mengalami luka berat."}],"level":"N4","enrichment":false,"order":55,"sources":[{"id":"master","page":232},{"id":"master","page":233}],"searchTerms":[]},{"id":"n4-bakari","concept":"bakari","category":"particles","subcategory":"Hal yang mendominasi","title":"～ばかり","kana":"ばかり","romaji":"bakari","meaning":"Hanya itu-itu saja; terus melakukan hal yang sama","explanation":"ばかり menekankan bahwa sesuatu mendominasi pilihan atau tindakan. Sering menyiratkan bahwa pembicara merasa isinya tidak seimbang atau tindakannya terlalu sering.","patterns":["N + ばかり","Vて + ばかりいます"],"note":"だけ pada N5 membatasi secara netral. ばかり sering menambahkan penilaian hanya itu terus. Ini berbeda dari Vたばかり yang berarti baru saja.","examples":[{"jp":"弟はゲームばかりしています。","kana":"おとうと は ゲーム ばかり して います。","meaning":"Adik terus bermain gim saja."},{"jp":"甘い物ばかり食べないでください。","kana":"あまい もの ばかり たべないで ください。","meaning":"Jangan makan makanan manis saja."}],"level":"N4","enrichment":false,"order":56,"sources":[{"id":"master","page":25},{"id":"master","page":26},{"id":"all","page":10}],"searchTerms":[]},{"id":"n4-shika","concept":"shika","category":"particles","subcategory":"Batas yang dianggap sedikit","title":"～しか～ない","kana":"しかない","romaji":"shikanai","meaning":"Hanya; tidak ada selain itu","explanation":"しか membatasi hal atau jumlah lalu diikuti bentuk negatif. Pembicara sering menyoroti bahwa pilihannya sedikit atau tidak cukup. Makna keseluruhan tetap hanya, bukan tidak punya sama sekali.","patterns":["N / jumlah + しか + bentuk negatif","V kamus + しかない"],"note":"だけ boleh diikuti positif; しか memerlukan negatif. 百円しかない berarti hanya punya seratus yen.","examples":[{"jp":"財布には百円しかありません。","kana":"さいふ に は ひゃくえん しか ありません。","meaning":"Di dompet hanya ada seratus yen."},{"jp":"今日は一時間しか勉強できません。","kana":"きょう は いちじかん しか べんきょう できません。","meaning":"Hari ini saya hanya bisa belajar satu jam."}],"level":"N4","enrichment":false,"order":57,"sources":[{"id":"all","page":7},{"id":"rangkuman","page":12}],"check":{"prompt":"Pilih kalimat dengan しか yang benar.","options":["百円しかあります。","百円しかありません。"],"answer":1,"explanation":"しか membutuhkan bentuk negatif."},"searchTerms":[]},{"id":"n4-hodo-negative","concept":"hodo-negative","category":"particles","subcategory":"Perbandingan negatif","title":"～ほど～ない","kana":"ほどない","romaji":"hodonai","meaning":"Tidak se-; tidak sampai tingkat pembanding","explanation":"AはBほど～ない menyatakan A tidak mempunyai sifat itu sampai tingkat B. Akhir kalimat memakai bentuk negatif dari sifat atau penilaian yang dibandingkan.","patterns":["A は + B + ほど + sifat negatif"],"note":"Ini struktur perbandingan negatif. AよりBのほうが～ pada N5 menyatakan perbandingan dari sisi yang lebih tinggi, sedangkan ほど～ない dari sisi yang lebih rendah.","examples":[{"jp":"今日は昨日ほど寒くありません。","kana":"きょう は きのう ほど さむく ありません。","meaning":"Hari ini tidak sedingin kemarin."},{"jp":"バスは電車ほど速くありません。","kana":"バス は でんしゃ ほど はやく ありません。","meaning":"Bus tidak secepat kereta."}],"level":"N4","enrichment":false,"order":58,"sources":[{"id":"all","page":3}],"searchTerms":[]},{"id":"n4-zutsu","concept":"zutsu","category":"particles","subcategory":"Pembagian merata","title":"～ずつ","kana":"ずつ","romaji":"zutsu","meaning":"Masing-masing; sedikit demi sedikit dalam jumlah tertentu","explanation":"ずつ mengikuti jumlah atau satuan untuk menyatakan pembagian yang sama kepada tiap pihak, atau pertambahan langkah demi langkah dengan jumlah yang tetap.","patterns":["Jumlah / satuan + ずつ"],"note":"一人に二枚ずつ berarti setiap orang mendapat dua lembar. 少しずつ berarti sedikit demi sedikit, bukan semuanya sekaligus.","examples":[{"jp":"一人に二枚ずつ配ってください。","kana":"ひとり に にまい ずつ くばって ください。","meaning":"Bagikan dua lembar kepada setiap orang."},{"jp":"毎日、少しずつ覚えます。","kana":"まいにち、すこし ずつ おぼえます。","meaning":"Saya menghafal sedikit demi sedikit setiap hari."}],"level":"N4","enrichment":false,"order":59,"sources":[{"id":"all","page":2}],"searchTerms":[]},{"id":"n4-oki-ni","concept":"oki-ni","category":"particles","subcategory":"Sela yang berulang","title":"～おきに","kana":"おきに","romaji":"okini","meaning":"Dengan sela tertentu secara berulang","explanation":"おきに mengikuti ukuran sela. 一時間おきに berarti pada interval satu jam. Ketika memakai satuan hari, 一日おきに lazim berarti satu hari dilewati lalu kegiatan dilakukan lagi: selang sehari.","patterns":["Ukuran waktu / jarak + おきに"],"note":"毎日 berarti setiap hari, sedangkan 一日おきに berarti selang sehari. Untuk jadwal penting, tanggal atau jam yang konkret membantu menghindari salah paham.","examples":[{"jp":"この薬は六時間おきに飲みます。","kana":"この くすり は ろくじかん おき に のみます。","meaning":"Obat ini diminum dengan interval enam jam."},{"jp":"一日おきに、花に水をやります。","kana":"いちにち おき に、はな に みず を やります。","meaning":"Saya menyiram bunga selang sehari."}],"level":"N4","enrichment":false,"order":60,"sources":[{"id":"master","page":151},{"id":"master","page":152}],"searchTerms":[]},{"id":"n4-mo-quantity","concept":"mo-quantity","category":"particles","subcategory":"Jumlah yang mengejutkan","title":"Jumlah＋も","kana":"も","romaji":"mo","meaning":"Sebanyak itu; penekanan jumlah yang besar","explanation":"も sesudah jumlah menunjukkan bahwa pembicara memandang jumlah itu besar atau mengejutkan. Ini fungsi penekanan jumlah, berbeda dari も yang sekadar berarti juga pada N5.","patterns":["Jumlah / durasi + も"],"note":"Satu jumlah yang sama dapat terasa besar atau kecil bergantung konteks. Untuk menekankan sedikitnya jumlah, しか～ない sering dipakai.","examples":[{"jp":"駅まで一時間もかかりました。","kana":"えき まで いちじかん も かかりました。","meaning":"Ke stasiun saja memakan waktu sampai satu jam."},{"jp":"友達が十人も来ました。","kana":"ともだち が じゅうにん も きました。","meaning":"Teman yang datang sampai sepuluh orang."}],"level":"N4","enrichment":false,"order":61,"sources":[{"id":"master","page":111},{"id":"master","page":112}],"searchTerms":[]},{"id":"n4-dake-de","concept":"dake-de","category":"particles","subcategory":"Syarat yang sudah cukup","title":"～だけで","kana":"だけで","romaji":"dakede","meaning":"Cukup dengan; hanya dengan melakukan","explanation":"だけで menyatakan bahwa satu hal saja sudah cukup untuk menimbulkan hasil. Bentuk ini dapat mengikuti kata benda atau kata kerja bentuk biasa.","patterns":["N + だけで","V kamus + だけで"],"note":"Fokusnya bukan hanya pembatasan seperti だけ pada N5, tetapi hubungan cukup A saja, B terjadi.","examples":[{"jp":"このボタンを押すだけで、ドアが開きます。","kana":"この ボタン を おす だけ で、ドア が あきます。","meaning":"Cukup menekan tombol ini, pintunya terbuka."},{"jp":"写真を見るだけで、うれしくなります。","kana":"しゃしん を みる だけ で、うれしく なります。","meaning":"Hanya dengan melihat fotonya, saya merasa senang."}],"level":"N4","enrichment":false,"order":62,"sources":[{"id":"master","page":27},{"id":"master","page":28}],"searchTerms":[]},{"id":"n4-material-kara","concept":"material-kara","category":"particles","subcategory":"Bahan asal","title":"～から作る・～で作る","kana":"からつくる・でつくる","romaji":"karatsukuru / detsukuru","meaning":"Dibuat dari bahan tertentu","explanation":"から menyoroti bahan asal yang telah mengalami pengolahan atau perubahan sehingga bentuk asalnya tidak begitu tampak. で menyebut bahan yang digunakan. Keduanya dapat bergantung pada cara pembicara memandang proses dan hasil.","patterns":["Bahan + から作ります / 作られます","Bahan + で作ります / 作られます"],"note":"Pembeda terlihat atau tidak terlihat adalah panduan awal, bukan hukum tanpa pengecualian. で sebagai alat dan bahan dasar sudah dikenal di N5; から di sini menambah sudut pandang bahan asal.","examples":[{"jp":"ワインはぶどうから作られます。","kana":"ワイン は ぶどう から つくられます。","meaning":"Minuman anggur (wine) dibuat dari buah anggur."},{"jp":"この机は木で作られています。","kana":"この つくえ は き で つくられて います。","meaning":"Meja ini dibuat dari kayu."}],"level":"N4","enrichment":false,"order":63,"sources":[{"id":"master","page":77},{"id":"master","page":78},{"id":"all","page":2}],"searchTerms":[]},{"id":"n4-demo-example","concept":"demo-example","category":"particles","subcategory":"Menawarkan contoh","title":"Nでも","kana":"でも","romaji":"demo","meaning":"Misalnya; … atau yang sejenis","explanation":"Nでも menawarkan satu contoh yang mewakili pilihan lain. Sering dipakai untuk ajakan santai, sehingga tawaran tidak terdengar terlalu membatasi pilihan lawan bicara.","patterns":["N + でも + ajakan / usulan"],"note":"お茶でも berarti teh atau minuman sejenis sebagai contoh, bukan tetapi teh. Berbeda pula dari 誰でも yang sudah dipelajari di N5.","examples":[{"jp":"お茶でも飲みませんか。","kana":"おちゃ でも のみません か。","meaning":"Bagaimana kalau minum teh atau yang lain?"},{"jp":"休みの日は映画でも見ましょう。","kana":"やすみ の ひ は えいが でも みましょう。","meaning":"Saat libur, ayo menonton film atau melakukan hal semacam itu."}],"level":"N4","enrichment":false,"order":64,"sources":[{"id":"master","page":33},{"id":"master","page":34},{"id":"all","page":5},{"id":"rangkuman","page":11}],"searchTerms":[]},{"id":"n4-demo-even","concept":"demo-even","category":"particles","subcategory":"Contoh yang tidak terduga","title":"Nでも（強調）","kana":"でも","romaji":"demo","meaning":"Bahkan; … pun","explanation":"でも menyoroti contoh yang biasanya dianggap tidak mungkin atau tidak diharapkan. Jika contoh ekstrem itu saja memenuhi pernyataan, pembicara menyiratkan hal lain tentu juga dapat.","patterns":["N + でも + pernyataan"],"note":"子どもでもできる berarti bahkan anak-anak pun bisa. Ini fungsi penekanan, berbeda dari tawaran お茶でも dan syarat ても／でも.","examples":[{"jp":"この問題は子どもでもわかります。","kana":"この もんだい は こども でも わかります。","meaning":"Soal ini bahkan dapat dipahami anak-anak."},{"jp":"忙しい日でも、朝ご飯は食べます。","kana":"いそがしい ひ でも、あさごはん は たべます。","meaning":"Bahkan pada hari sibuk pun saya sarapan."}],"level":"N4","enrichment":false,"order":65,"sources":[{"id":"all","page":5}],"searchTerms":[]},{"id":"n4-question-temo","concept":"question-temo","category":"particles","subcategory":"Keadaan mana pun","title":"疑問詞＋～ても","kana":"ぎもんしとても","romaji":"gimonshitotemo","meaning":"Kapan pun; di mana pun; berapa kali pun melakukan","explanation":"Kata tanya diikuti klausa ～ても menyatakan bahwa waktu, tempat, pelaku, atau jumlah yang dipilih tidak mengubah hasil. Tindakan dan hasilnya disebutkan secara lengkap.","patterns":["いつ / どこへ / 誰が + Vても","何度 + Vても","どんなに + sifat bentuk ても"],"note":"いつでも pada N5 adalah bentuk kata tanya＋でも. Di sini ada tindakan di antaranya: いつ行っても, yaitu setiap kali pergi pada waktu apa pun.","examples":[{"jp":"この店はいつ行っても、込んでいます。","kana":"この みせ は いつ いって も、こんで います。","meaning":"Toko ini selalu ramai kapan pun saya pergi."},{"jp":"何度読んでも、わかりません。","kana":"なんど よんで も、わかりません。","meaning":"Berapa kali pun dibaca, saya tetap tidak mengerti."}],"level":"N4","enrichment":false,"order":66,"sources":[{"id":"all","page":47}],"searchTerms":[]},{"id":"n4-ndesu","concept":"ndesu","category":"connectors","subcategory":"Latar belakang dan alasan","title":"～んです・～のです","kana":"んです・のです","romaji":"ndesu / nodesu","meaning":"Memberi penjelasan; meminta latar belakang","explanation":"んです menambahkan latar belakang atau penjelasan yang berkaitan dengan keadaan yang sedang dibicarakan. Dalam pertanyaan, ～んですか meminta alasan atau klarifikasi, bukan sekadar menanyakan fakta baru.","patterns":["V / sifat-i bentuk biasa + んです","Sifat-na / N + なんです","Bentuk tulisan: ～のです"],"note":"Jangan menambahkannya pada setiap kalimat. どうしたんですか lazim dipakai ketika terlihat ada sesuatu yang terjadi. Nada pertanyaan yang terlalu kuat dapat terdengar menuntut alasan.","examples":[{"jp":"頭が痛いんです。","kana":"あたま が いたい ん です。","meaning":"Soalnya kepala saya sakit."},{"jp":"どうして日本語を勉強しているんですか。","kana":"どうして にほんご を べんきょう して いる ん です か。","meaning":"Apa yang membuat kamu belajar bahasa Jepang?"}],"level":"N4","enrichment":false,"order":67,"sources":[{"id":"all","page":77},{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-node","concept":"node","category":"connectors","subcategory":"Alasan sebagai latar","title":"～ので","kana":"ので","romaji":"node","meaning":"Karena; memberikan latar penyebab","explanation":"ので menghubungkan alasan dengan hasil, permintaan, atau penjelasan berikutnya. Alasan dipresentasikan sebagai latar yang perlu diketahui lawan bicara. Sifat-na dan kata benda memakai な sebelum ので.","patterns":["V / sifat-i bentuk biasa + ので","Sifat-na / N + なので"],"note":"ので sering terasa lebih lunak dalam permintaan daripada から, tetapi bukan berarti から selalu tidak sopan. Pemilihan bergantung konteks dan cara berbicara.","examples":[{"jp":"雨が降っているので、傘を持っていきます。","kana":"あめ が ふって いる ので、かさ を もって いきます。","meaning":"Karena sedang hujan, saya akan membawa payung."},{"jp":"明日は試験なので、今日は勉強します。","kana":"あした は しけん な ので、きょう は べんきょう します。","meaning":"Karena besok ujian, hari ini saya akan belajar."}],"level":"N4","enrichment":false,"order":68,"sources":[{"id":"all","page":44},{"id":"rangkuman","page":48}],"searchTerms":[]},{"id":"n4-noni-contrast","concept":"noni-contrast","category":"connectors","subcategory":"Hasil berlawanan harapan","title":"～のに（逆接）","kana":"のに","romaji":"noni","meaning":"Padahal; meskipun ternyata","explanation":"のに menghubungkan kenyataan dengan hasil yang berbeda dari harapan. Sering disertai rasa heran, kecewa, atau tidak puas. Bagian setelahnya biasanya menyatakan hasil atau keadaan, bukan ajakan atau perintah.","patterns":["V / sifat-i bentuk biasa + のに","Sifat-na / N + なのに"],"note":"Pola ini berbeda dari V kamus＋のに untuk fungsi atau kebutuhan. 雨なのに出かけた berarti padahal hujan, tetap keluar.","examples":[{"jp":"たくさん勉強したのに、試験に落ちました。","kana":"たくさん べんきょう した のに、しけん に おちました。","meaning":"Padahal sudah banyak belajar, saya tidak lulus ujian."},{"jp":"日曜日なのに、仕事があります。","kana":"にちようび な のに、しごと が あります。","meaning":"Padahal hari Minggu, saya harus bekerja."}],"level":"N4","enrichment":false,"order":69,"sources":[{"id":"master","page":141},{"id":"master","page":142},{"id":"all","page":45},{"id":"rangkuman","page":49}],"check":{"prompt":"Pilih “padahal hari libur”.","options":["休みなのに","休みだのに"],"answer":0,"explanation":"Kata benda diikuti なのに, bukan だのに."},"searchTerms":[]},{"id":"n4-temo","concept":"temo","category":"connectors","subcategory":"Syarat yang tidak mengubah hasil","title":"～ても・～でも","kana":"ても・でも","romaji":"temo / demo","meaning":"Meskipun; sekalipun","explanation":"ても menyatakan bahwa hasil atau keputusan tidak berubah walaupun suatu keadaan terjadi. Berbeda dari のに, keadaan sebelum ても boleh berupa dugaan yang belum terjadi.","patterns":["Vて + も","Sifat-i: い → くても","Sifat-na / N + でも","V negatif: ない → なくても"],"note":"ここで でも menyambung kata benda atau sifat-na, bukan menawarkan contoh seperti お茶でも. Bentuk negatif yang benar 行かなくても, bukan 行かないくても.","examples":[{"jp":"雨が降っても、行きます。","kana":"あめ が ふって も、いきます。","meaning":"Meskipun hujan, saya akan pergi."},{"jp":"高くても、必要なら買います。","kana":"たかくて も、ひつよう なら かいます。","meaning":"Sekalipun mahal, kalau perlu saya akan membelinya."}],"level":"N4","enrichment":false,"order":70,"sources":[{"id":"master","page":236},{"id":"master","page":237},{"id":"master","page":238},{"id":"all","page":46},{"id":"rangkuman","page":41},{"id":"rangkuman","page":46}],"searchTerms":[]},{"id":"n4-shi","concept":"shi","category":"connectors","subcategory":"Beberapa alasan atau sifat","title":"～し、～し","kana":"し","romaji":"shi","meaning":"Selain … juga …; menyebut beberapa alasan","explanation":"し menyusun beberapa sifat, fakta, atau alasan. Penggunaannya memberi kesan masih ada hal lain yang dapat ditambahkan. Tidak menetapkan urutan kejadian.","patterns":["Bentuk biasa + し","Sifat-na / N + だし","Bentuk sopan + し"],"note":"Boleh memakai satu し ketika alasan lain sudah tersirat. ～たり pada N5 menyebut contoh kegiatan, sedangkan ～し dapat menghubungkan alasan atau penilaian.","examples":[{"jp":"この店は安いし、おいしいし、よく来ます。","kana":"この みせ は やすい し、おいしい し、よく きます。","meaning":"Karena toko ini murah dan enak, saya sering datang."},{"jp":"今日は休みだし、ゆっくりしましょう。","kana":"きょう は やすみ だ し、ゆっくり しましょう。","meaning":"Hari ini juga libur, jadi ayo santai saja."}],"level":"N4","enrichment":false,"order":71,"sources":[{"id":"master","page":174},{"id":"master","page":175},{"id":"master","page":176},{"id":"all","page":9},{"id":"all","page":10},{"id":"rangkuman","page":47}],"searchTerms":[]},{"id":"n4-te-cause","concept":"te-cause","category":"connectors","subcategory":"Sebab dan akibat alami","title":"～て・～で（原因）","kana":"て・で","romaji":"te / de","meaning":"Karena suatu keadaan, hasil tertentu terjadi","explanation":"Bentuk て／で dapat menghubungkan penyebab dengan akibat seperti perasaan, keadaan, atau ketidakmampuan. Bagian akhir lazim berupa hasil yang timbul secara alami, bukan niat, perintah, atau ajakan.","patterns":["Vて / Vなくて、hasil","Sifat-i: い → くて、hasil","Sifat-na / N + で、hasil"],"note":"Ini fungsi sebab, bukan sekadar rangkaian tindakan atau penyambung sifat pada N5. Untuk alasan yang diikuti ajakan, gunakan から／ので.","examples":[{"jp":"ニュースを聞いて、びっくりしました。","kana":"ニュース を きいて、びっくり しました。","meaning":"Saya terkejut karena mendengar berita itu."},{"jp":"道が混んでいて、遅れました。","kana":"みち が こんで いて、おくれました。","meaning":"Saya terlambat karena jalanan macet."}],"level":"N4","enrichment":false,"order":72,"sources":[{"id":"master","page":203},{"id":"master","page":204},{"id":"all","page":6},{"id":"all","page":14},{"id":"all","page":15}],"searchTerms":[]},{"id":"n4-noni-purpose","concept":"noni-purpose","category":"connectors","subcategory":"Fungsi dan kebutuhan","title":"～のに（用途）","kana":"のに","romaji":"noni","meaning":"Untuk melakukan; dalam melakukan","explanation":"V kamus＋のに menjadikan kegiatan sebagai sasaran fungsi, penilaian kegunaan, atau kebutuhan biaya dan waktu. Setelahnya sering muncul 使う, 便利, 必要, atau かかる.","patterns":["V kamus + のに + 使います / 便利です","V kamus + のに + waktu / biaya + かかります"],"note":"Jangan samakan dengan のに yang berarti padahal. 本を読むのに便利 berarti berguna untuk membaca buku.","examples":[{"jp":"この道具は野菜を切るのに使います。","kana":"この どうぐ は やさい を きる のに つかいます。","meaning":"Alat ini dipakai untuk memotong sayuran."},{"jp":"駅まで歩くのに十分かかります。","kana":"えき まで あるく のに じゅっぷん かかります。","meaning":"Berjalan ke stasiun membutuhkan sepuluh menit."}],"level":"N4","enrichment":false,"order":73,"sources":[{"id":"master","page":143},{"id":"master","page":144},{"id":"all","page":41},{"id":"rangkuman","page":12}],"check":{"prompt":"Apa fungsi のに dalam この道具は切るのに使います？","options":["Padahal.","Untuk memotong."],"answer":1,"explanation":"使います menjelaskan kegunaan alat, sehingga のに berarti untuk."},"searchTerms":[]},{"id":"n4-soredemo","concept":"soredemo","category":"connectors","subcategory":"Tetap berlawanan","title":"それでも","kana":"それでも","romaji":"soredemo","meaning":"Meskipun begitu; tetap saja","explanation":"それでも menghubungkan kalimat sebelumnya dengan tindakan atau hasil yang tetap terjadi meskipun ada hambatan. Menyoroti bahwa keadaan sebelumnya tidak mengubah hasil.","patterns":["Kalimat A。それでも、kalimat B。"],"note":"Berbeda dari それで yang berarti karena itu. でも sebagai kata penghubung dasar sudah ada di N5; それでも menambahkan makna tetap demikian walaupun ada keadaan tadi.","examples":[{"jp":"昨日はよく寝ました。それでも、まだ眠いです。","kana":"きのう は よく ねました。それでも、まだ ねむい です。","meaning":"Kemarin saya tidur cukup. Meskipun begitu, saya masih mengantuk."},{"jp":"難しいです。それでも、やってみます。","kana":"むずかしい です。それでも、やって みます。","meaning":"Ini sulit. Meski begitu, saya akan mencobanya."}],"level":"N4","enrichment":false,"order":74,"sources":[{"id":"master","page":179},{"id":"master","page":180}],"searchTerms":[]},{"id":"n4-soreni","concept":"soreni","category":"connectors","subcategory":"Tambahan alasan","title":"それに・そのうえ","kana":"それに・そのうえ","romaji":"soreni / sonoue","meaning":"Selain itu; ditambah lagi","explanation":"それに dan そのうえ menambahkan fakta yang memperkuat arah penilaian sebelumnya. Kedua informasi biasanya sama-sama mendukung kesan baik atau sama-sama menunjukkan masalah.","patterns":["Kalimat A。それに、kalimat B。","Kalimat A。そのうえ、kalimat B。"],"note":"そして pada N5 menghubungkan informasi secara umum. それに／そのうえ lebih menonjolkan tambahan yang menguatkan.","examples":[{"jp":"この部屋は広いです。それに、明るいです。","kana":"この へや は ひろい です。それに、あかるい です。","meaning":"Kamar ini luas. Selain itu, terang."},{"jp":"雨が降っていました。そのうえ、風も強かったです。","kana":"あめ が ふって いました。そのうえ、かぜ も つよかった です。","meaning":"Saat itu hujan. Ditambah lagi, anginnya kencang."}],"level":"N4","enrichment":false,"order":75,"sources":[{"id":"all","page":48}],"searchTerms":[]},{"id":"n4-embedded-ka","concept":"embedded-ka","category":"connectors","subcategory":"Pertanyaan dalam kalimat","title":"疑問詞＋～か","kana":"ぎもんしとか","romaji":"gimonshitoka","meaning":"Menyisipkan isi pertanyaan ke dalam kalimat","explanation":"Pertanyaan dengan kata tanya dapat menjadi bagian dari kalimat lebih besar. Gunakan bentuk biasa lalu か; setelahnya dapat diikuti わかる, 知る, 調べる, atau 教える. Tidak memakai ですか di dalam bagian pertanyaan itu.","patterns":["Kata tanya + V / sifat-i bentuk biasa + か","Kata tanya + sifat-na / N（tanpa だ）+ か"],"note":"これは 何か berbeda konteks dengan 何かありますか pada N5. Materi ini menempatkan isi pertanyaan seperti di mana tinggal sebagai satu bagian kalimat.","examples":[{"jp":"会議が何時に始まるか、教えてください。","kana":"かいぎ が なんじ に はじまる か、おしえて ください。","meaning":"Tolong beri tahu rapat mulai pukul berapa."},{"jp":"どの店が安いか、調べます。","kana":"どの みせ が やすい か、しらべます。","meaning":"Saya akan mencari tahu toko mana yang murah."}],"level":"N4","enrichment":false,"order":76,"sources":[{"id":"all","page":39},{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-ka-douka","concept":"ka-douka","category":"connectors","subcategory":"Apakah atau tidak","title":"～かどうか","kana":"かどうか","romaji":"kadouka","meaning":"Apakah suatu hal benar atau tidak","explanation":"かどうか memasukkan pertanyaan ya/tidak ke dalam kalimat lain. Tidak memerlukan kata tanya seperti いつ atau どこ. Setelah bagian itu, katakan apakah sudah tahu, akan memeriksa, atau masih belum jelas.","patterns":["V / sifat-i bentuk biasa + かどうか","Sifat-na / N（tanpa だ）+ かどうか"],"note":"Untuk pertanyaan dengan kata tanya, cukup gunakan ～か. Jangan menulis どこかどうか ketika maksudnya di mana.","examples":[{"jp":"明日行けるかどうか、まだわかりません。","kana":"あした いける か どう か、まだ わかりません。","meaning":"Saya belum tahu apakah besok bisa pergi atau tidak."},{"jp":"この店が日曜日も開いているかどうか、確認します。","kana":"この みせ が にちようび も あいて いる か どう か、かくにん します。","meaning":"Saya akan memastikan apakah toko ini juga buka hari Minggu."}],"level":"N4","enrichment":false,"order":77,"sources":[{"id":"master","page":67},{"id":"master","page":68},{"id":"all","page":38},{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-to-omou","concept":"to-omou","category":"connectors","subcategory":"Pendapat dan perkiraan","title":"～と思う","kana":"とおもう","romaji":"toomou","meaning":"Berpikir bahwa; berpendapat","explanation":"と diikuti 思う menyatakan isi pikiran atau penilaian. Bagian yang dipikirkan memakai bentuk biasa. Kata benda dan sifat-na positif masa kini memerlukan だ sebelum と.","patterns":["V / sifat-i bentuk biasa + と思います","Sifat-na / N + だと思います"],"note":"Untuk niat melakukan, pakai bentuk kehendak＋と思う. 行くと思う berarti mengira akan pergi, sedangkan 行こうと思う berarti berniat pergi.","examples":[{"jp":"この方法がいいと思います。","kana":"この ほうほう が いい と おもいます。","meaning":"Saya rasa cara ini bagus."},{"jp":"明日は雨だと思います。","kana":"あした は あめ だ と おもいます。","meaning":"Saya kira besok hujan."}],"level":"N4","enrichment":false,"order":78,"sources":[{"id":"master","page":252},{"id":"master","page":253},{"id":"rangkuman","page":45}],"searchTerms":[]},{"id":"n4-toiu-label","concept":"toiu-label","category":"connectors","subcategory":"Nama dan sebutan","title":"～というN・～っていうN","kana":"という・っていう","romaji":"toiu / tteiu","meaning":"Benda atau hal yang bernama atau disebut …","explanation":"という menghubungkan nama, sebutan, atau istilah dengan jenis bendanya. Bentuk percakapan ～っていう／～って memiliki fungsi serupa untuk memberi label.","patterns":["Nama / sebutan + という + N","Nama / sebutan + っていう + N"],"note":"Ini perluasan menjadi keterangan kata benda, berbeda dari ～と言います pada N5 untuk mengutip ucapan atau memperkenalkan nama. Bentuk って lebih santai.","examples":[{"jp":"「いろどり」という本を使っています。","kana":"いろどり と いう ほん を つかって います。","meaning":"Saya memakai buku yang berjudul Irodori."},{"jp":"おにぎりっていう食べ物を知っていますか。","kana":"おにぎり って いう たべもの を しって います か。","meaning":"Apakah kamu tahu makanan yang disebut onigiri?"}],"level":"N4","enrichment":false,"order":79,"sources":[{"id":"master","page":243},{"id":"master","page":244},{"id":"master","page":245},{"id":"master","page":261},{"id":"master","page":262},{"id":"all","page":34}],"searchTerms":[]},{"id":"n4-toiu-koto","concept":"toiu-koto","category":"connectors","subcategory":"Isi suatu hal","title":"～ということ","kana":"ということ","romaji":"toiukoto","meaning":"Hal bahwa; isi yang dimaksud","explanation":"ということ membungkus isi kalimat sebagai hal yang dibicarakan. Dipakai untuk menjelaskan informasi, memahami maksud, atau menyampaikan bahwa suatu fakta diketahui.","patterns":["V / sifat-i bentuk biasa + ということ","Sifat-na / N + だということ"],"note":"Jangan menyamakan semua こと dengan pola ini. Vこと pada N5 membendakan kegiatan; ～ということ di sini merangkum isi pernyataan.","examples":[{"jp":"試験が来週だということを知りませんでした。","kana":"しけん が らいしゅう だ と いう こと を しりません でした。","meaning":"Saya tidak tahu bahwa ujiannya minggu depan."},{"jp":"つまり、今日は休みだということですね。","kana":"つまり、きょう は やすみ だ と いう こと です ね。","meaning":"Jadi maksudnya hari ini libur, ya."}],"level":"N4","enrichment":false,"order":80,"sources":[{"id":"master","page":246},{"id":"master","page":247}],"searchTerms":[]},{"id":"n4-toittemo-ii","concept":"toittemo-ii","category":"connectors","subcategory":"Penilaian yang dapat dikatakan","title":"～と言ってもいい","kana":"といってもいい","romaji":"toittemoii","meaning":"Boleh dikatakan; bisa dibilang","explanation":"Pola ini menilai bahwa suatu pernyataan layak atau tidak berlebihan untuk diucapkan. Pembicara menyatakan kesimpulan dengan ungkapan boleh dikatakan, bukan meminta izin sungguhan untuk berbicara.","patterns":["Bentuk biasa + と言ってもいい"],"note":"Berbeda dari izin tindakan Vてもいい. Isi kalimat sebelum と adalah penilaian yang ingin disampaikan.","examples":[{"jp":"この町は第二の故郷だと言ってもいいです。","kana":"この まち は だいに の ふるさと だ と いって も いい です。","meaning":"Kota ini bisa dibilang kampung halaman kedua saya."},{"jp":"準備は終わったと言ってもいいでしょう。","kana":"じゅんび は おわった と いって も いい でしょう。","meaning":"Boleh dikatakan persiapannya sudah selesai."}],"level":"N4","enrichment":false,"order":81,"sources":[{"id":"master","page":241},{"id":"master","page":242}],"searchTerms":[]},{"id":"n4-toka","concept":"toka","category":"connectors","subcategory":"Contoh yang tidak lengkap","title":"～とか～とか","kana":"とか","romaji":"toka","meaning":"Seperti A dan B; menyebut beberapa contoh","explanation":"とか menyebut anggota contoh tanpa membuat daftar lengkap. Lazim dalam percakapan. Dapat mengikuti kata benda maupun bentuk biasa untuk memberikan contoh kegiatan atau keadaan.","patterns":["N + とか + N + とか","Bentuk biasa + とか + bentuk biasa + とか"],"note":"や pada N5 terutama menghubungkan contoh kata benda. とか lebih berciri percakapan dan dapat dipakai pada contoh berbentuk klausa.","examples":[{"jp":"週末は本を読むとか、映画を見るとかしています。","kana":"しゅうまつ は ほん を よむ とか、えいが を みる とか して います。","meaning":"Saat akhir pekan, saya melakukan hal seperti membaca buku atau menonton film."},{"jp":"お茶とか水とかがあります。","kana":"おちゃ とか みず とか が あります。","meaning":"Ada minuman seperti teh dan air."}],"level":"N4","enrichment":false,"order":82,"sources":[{"id":"master","page":254},{"id":"master","page":255},{"id":"all","page":7},{"id":"rangkuman","page":11}],"searchTerms":[]},{"id":"n4-matawa","concept":"matawa","category":"connectors","subcategory":"Alternatif dalam petunjuk","title":"または","kana":"または","romaji":"mataha","meaning":"Atau; pilihan satu di antara alternatif","explanation":"または menghubungkan pilihan yang dapat dipakai sebagai alternatif. Lebih lazim dalam petunjuk tertulis, pengumuman, atau penjelasan resmi daripada percakapan santai.","patterns":["A + または + B"],"note":"AかB sebagai pilihan dasar sudah ada di N5. または digunakan di sini untuk gaya petunjuk yang lebih formal; bukan berarti kedua pilihan harus dilakukan sekaligus.","examples":[{"jp":"鉛筆またはペンで書いてください。","kana":"えんぴつ または ペン で かいて ください。","meaning":"Tulislah dengan pensil atau pena."},{"jp":"月曜日または火曜日に来てください。","kana":"げつようび または かようび に きて ください。","meaning":"Datanglah pada hari Senin atau Selasa."}],"level":"N4","enrichment":false,"order":83,"sources":[{"id":"master","page":103},{"id":"master","page":104}],"searchTerms":[]},{"id":"n4-tokorode","concept":"tokorode","category":"connectors","subcategory":"Mengalihkan topik","title":"ところで","kana":"ところで","romaji":"tokorode","meaning":"Ngomong-ngomong; beralih ke topik lain","explanation":"ところで memperkenalkan topik baru yang tidak harus menjadi akibat atau kelanjutan langsung dari kalimat sebelumnya. Lazim dipakai untuk beralih pembicaraan dengan tetap menyapa lawan bicara.","patterns":["Pembicaraan sebelumnya。ところで、topik baru。"],"note":"Bedakan dari それで yang melanjutkan akibat atau meminta kelanjutan cerita. Jangan memotong pembicaraan penting secara tiba-tiba hanya dengan kata ini.","examples":[{"jp":"ところで、明日の会議は何時ですか。","kana":"ところで、あした の かいぎ は なんじ です か。","meaning":"Ngomong-ngomong, rapat besok pukul berapa?"},{"jp":"ところで、もう昼ご飯を食べましたか。","kana":"ところで、もう ひるごはん を たべました か。","meaning":"Ngomong-ngomong, apakah kamu sudah makan siang?"}],"level":"N4","enrichment":false,"order":84,"sources":[{"id":"all","page":49}],"searchTerms":[]},{"id":"n4-tatoeba","concept":"tatoeba","category":"connectors","subcategory":"Memberi contoh konkret","title":"例えば","kana":"たとえば","romaji":"tatoeba","meaning":"Misalnya; sebagai contoh","explanation":"例えば membuka contoh konkret untuk membantu menjelaskan pernyataan umum. Sesudahnya, sebutkan contoh yang benar-benar termasuk dalam kelompok atau gagasan tadi.","patterns":["Pernyataan umum。例えば、contoh。"],"note":"Bedakan dari とか／や yang menyusun anggota daftar. 例えば dapat memperkenalkan satu kalimat contoh lengkap.","examples":[{"jp":"果物が好きです。例えば、りんごやみかんです。","kana":"くだもの が すき です。たとえば、りんご や みかん です。","meaning":"Saya suka buah-buahan, misalnya apel dan jeruk."},{"jp":"例えば、こんな方法もあります。","kana":"たとえば、こんな ほうほう も あります。","meaning":"Sebagai contoh, ada juga cara seperti ini."}],"level":"N4","enrichment":false,"order":85,"sources":[{"id":"all","page":49}],"searchTerms":[]},{"id":"n4-sou-appearance","concept":"sou-appearance","category":"inference","subcategory":"Kesan dari pengamatan","title":"～そうだ（様態）","kana":"そうだ","romaji":"souda","meaning":"Kelihatannya; tampaknya akan","explanation":"そうだ ini menyatakan kesan dari hal yang terlihat atau tanda yang sedang diamati. Pada kata kerja, gunakan pangkal ます untuk menunjukkan sesuatu tampak akan terjadi. Pada sifat, buang い atau な terlebih dahulu.","patterns":["Vます: buang ます + そうです","Sifat-i: buang い + そうです","Sifat-na: tanpa な + そうです","～そうな + N / ～そうに + V"],"note":"いい→よさそう dan ない→なさそう. Jangan samakan おいしそう dengan おいしいそう: yang pertama kelihatannya enak, yang kedua katanya enak. Untuk sifat yang terlihat langsung seperti merah, biasanya tidak cukup sekadar menggantinya dengan そう.","examples":[{"jp":"雨が降りそうです。","kana":"あめ が ふりそう です。","meaning":"Kelihatannya akan hujan."},{"jp":"このケーキはおいしそうですね。","kana":"この ケーキ は おいしそう です ね。","meaning":"Kue ini kelihatannya enak, ya."}],"level":"N4","enrichment":false,"order":86,"sources":[{"id":"master","page":183},{"id":"master","page":184},{"id":"master","page":185},{"id":"master","page":186},{"id":"all","page":62},{"id":"rangkuman","page":48}],"table":{"headers":["Dasar","Kesan visual"],"rows":[["おいしい","おいしそう"],["元気","元気そう"],["いい","よさそう"],["ない","なさそう"],["雨が降ります","雨が降りそう"]]},"check":{"prompt":"Pilih “kelihatannya enak”.","options":["おいしそうです。","おいしいそうです。"],"answer":0,"explanation":"Kesan visual membuang い. Bentuk おいしいそう melaporkan kabar."},"searchTerms":["sou na","sou ni","そうな","そうに"]},{"id":"n4-sou-hearsay","concept":"sou-hearsay","category":"inference","subcategory":"Informasi yang didengar","title":"～そうだ（伝聞）","kana":"そうだ","romaji":"souda","meaning":"Katanya; menurut kabar yang diperoleh","explanation":"そうだ ini melaporkan informasi yang didengar atau dibaca, bukan kesan visual langsung. Pertahankan bentuk biasa kalimat asal, lalu tambahkan そうです. Sumber informasi dapat diperkenalkan dengan ～によると.","patterns":["V / sifat-i bentuk biasa + そうです","Sifat-na / N + だそうです","Isi + と聞きました / と言われています"],"note":"と聞きました menjelaskan bahwa pembicara mendengar isi itu; と言われています menyampaikan hal yang dikatakan secara umum. Ketiganya dibahas bersama sebagai cara melaporkan kabar, bukan kartu berulang.","examples":[{"jp":"天気予報によると、明日は雨だそうです。","kana":"てんきよほう に よる と、あした は あめ だ そう です。","meaning":"Menurut ramalan cuaca, katanya besok hujan."},{"jp":"この店は安いと聞きました。","kana":"この みせ は やすい と ききました。","meaning":"Saya mendengar bahwa toko ini murah."}],"level":"N4","enrichment":false,"order":87,"sources":[{"id":"master","page":181},{"id":"master","page":182},{"id":"master","page":248},{"id":"master","page":249},{"id":"master","page":250},{"id":"master","page":251},{"id":"all","page":63},{"id":"rangkuman","page":48}],"table":{"headers":["Kalimat asal","Melaporkan kabar"],"rows":[["雨が降る","雨が降るそうです"],["おいしい","おいしいそうです"],["元気だ","元気だそうです"],["休みだ","休みだそうです"]]},"check":{"prompt":"Pilih “katanya hari ini libur”.","options":["今日は休みそうです。","今日は休みだそうです。"],"answer":1,"explanation":"Kabar mempertahankan だ setelah kata benda."},"searchTerms":["to iwareteiru","to kiita","といわれている","ときいた"]},{"id":"n4-you-mitai","concept":"you-mitai","category":"inference","subcategory":"Dugaan dan kemiripan","title":"～ようだ・～みたいだ","kana":"ようだ・みたいだ","romaji":"youda / mitaida","meaning":"Sepertinya; mirip atau seperti","explanation":"ようだ menyatakan kesimpulan dari petunjuk yang ada atau kemiripan dengan sesuatu. みたいだ mempunyai penggunaan serupa dan lebih berciri percakapan. Bentuk sebelum kata benda menjadi ような／みたいな; sebelum tindakan menjadi ように／みたいに.","patterns":["V / sifat-i bentuk biasa + ようです","Sifat-na + なようです / N + のようです","V / sifat-i bentuk biasa + みたいです","Sifat-na / N（tanpa だ／な）+ みたいです"],"note":"Untuk ようだ, kata benda memakai の dan sifat-na memakai な. Untuk みたいだ, keduanya langsung diikuti みたい. Bedakan ように yang berarti seperti dari ように tujuan yang berarti agar.","examples":[{"jp":"誰もいないようです。","kana":"だれ も いない よう です。","meaning":"Sepertinya tidak ada siapa-siapa."},{"jp":"この雲は魚みたいな形ですね。","kana":"この くも は さかな みたいな かたち です ね。","meaning":"Awan ini bentuknya seperti ikan, ya."}],"level":"N4","enrichment":false,"order":88,"sources":[{"id":"master","page":105},{"id":"master","page":106},{"id":"master","page":107},{"id":"master","page":108},{"id":"master","page":109},{"id":"master","page":110},{"id":"master","page":277},{"id":"master","page":278},{"id":"master","page":279},{"id":"master","page":280},{"id":"all","page":60},{"id":"all","page":61},{"id":"rangkuman","page":47}],"table":{"headers":["Dasar","ようだ","みたいだ"],"rows":[["学生","学生のようだ","学生みたいだ"],["元気","元気なようだ","元気みたいだ"],["来る","来るようだ","来るみたいだ"]]},"check":{"prompt":"Pilih bentuk yang benar.","options":["学生なようです。","学生のようです。"],"answer":1,"explanation":"Kata benda memakai の sebelum ようです."},"searchTerms":["mitai na","mitai ni","you na","you ni","みたいな","みたいに","ような","ように"]},{"id":"n4-rashii","concept":"rashii","category":"inference","subcategory":"Kabar dan petunjuk tidak langsung","title":"～らしい","kana":"らしい","romaji":"rashii","meaning":"Kabarnya; tampaknya berdasarkan informasi","explanation":"らしい menyatakan dugaan berdasarkan informasi yang didapat atau petunjuk tidak langsung. Sering dapat diterjemahkan kabarnya atau tampaknya, dengan jarak antara pembicara dan kepastian faktanya.","patterns":["V / sifat-i bentuk biasa + らしいです","Sifat-na / N（tanpa だ）+ らしいです"],"note":"Ini penggunaan dugaan. Nらしい juga dapat berarti khas atau sesuai sifat N, tetapi fungsi itu perlu dibedakan dari melaporkan kabar.","examples":[{"jp":"駅の近くに新しい店ができるらしいです。","kana":"えき の ちかく に あたらしい みせ が できる らしい です。","meaning":"Kabarnya akan ada toko baru di dekat stasiun."},{"jp":"外の道がぬれています。雨が降ったらしいです。","kana":"そと の みち が ぬれて います。あめ が ふった らしい です。","meaning":"Jalan di luar basah. Tampaknya tadi hujan."}],"level":"N4","enrichment":false,"order":89,"sources":[{"id":"master","page":159},{"id":"master","page":160}],"searchTerms":[]},{"id":"n4-hazu","concept":"hazu","category":"inference","subcategory":"Kesimpulan beralasan","title":"～はずだ・～はずがない","kana":"はずだ・はずがない","romaji":"hazuda / hazuganai","meaning":"Seharusnya; tidak mungkin berdasarkan alasan","explanation":"はずだ menyampaikan kesimpulan yang dirasa masuk akal berdasarkan fakta atau jadwal. はずがない menolak kemungkinan karena bertentangan dengan informasi yang dipercaya. Ini penilaian beralasan, bukan kewajiban.","patterns":["V / sifat-i bentuk biasa + はずです","Sifat-na + なはずです / N + のはずです","Bentuk yang sama + はずがありません"],"note":"来ないはず berarti diperkirakan tidak datang. 来るはずがない berarti tidak mungkin datang. Jangan menerjemahkan semua はず sebagai harus.","examples":[{"jp":"電車は五時に着くはずです。","kana":"でんしゃ は ごじ に つく はず です。","meaning":"Menurut jadwal, keretanya seharusnya tiba pukul lima."},{"jp":"まだ子どもなので、車を運転できるはずがありません。","kana":"まだ こども な ので、くるま を うんてん できる はず が ありません。","meaning":"Karena masih anak-anak, tidak mungkin dia bisa mengemudikan mobil."}],"level":"N4","enrichment":false,"order":90,"sources":[{"id":"master","page":51},{"id":"master","page":52},{"id":"master","page":53},{"id":"master","page":54},{"id":"rangkuman","page":50}],"searchTerms":["hazu ga nai","はずがない"]},{"id":"n4-kamo","concept":"kamo","category":"inference","subcategory":"Kemungkinan","title":"～かもしれない","kana":"かもしれない","romaji":"kamoshirenai","meaning":"Mungkin; ada kemungkinan","explanation":"かもしれない menyebut suatu kemungkinan tanpa memastikannya. Bentuk sopannya かもしれません. Kata benda dan sifat-na positif masa kini tidak memakai だ sebelum pola ini.","patterns":["V / sifat-i bentuk biasa + かもしれません","Sifat-na / N（tanpa だ）+ かもしれません"],"note":"Tidak perlu memberi persentase kemungkinan tertentu. Konteks menentukan seberapa kuat dugaan pembicara.","examples":[{"jp":"明日は雪が降るかもしれません。","kana":"あした は ゆき が ふる かも しれません。","meaning":"Besok mungkin turun salju."},{"jp":"あの人は先生かもしれません。","kana":"あの ひと は せんせい かも しれません。","meaning":"Orang itu mungkin guru."}],"level":"N4","enrichment":false,"order":91,"sources":[{"id":"master","page":73},{"id":"master","page":74},{"id":"all","page":65},{"id":"rangkuman","page":45},{"id":"rangkuman","page":48}],"searchTerms":[]},{"id":"n4-darou","concept":"darou","category":"inference","subcategory":"Perkiraan dan konfirmasi","title":"～でしょう・～だろう","kana":"でしょう・だろう","romaji":"deshou / darou","meaning":"Barangkali; bukankah begitu?","explanation":"でしょう menyatakan perkiraan, sedangkan だろう adalah bentuk biasa yang lebih langsung. Dengan intonasi naik dan konteks bersama, でしょう juga dapat meminta persetujuan atau memastikan sesuatu.","patterns":["V / sifat-i bentuk biasa + でしょう","Sifat-na / N（tanpa だ）+ でしょう","Bentuk biasa yang sesuai + だろう"],"note":"Untuk N dan sifat-na masa kini, jangan menumpuk だ menjadi だでしょう. Bentuk konfirmasi dapat terdengar mendesak bila nadanya terlalu kuat.","examples":[{"jp":"午後は晴れるでしょう。","kana":"ごご は はれる でしょう。","meaning":"Siang nanti kemungkinan akan cerah."},{"jp":"この店、おいしいでしょう。","kana":"この みせ、おいしい でしょう。","meaning":"Makanan di toko ini enak, kan?"}],"level":"N4","enrichment":false,"order":92,"sources":[{"id":"all","page":64},{"id":"rangkuman","page":45}],"searchTerms":[]},{"id":"n4-ni-mieru","concept":"ni-mieru","category":"inference","subcategory":"Kesan penampilan","title":"～に見える","kana":"にみえる","romaji":"nimieru","meaning":"Tampak sebagai; terlihat berkesan","explanation":"に見える memberi penilaian tentang bagaimana seseorang atau sesuatu tampak. Kata benda atau sifat-na memakai に, sedangkan sifat-i diubah menjadi く.","patterns":["N / sifat-na + に見えます","Sifat-i: い → く見えます"],"note":"若く見える berarti tampak muda, bukan terlihatnya usia muda sebagai objek. Bedakan dari 海が見える yang menyatakan laut benar-benar terlihat.","examples":[{"jp":"このかばんは高く見えます。","kana":"この かばん は たかく みえます。","meaning":"Tas ini tampak mahal."},{"jp":"あの人は学生に見えます。","kana":"あの ひと は がくせい に みえます。","meaning":"Orang itu kelihatan seperti pelajar."}],"level":"N4","enrichment":false,"order":93,"sources":[{"id":"master","page":133},{"id":"master","page":134}],"searchTerms":["ni mieru"]},{"id":"n4-yasui","concept":"yasui","category":"morphology","subcategory":"Kemudahan tindakan","title":"～やすい","kana":"やすい","romaji":"yasui","meaning":"Mudah untuk dilakukan; mudah terjadi","explanation":"やすい ditambahkan pada pangkal ます untuk menunjukkan kemudahan melakukan tindakan atau kecenderungan suatu hal mudah terjadi. Hasil gabungannya berubah seperti kata sifat-i.","patterns":["Vます: buang ます + やすい","～やすかった / ～やすくない"],"note":"Ini bukan 安い yang berarti murah. 壊れやすい berarti mudah rusak, bukan mudah merusak sesuatu dengan sengaja.","examples":[{"jp":"このペンは書きやすいです。","kana":"この ペン は かきやすい です。","meaning":"Pena ini nyaman dan mudah dipakai menulis."},{"jp":"このコップは割れやすいので、気をつけてください。","kana":"この コップ は われやすい ので、き を つけて ください。","meaning":"Gelas ini mudah pecah, jadi hati-hati."}],"level":"N4","enrichment":false,"order":94,"sources":[{"id":"master","page":268},{"id":"master","page":269},{"id":"all","page":67},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-nikui-zurai","concept":"nikui-zurai","category":"morphology","subcategory":"Kesulitan tindakan","title":"～にくい・～づらい","kana":"にくい・づらい","romaji":"nikui / zurai","meaning":"Sulit atau tidak nyaman untuk dilakukan","explanation":"にくい menunjukkan tindakan sulit dilakukan karena sifat benda atau keadaan. づらい sering menyoroti kesulitan yang dirasakan pelaku, seperti rasa sakit, tidak nyaman, atau berat hati. Keduanya ditempelkan pada pangkal ます.","patterns":["Vます: buang ます + にくい","Vます: buang ます + づらい"],"note":"Gunakan pembeda ini sebagai kecenderungan, bukan aturan mutlak. Tulisan bakunya づらい, bukan ずらい.","examples":[{"jp":"この字は小さくて読みにくいです。","kana":"この じ は ちいさくて よみにくい です。","meaning":"Tulisan ini kecil sehingga sulit dibaca."},{"jp":"足が痛くて、歩きづらいです。","kana":"あし が いたくて、あるきづらい です。","meaning":"Kaki saya sakit sehingga berjalan terasa sulit."}],"level":"N4","enrichment":false,"order":95,"sources":[{"id":"master","page":137},{"id":"master","page":138},{"id":"master","page":292},{"id":"master","page":293},{"id":"all","page":67},{"id":"rangkuman","page":40}],"searchTerms":["nikui","zurai","づらい"]},{"id":"n4-sugiru","concept":"sugiru","category":"morphology","subcategory":"Keadaan berlebihan","title":"～すぎる","kana":"すぎる","romaji":"sugiru","meaning":"Terlalu; melewati batas yang sesuai","explanation":"すぎる menyatakan tindakan atau sifat yang berlebihan. Kata kerja memakai pangkal ます; sifat-i membuang い; sifat-na membuang な. Gabungannya berubah sebagai kata kerja golongan II.","patterns":["Vます: buang ます + すぎる","Sifat-i: buang い + すぎる","Sifat-na: tanpa な + すぎる"],"note":"いい→よすぎる. Bentuk negatif ない dapat menjadi なさすぎる. Kata ini menilai adanya kelebihan, bukan hanya menyatakan sangat.","examples":[{"jp":"昨日は食べすぎました。","kana":"きのう は たべすぎました。","meaning":"Kemarin saya makan terlalu banyak."},{"jp":"この部屋は静かすぎます。","kana":"この へや は しずかすぎます。","meaning":"Ruangan ini terlalu sepi."}],"level":"N4","enrichment":false,"order":96,"sources":[{"id":"all","page":66},{"id":"rangkuman","page":40},{"id":"rangkuman","page":49}],"searchTerms":[]},{"id":"n4-kata","concept":"kata","category":"morphology","subcategory":"Cara melakukan","title":"～方","kana":"かた","romaji":"kata","meaning":"Cara melakukan sesuatu","explanation":"方 mengubah pangkal kata kerja menjadi nama suatu cara melakukan tindakan. Kata benda yang tadinya objek を biasanya dihubungkan dengan の ketika menjadi bagian dari frasa cara.","patterns":["Vます: buang ます + 方","N + の + Vます tanpa ます + 方","する → し方"],"note":"漢字を書く menjadi 漢字の書き方. Untuk 使う, bentuknya 使い方; jangan langsung menambahkan 方 pada bentuk kamus.","examples":[{"jp":"この機械の使い方を教えてください。","kana":"この きかい の つかいかた を おしえて ください。","meaning":"Tolong ajari saya cara memakai mesin ini."},{"jp":"名前の読み方がわかりません。","kana":"なまえ の よみかた が わかりません。","meaning":"Saya tidak tahu cara membaca nama itu."}],"level":"N4","enrichment":false,"order":97,"sources":[{"id":"all","page":50},{"id":"rangkuman","page":40}],"searchTerms":[]},{"id":"n4-adjective-sa","concept":"adjective-sa","category":"morphology","subcategory":"Membendakan sifat","title":"～さ","kana":"さ","romaji":"sa","meaning":"Tingkat atau ukuran suatu sifat","explanation":"さ mengubah sifat menjadi kata benda yang menyatakan ukuran atau kadar sifat tersebut. Sifat-i membuang い, sedangkan sifat-na tidak memakai な.","patterns":["Sifat-i: buang い + さ","Sifat-na: tanpa な + さ"],"note":"いい berubah menjadi よさ. Bedakan 高さ ketinggian dengan 高い yang menerangkan bahwa sesuatu tinggi.","examples":[{"jp":"この山の高さはどのくらいですか。","kana":"この やま の たかさ は どのくらい です か。","meaning":"Berapa ketinggian gunung ini?"},{"jp":"この町の静かさが好きです。","kana":"この まち の しずかさ が すき です。","meaning":"Saya menyukai ketenangan kota ini."}],"level":"N4","enrichment":false,"order":98,"sources":[{"id":"master","page":161},{"id":"master","page":162}],"searchTerms":[]},{"id":"n4-garu","concept":"garu","category":"morphology","subcategory":"Tanda perasaan orang lain","title":"～がる・～たがる","kana":"がる・たがる","romaji":"garu / tagaru","meaning":"Menunjukkan perasaan; tampak ingin melakukan","explanation":"がる dipakai ketika perilaku orang lain menunjukkan perasaan atau keinginan. Sifat perasaan membuang い／な lalu menambah がる. Bentuk たい menjadi たがる untuk tanda ingin melakukan. ～がっている／～たがっている menjelaskan tanda yang sedang terlihat.","patterns":["Sifat perasaan tanpa い／な + がる","Vます tanpa ます + たがる","～がり: sebutan kecenderungan orang"],"note":"暑がり berarti orang yang mudah merasa panas; jangan membuat ～がり dari semua sifat secara bebas. Ketika berbicara tentang keinginan sendiri, pola たい pada N5 tetap digunakan.","examples":[{"jp":"子どもが犬を怖がっています。","kana":"こども が いぬ を こわがって います。","meaning":"Anak itu menunjukkan rasa takut kepada anjing."},{"jp":"弟は新しいゲームを買いたがっています。","kana":"おとうと は あたらしい ゲーム を かいたがって います。","meaning":"Adik tampak ingin membeli gim baru."}],"level":"N4","enrichment":false,"order":99,"sources":[{"id":"master","page":41},{"id":"master","page":42},{"id":"master","page":43},{"id":"master","page":44},{"id":"master","page":45},{"id":"master","page":46},{"id":"master","page":194},{"id":"master","page":195},{"id":"master","page":196}],"check":{"prompt":"弟は行きたがっています berarti …","options":["Adik tampak ingin pergi.","Saya ingin pergi."],"answer":0,"explanation":"たがっている menjelaskan tanda keinginan pihak lain."},"searchTerms":["gari","gatteiru","tagaru","がり","がっている","たがる"]},{"id":"n4-verb-stages","concept":"verb-stages","category":"morphology","subcategory":"Mulai sampai selesai","title":"～始める・～出す・～続ける・～終わる","kana":"はじめる・だす・つづける・おわる","romaji":"hajimeru / dasu / tsuzukeru / owaru","meaning":"Tahap mulai, mendadak mulai, berlanjut, atau selesai","explanation":"Kata kerja tambahan ini ditempelkan pada pangkal ます. 始める menandai awal secara umum; 出す sering menyoroti awal yang mendadak. 続ける menunjukkan tindakan berlanjut, sedangkan 終わる menunjukkan tindakan diselesaikan.","patterns":["Vます tanpa ます + 始める","Vます tanpa ます + 出す","Vます tanpa ます + 続ける","Vます tanpa ます + 終わる"],"note":"Jangan menganggap 出す dan 始める selalu sama. 泣き出す biasanya terdengar seperti mulai menangis tiba-tiba. Pelajari gabungan yang lazim dan cocok maknanya.","examples":[{"jp":"七時に勉強し始めました。","kana":"しちじ に べんきょう しはじめました。","meaning":"Saya mulai belajar pukul tujuh."},{"jp":"急に雨が降り出しました。","kana":"きゅう に あめ が ふりだしました。","meaning":"Tiba-tiba hujan mulai turun."},{"jp":"一時間歩き続けました。","kana":"いちじかん あるきつづけました。","meaning":"Saya terus berjalan selama satu jam."},{"jp":"やっと本を読み終わりました。","kana":"やっと ほん を よみおわりました。","meaning":"Akhirnya saya selesai membaca buku."}],"level":"N4","enrichment":false,"order":100,"sources":[{"id":"master","page":29},{"id":"master","page":30},{"id":"master","page":49},{"id":"master","page":50},{"id":"master","page":153},{"id":"master","page":154},{"id":"master","page":258},{"id":"master","page":259},{"id":"master","page":260},{"id":"all","page":68}],"searchTerms":["hajimeru","dasu","tsuzukeru","owaru","はじめる","だす","つづける","おわる"]},{"id":"n4-respect","concept":"respect","category":"polite","subcategory":"Meninggikan pihak lain","title":"尊敬語：お～になる・特別な動詞","kana":"そんけいご","romaji":"sonkeigo","meaning":"Menghormati tindakan pihak lain","explanation":"尊敬語 meninggikan orang yang melakukan tindakan, misalnya tamu atau guru. Banyak kata kerja memakai お＋pangkal ます＋になる. Beberapa kata mempunyai bentuk khusus yang perlu diingat sebagai satu kesatuan.","patterns":["お + Vます tanpa ます + になります","いる / 行く / 来る → いらっしゃいます","する → なさいます","言う → おっしゃいます"],"note":"Jangan pakai bentuk ini untuk meninggikan tindakan diri sendiri. Bentuk sopan khususnya いらっしゃいます／なさいます, bukan いらっしゃります／なさります.","examples":[{"jp":"先生は何時にいらっしゃいますか。","kana":"せんせい は なんじ に いらっしゃいます か。","meaning":"Guru akan datang pukul berapa?"},{"jp":"お客様はこの本をお読みになります。","kana":"おきゃくさま は この ほん を およみ に なります。","meaning":"Tamu akan membaca buku ini."}],"level":"N4","enrichment":false,"order":101,"sources":[{"id":"master","page":61},{"id":"master","page":62},{"id":"master","page":129},{"id":"master","page":130},{"id":"master","page":149},{"id":"master","page":150},{"id":"rangkuman","page":15},{"id":"rangkuman","page":19}],"table":{"headers":["Bentuk biasa","Hormat"],"rows":[["いる／行く／来る","いらっしゃいます"],["する","なさいます"],["言う","おっしゃいます"],["食べる／飲む","召し上がります（めしあがります）"],["見る","ご覧になります（ごらんになります）"]]},"searchTerms":["irassharu","nasaru","o ni naru","いらっしゃる","なさる","おになる"]},{"id":"n4-humble","concept":"humble","category":"polite","subcategory":"Merendahkan tindakan diri","title":"謙譲語：お～する・いたす","kana":"けんじょうご","romaji":"kenjougo","meaning":"Menyampaikan tindakan diri dengan rendah hati","explanation":"謙譲語 digunakan untuk tindakan diri atau pihak sendiri ketika berbicara kepada pihak yang dihormati. お＋pangkal ます＋する lazim dipakai ketika tindakan ditujukan kepada orang itu. Bentuk seperti いたします dan まいります menyampaikan tindakan diri secara resmi.","patterns":["お + Vます tanpa ます + します","する → いたします","行く / 来る → まいります","いる → おります","言う → 申します"],"note":"Jangan menggunakan bentuk rendah hati untuk menurunkan tindakan tamu. Beberapa gabungan memakai ご, misalnya ご説明します. Pelajari gabungan yang lazim, bukan menambahkan お／ご secara acak.","examples":[{"jp":"荷物をお持ちします。","kana":"にもつ を おもち します。","meaning":"Saya akan membawakan barang Anda."},{"jp":"明日、こちらから電話いたします。","kana":"あした、こちら から でんわ いたします。","meaning":"Besok pihak kami akan menelepon Anda."}],"level":"N4","enrichment":false,"order":102,"sources":[{"id":"master","page":63},{"id":"master","page":64},{"id":"rangkuman","page":19}],"table":{"headers":["Bentuk biasa","Rendah hati / resmi"],"rows":[["する","いたします"],["行く／来る","まいります"],["いる","おります"],["言う","申します（もうします）"],["見る","拝見します（はいけんします）"]]},"searchTerms":["itashimasu","mairimasu","orimasu","いたします","まいります","おります"]},{"id":"n4-gozaimasu","concept":"gozaimasu","category":"polite","subcategory":"Bentuk sangat sopan","title":"ございます・でございます","kana":"ございます・でございます","romaji":"gozaimasu / degozaimasu","meaning":"Ada; adalah dalam situasi resmi","explanation":"ございます merupakan bentuk sangat sopan dari あります untuk keberadaan benda atau hal. でございます digunakan sebagai bentuk resmi dari です setelah kata benda atau sifat-na. Lazim dalam layanan dan pengumuman.","patterns":["N が + ございます","N / sifat-na + でございます","ありません → ございません"],"note":"Jangan mengubah います untuk orang menjadi ございます. Untuk orang pihak sendiri gunakan おります; untuk pihak yang dihormati gunakan いらっしゃいます.","examples":[{"jp":"こちらが受付でございます。","kana":"こちら が うけつけ で ございます。","meaning":"Di sebelah sini adalah meja resepsionis."},{"jp":"お手洗いは二階にございます。","kana":"おてあらい は にかい に ございます。","meaning":"Toilet berada di lantai dua."}],"level":"N4","enrichment":false,"order":103,"sources":[{"id":"master","page":31},{"id":"master","page":32},{"id":"master","page":47},{"id":"master","page":48}],"check":{"prompt":"Untuk keberadaan benda dalam bahasa resmi …","options":["ございます","いらっしゃいます"],"answer":0,"explanation":"ございます berasal dari あります. いらっしゃいます digunakan untuk orang yang dihormati."},"searchTerms":["de gozaimasu","でございます"]},{"id":"n4-polite-request","concept":"polite-request","category":"polite","subcategory":"Meminta bantuan dengan sopan","title":"～ていただけませんか・お～ください","kana":"ていただけませんか・おください","romaji":"teitadakemasenka / okudasai","meaning":"Bisakah Anda berkenan melakukan …?","explanation":"～ていただけませんか meminta bantuan dengan menekankan penerimaan bantuan oleh pembicara. ～てくださいませんか memakai bentuk hormat pelaku. お＋pangkal ます＋ください adalah bentuk permintaan hormat yang lazim pada layanan atau petunjuk.","patterns":["Vて + いただけませんか","Vて + くださいませんか","Vて + もらえませんか / くれませんか","お + Vます tanpa ます + ください"],"note":"Bentuk dasar ～てください sudah ada di N5. Pilih ungkapan sesuai hubungan dan situasi; jangan menganggap semua permintaan dapat diberi tingkat sopan yang kaku tanpa konteks.","examples":[{"jp":"もう一度説明していただけませんか。","kana":"もう いちど せつめい して いただけません か。","meaning":"Bisakah Anda menjelaskannya sekali lagi?"},{"jp":"こちらでお待ちください。","kana":"こちら で おまち ください。","meaning":"Silakan menunggu di sini."}],"level":"N4","enrichment":false,"order":104,"sources":[{"id":"master","page":147},{"id":"master","page":148},{"id":"master","page":213},{"id":"master","page":214},{"id":"all","page":51}],"searchTerms":["o kudasai","te itadakemasen ka","te moraemasen ka","te kuremasen ka","te kudasaimasen ka"]},{"id":"n4-kana-kashira","concept":"kana-kashira","category":"expressions","subcategory":"Bertanya pada diri sendiri","title":"～かな・～かしら","kana":"かな・かしら","romaji":"kana / kashira","meaning":"Ya, kira-kira …; bertanya dalam hati","explanation":"かな dan かしら menambahkan rasa bertanya-tanya atau belum yakin, sering sebagai ucapan kepada diri sendiri. Lawan bicara boleh menanggapi, tetapi tidak selalu diminta menjawab secara langsung.","patterns":["Bentuk biasa + かな","Bentuk biasa + かしら"],"note":"かな umum dalam percakapan. かしら mempunyai kesan gaya tertentu dan sering diasosiasikan dengan tuturan feminin. Untuk pertanyaan formal, gunakan bentuk ですか／ますか yang sesuai.","examples":[{"jp":"明日は晴れるかな。","kana":"あした は はれる かな。","meaning":"Kira-kira besok cerah tidak, ya?"},{"jp":"この店、まだ開いているかしら。","kana":"この みせ、まだ あいて いる かしら。","meaning":"Toko ini masih buka tidak, ya?"}],"level":"N4","enrichment":false,"order":105,"sources":[{"id":"master","page":69},{"id":"master","page":70},{"id":"master","page":75},{"id":"master","page":76}],"searchTerms":["kana","kashira"]},{"id":"n4-kai","concept":"kai","category":"expressions","subcategory":"Pertanyaan akrab","title":"～かい","kana":"かい","romaji":"kai","meaning":"Akhiran pertanyaan ya/tidak yang akrab","explanation":"かい digunakan pada pertanyaan ya/tidak dalam gaya akrab. Sering terdengar dari orang yang lebih tua kepada anak atau orang dekat. Bukan pilihan netral untuk setiap percakapan.","patterns":["Kalimat bentuk biasa + かい"],"note":"Untuk pertanyaan dengan kata tanya, gaya akrab lain seperti ～だい dapat muncul. Pada percakapan dengan orang baru, bentuk sopan lebih aman.","examples":[{"jp":"もうご飯を食べたかい。","kana":"もう ごはん を たべた かい。","meaning":"Sudah makan belum?"},{"jp":"明日も来るかい。","kana":"あした も くる かい。","meaning":"Besok datang lagi?"}],"level":"N4","enrichment":false,"order":106,"sources":[{"id":"master","page":71},{"id":"master","page":72}],"searchTerms":[]},{"id":"n4-naa","concept":"naa","category":"expressions","subcategory":"Kesan spontan","title":"～なあ","kana":"なあ","romaji":"naa","meaning":"Wah; menyatakan kesan atau perasaan","explanation":"なあ menambahkan kesan pribadi seperti kagum, terharu, atau keluhan. Pembicara seolah mengungkapkan perasaan kepada diri sendiri. Nada suara sangat memengaruhi kesannya.","patterns":["Bentuk biasa + なあ"],"note":"Ini akhiran kalimat yang mempunyai fungsi, bukan kata seru kosong sebagai kartu Kotoba. Bedakan dari V kamus＋な yang merupakan larangan langsung.","examples":[{"jp":"この景色はきれいだなあ。","kana":"この けしき は きれい だ なあ。","meaning":"Wah, pemandangan ini indah sekali."},{"jp":"今日はよく歩いたなあ。","kana":"きょう は よく あるいた なあ。","meaning":"Hari ini banyak berjalan juga, ya."}],"level":"N4","enrichment":false,"order":107,"sources":[{"id":"all","page":78}],"searchTerms":[]},{"id":"n4-nakanaka","concept":"nakanaka","category":"expressions","subcategory":"Sulit mencapai hasil","title":"なかなか～ない","kana":"なかなかない","romaji":"nakanakanai","meaning":"Tidak juga; sulit atau lama untuk bisa terjadi","explanation":"なかなか bersama bentuk negatif menunjukkan hasil yang diharapkan belum tercapai meskipun sudah ada usaha atau waktu yang berlalu. Fokusnya pada sulitnya mencapai hasil, bukan larangan.","patterns":["なかなか + bentuk negatif"],"note":"なかなか tanpa negatif dapat memuji sesuatu sebagai cukup bagus, tetapi itu fungsi lain. Dalam pola ini, perhatikan adanya bentuk negatif.","examples":[{"jp":"漢字がなかなか覚えられません。","kana":"かんじ が なかなか おぼえられません。","meaning":"Saya sulit sekali menghafal kanji."},{"jp":"バスがなかなか来ません。","kana":"バス が なかなか きません。","meaning":"Busnya tidak kunjung datang."}],"level":"N4","enrichment":false,"order":108,"sources":[{"id":"master","page":119},{"id":"master","page":120}],"searchTerms":[]},{"id":"n4-yatto","concept":"yatto","category":"expressions","subcategory":"Hasil setelah usaha","title":"やっと","kana":"やっと","romaji":"yatto","meaning":"Akhirnya setelah menunggu atau berusaha","explanation":"やっと menyoroti hasil yang baru tercapai setelah usaha, kesulitan, atau penantian. Dapat pula menunjukkan sesuatu tercapai dengan pas-pasan.","patterns":["やっと + hasil / keadaan yang tercapai"],"note":"Jangan memakai やっと hanya untuk semua kejadian terakhir. Ada rasa sebelumnya sulit atau lama yang membedakannya dari urutan biasa.","examples":[{"jp":"やっと宿題が終わりました。","kana":"やっと しゅくだい が おわりました。","meaning":"Akhirnya tugas saya selesai."},{"jp":"このかばんは重くて、一人でやっと持てます。","kana":"この かばん は おもくて、ひとり で やっと もてます。","meaning":"Tas ini berat sehingga saya nyaris tidak mampu membawanya sendiri."}],"level":"N4","enrichment":false,"order":109,"sources":[{"id":"master","page":270},{"id":"master","page":271}],"searchTerms":[]},{"id":"n4-kitto","concept":"kitto","category":"expressions","subcategory":"Keyakinan dalam dugaan","title":"きっと","kana":"きっと","romaji":"kitto","meaning":"Pasti atau sangat mungkin menurut keyakinan","explanation":"きっと memperkuat perkiraan atau keyakinan pembicara. Sering muncul bersama でしょう atau と思います. Keyakinannya tetap merupakan penilaian, bukan jaminan bahwa kejadian itu akan terjadi.","patterns":["きっと + dugaan / keyakinan"],"note":"必ず sering dipakai untuk tindakan yang dipastikan, aturan, atau permintaan yang harus dipenuhi. きっと lebih dekat dengan saya yakin hal itu akan terjadi.","examples":[{"jp":"練習すれば、きっと上手になります。","kana":"れんしゅう すれば、きっと じょうず に なります。","meaning":"Kalau berlatih, saya yakin kamu akan makin mahir."},{"jp":"明日はきっといい天気でしょう。","kana":"あした は きっと いい てんき でしょう。","meaning":"Saya yakin besok cuacanya akan bagus."}],"level":"N4","enrichment":false,"order":110,"sources":[{"id":"master","page":79},{"id":"master","page":80}],"searchTerms":[]},{"id":"n4-zehi","concept":"zehi","category":"expressions","subcategory":"Keinginan dan ajakan kuat","title":"ぜひ","kana":"ぜひ","romaji":"zehi","meaning":"Sangat ingin; silakan dengan sungguh-sungguh","explanation":"ぜひ menegaskan keinginan, undangan, atau anjuran yang kuat. Lazim bersama ～たい, ～てください, atau ajakan. Maknanya menyoroti kesungguhan, bukan kepastian hasil.","patterns":["ぜひ + Vたい","ぜひ + Vてください"],"note":"Jangan gunakan ぜひ seolah-olah sama dengan きっと untuk meramal cuaca. ぜひ会いたい adalah keinginan, bukan perkiraan akan bertemu.","examples":[{"jp":"ぜひ日本へ行ってみたいです。","kana":"ぜひ にほん へ いって みたい です。","meaning":"Saya sangat ingin mencoba pergi ke Jepang."},{"jp":"ぜひ遊びに来てください。","kana":"ぜひ あそび に きて ください。","meaning":"Silakan datang berkunjung, saya sungguh berharap Anda datang."}],"level":"N4","enrichment":false,"order":111,"sources":[{"id":"master","page":288},{"id":"master","page":289}],"searchTerms":[]},{"id":"n4-sasuga","concept":"sasuga","category":"expressions","subcategory":"Hasil sesuai reputasi","title":"さすが","kana":"さすが","romaji":"sasuga","meaning":"Memang hebat; sesuai yang diharapkan","explanation":"さすが menunjukkan kekaguman karena hasil sesuai dengan kemampuan, pengalaman, atau reputasi yang sudah diketahui. Sering digunakan untuk memuji pencapaian seseorang.","patterns":["さすが + （N / penilaian）","さすがですね"],"note":"Bukan sekadar pengganti sangat. Ada hubungan antara hasil yang diamati dan harapan atau pengetahuan sebelumnya.","examples":[{"jp":"さすが先生ですね。説明がわかりやすいです。","kana":"さすが せんせい です ね。せつめい が わかりやすい です。","meaning":"Memang hebat, seperti yang diharapkan dari seorang guru. Penjelasannya mudah dipahami."},{"jp":"さすがプロです。とても速いです。","kana":"さすが プロ です。とても はやい です。","meaning":"Memang seorang profesional. Cepat sekali."}],"level":"N4","enrichment":false,"order":112,"sources":[{"id":"master","page":172},{"id":"master","page":173}],"searchTerms":[]},{"id":"n4-sonnani","concept":"sonnani","category":"expressions","subcategory":"Derajat yang dirujuk","title":"そんなに・こんなに・あんなに","kana":"そんなに・こんなに・あんなに","romaji":"sonnani / konnani / annani","meaning":"Sedemikian; sampai tingkat seperti ini atau itu","explanation":"こんなに, そんなに, dan あんなに menunjuk kadar atau jumlah yang terkait situasi. こんなに menyoroti tingkat yang dekat atau sedang dirasakan; そんなに merujuk hal yang disebut lawan bicara; あんなに mengacu hal yang terasa lebih jauh atau sama-sama diketahui.","patterns":["こんなに / そんなに / あんなに + sifat / tindakan"],"note":"そんなに～ない berarti tidak sampai sebegitunya. Bedakan dari そんなN yang langsung menerangkan jenis benda.","examples":[{"jp":"このかばんはそんなに高くありません。","kana":"この かばん は そんなに たかく ありません。","meaning":"Tas ini tidak semahal itu."},{"jp":"こんなにたくさん、ありがとうございます。","kana":"こんなに たくさん、ありがとう ございます。","meaning":"Terima kasih sudah memberi sebanyak ini."}],"level":"N4","enrichment":false,"order":113,"sources":[{"id":"master","page":177},{"id":"master","page":178}],"searchTerms":[]},{"id":"n4-kyuuni","concept":"kyuuni","category":"expressions","subcategory":"Perubahan mendadak","title":"急に","kana":"きゅうに","romaji":"kyuuni","meaning":"Tiba-tiba; secara mendadak","explanation":"急に menerangkan perubahan atau tindakan yang terjadi tanpa persiapan atau sangat mendadak. Dapat dipakai dengan perubahan cuaca, kondisi tubuh, atau perubahan rencana.","patterns":["急に + perubahan / tindakan"],"note":"Bukan berarti melakukan lebih cepat. Untuk menyuruh bergegas, gunakan 急いで; 急に menyoroti perubahan mendadak.","examples":[{"jp":"急に寒くなりました。","kana":"きゅう に さむく なりました。","meaning":"Tiba-tiba cuaca menjadi dingin."},{"jp":"急に予定が変わりました。","kana":"きゅう に よてい が かわりました。","meaning":"Rencananya tiba-tiba berubah."}],"level":"N4","enrichment":false,"order":114,"sources":[{"id":"master","page":96},{"id":"master","page":97}],"searchTerms":[]},{"id":"n4-janai-ka","concept":"janai-ka","category":"expressions","subcategory":"Mengajak konfirmasi","title":"～じゃないか・～ではないか","kana":"じゃないか・ではないか","romaji":"janaika / dehanaika","meaning":"Bukankah; ternyata …; ajakan tegas","explanation":"じゃないか dan ではないか dapat menekankan temuan atau mengajak lawan bicara mengakui sesuatu. Dalam bentuk kehendak＋ではないか, ungkapannya dapat menjadi ajakan. Makna bergantung nada dan konteks, bukan selalu pertanyaan negatif.","patterns":["Bentuk biasa + じゃないか / ではないか","V bentuk kehendak + ではないか"],"note":"Bentuk langsung ini dapat terdengar tegas. Untuk konfirmasi yang lebih lembut dalam percakapan akrab, ～じゃない？ juga umum. Jangan mengira setiap bentuknya berarti tidak.","examples":[{"jp":"ここにあるじゃないか。","kana":"ここ に ある じゃない か。","meaning":"Ternyata ada di sini, kan."},{"jp":"みんなで考えようではありませんか。","kana":"みんな で かんがえよう では ありません か。","meaning":"Mari kita pikirkan bersama."}],"level":"N4","enrichment":false,"order":115,"sources":[{"id":"master","page":35},{"id":"master","page":36},{"id":"master","page":65},{"id":"master","page":66}],"searchTerms":[]}];
function bunpoEntries(level=(typeof prefs!=='undefined'?prefs.level:'N5')){return level==='N4'?BUNPO_N4_DATA:BUNPO_DATA}
function bunpoCategories(level=(typeof prefs!=='undefined'?prefs.level:'N5')){return level==='N4'?BUNPO_N4_CATEGORIES:BUNPO_CATEGORIES}
